String _hpjMealDisplayName() {
  final user = supabase.auth.currentUser;
  if (user == null) return 'HPJ Member';

  final metadata = user.userMetadata ?? const <String, dynamic>{};

  for (final key in const <String>[
    'full_name',
    'display_name',
    'name',
  ]) {
    final value = metadata[key]?.toString().trim() ?? '';
    if (value.isNotEmpty) return value;
  }

  final first = metadata['first_name']?.toString().trim() ?? '';
  final last = metadata['last_name']?.toString().trim() ?? '';
  final combined = [first, last].where((value) => value.isNotEmpty).join(' ');
  if (combined.isNotEmpty) return combined;

  final email = user.email?.trim() ?? '';
  if (email.contains('@')) {
    final local = email.split('@').first.trim();
    if (local.isNotEmpty) return local;
  }

  return 'HPJ Member';
}

String _hpjMealRelativeTime(DateTime? value) {
  if (value == null) return 'Recently';
  final difference = DateTime.now().difference(value.toLocal());

  if (difference.inMinutes < 1) return 'Just now';
  if (difference.inMinutes < 60) return '${difference.inMinutes}m';
  if (difference.inHours < 24) return '${difference.inHours}h';
  if (difference.inDays < 7) return '${difference.inDays}d';

  return formatCustomerDateTime(value.toLocal());
}

String _hpjMealTypeLabel(String value) {
  final clean = value.trim().toLowerCase();
  switch (clean) {
    case 'breakfast':
      return 'Breakfast';
    case 'lunch':
      return 'Lunch';
    case 'snack':
      return 'Snack';
    case 'dinner':
    default:
      return 'Dinner';
  }
}

String _hpjMealDailyPrompt() {
  switch (DateTime.now().weekday) {
    case DateTime.monday:
      return 'Monday plate check — what started your week?';
    case DateTime.tuesday:
      return 'Taste of Tuesday — show Jamaica what is on your plate.';
    case DateTime.wednesday:
      return 'Midweek meal check — what did you cook today?';
    case DateTime.thursday:
      return 'Thursday table — share one meal from your day.';
    case DateTime.friday:
      return 'Friday food check — what are you eating tonight?';
    case DateTime.saturday:
      return 'Saturday kitchen — show us what is cooking.';
    case DateTime.sunday:
    default:
      return 'Sunday dinner — what is your family having today?';
  }
}

Future<List<HpjMealPost>> fetchHpjMealPulse({
  String filter = 'today',
  int limit = 40,
  int offset = 0,
}) async {
  final clean = filter.trim().toLowerCase();
  final mealType = const <String>{
    'breakfast',
    'lunch',
    'dinner',
    'snack',
  }.contains(clean)
      ? clean
      : '';

  final feedMode = clean == 'trending'
      ? 'trending'
      : clean == 'following'
          ? 'following'
          : clean == 'today'
              ? 'today'
              : 'all';

  try {
    final response = await supabase.rpc(
      'hpj_get_meal_feed',
      params: {
        'p_filter': feedMode,
        'p_meal_type': mealType,
        'p_limit': limit.clamp(1, 80),
        'p_offset': offset < 0 ? 0 : offset,
      },
    );

    return (response as List)
        .map(
          (row) => HpjMealPost.fromSupabase(
            Map<String, dynamic>.from(row as Map),
          ),
        )
        .where((item) => item.id.isNotEmpty)
        .toList(growable: false);
  } catch (error) {
    farmDebugLog('Meal Pulse feed unavailable: $error');
    return const <HpjMealPost>[];
  }
}

Future<HpjMealPost?> fetchHpjMealPostById(String postId) async {
  final clean = postId.trim();
  if (clean.isEmpty) return null;

  try {
    final response = await supabase.rpc(
      'hpj_get_meal_post',
      params: <String, dynamic>{'p_post_id': clean},
    );
    if (response is! List || response.isEmpty) return null;
    return HpjMealPost.fromSupabase(
      Map<String, dynamic>.from(response.first as Map),
    );
  } catch (error) {
    farmDebugLog('Shared Meal Pulse post unavailable: $error');
    return null;
  }
}

Future<List<HpjMealIngredientPulse>> fetchHpjMealIngredientPulse({
  int days = 7,
  int limit = 10,
}) async {
  try {
    final response = await supabase.rpc(
      'hpj_get_meal_ingredient_pulse',
      params: {
        'p_days': days.clamp(1, 30),
        'p_limit': limit.clamp(1, 25),
      },
    );

    return (response as List)
        .map(
          (row) => HpjMealIngredientPulse.fromSupabase(
            Map<String, dynamic>.from(row as Map),
