class _HpjMealFilterBar extends StatelessWidget {
  final List<String> filters;
  final String selected;
  final void Function(String value) onSelected;
  final bool compact;

  const _HpjMealFilterBar({
    required this.filters,
    required this.selected,
    required this.onSelected,
    this.compact = false,
  });

  @override
  Widget build(BuildContext context) {
    return SizedBox(
      height: compact ? 38 : 42,
      child: ListView.separated(
        scrollDirection: Axis.horizontal,
        itemCount: filters.length,
        separatorBuilder: (_, __) => const SizedBox(width: 7),
        itemBuilder: (context, index) {
          final value = filters[index];
          final active = selected == value;
          final label = value == 'today'
              ? 'Today'
              : value == 'following'
                  ? 'Following'
                  : value == 'trending'
                      ? 'Trending'
                      : _hpjMealTypeLabel(value);

          return ChoiceChip(
            label: Text(label),
            selected: active,
            showCheckmark: false,
            onSelected: (_) => onSelected(value),
            selectedColor: FarmColors.primary,
            backgroundColor: Colors.white,
            side: BorderSide(
              color: active ? FarmColors.primary : FarmColors.line,
            ),
            padding: compact
                ? const EdgeInsets.symmetric(horizontal: 8, vertical: 2)
                : null,
            labelStyle: TextStyle(
              color: active ? Colors.white : FarmColors.deepGreen,
              fontSize: compact ? 9.5 : 10.2,
              fontWeight: FontWeight.w900,
            ),
          );
        },
      ),
    );
  }
}

