// HPJ PARISH-FIRST MARKETPLACE
// "Parish first, Jamaica always": selected-parish farms and produce
// are ranked first, but Jamaica-wide supply remains available.
final ValueNotifier<String> hpjCustomerParishPreference =
    ValueNotifier<String>('St. Elizabeth');

String _hpjParishPreferenceKey(String value) => value
    .trim()
    .toLowerCase()
    .replaceAll('saint ', 'st ')
    .replaceAll('.', '')
    .replaceAll(' parish', '')
    .replaceAll(RegExp(r'\s+'), ' ');

bool _hpjFarmMatchesParishPreference(
  FarmPublicProfileRecord farm,
  String parish,
) {
  final target = _hpjParishPreferenceKey(parish);
  if (target.isEmpty) return false;

  final location = _hpjParishPreferenceKey(farm.locationLine);
  return location.isNotEmpty && location.contains(target);
}

bool _hpjProductMatchesParishPreference(
  Product product,
  String parish,
) {
  final target = _hpjParishPreferenceKey(parish);
  if (target.isEmpty) return false;

  final productParish =
      _hpjParishPreferenceKey((product.parish ?? '').trim());

  return productParish.isNotEmpty && productParish == target;
}

List<FarmPublicProfileRecord> _hpjPrioritizeFarmsByParish(
  List<FarmPublicProfileRecord> source,
  String parish,
) {
  final rows = source.asMap().entries.toList(growable: false);

  rows.sort((a, b) {
    final aLocal = _hpjFarmMatchesParishPreference(a.value, parish);
    final bLocal = _hpjFarmMatchesParishPreference(b.value, parish);
    if (aLocal != bLocal) return aLocal ? -1 : 1;
    return a.key.compareTo(b.key);
  });

  return rows.map((entry) => entry.value).toList(growable: false);
}

List<Product> _hpjPrioritizeProductsByParish(
  List<Product> source,
  String parish,
) {
  final rows = source.asMap().entries.toList(growable: false);

  rows.sort((a, b) {
    final aLocal = _hpjProductMatchesParishPreference(a.value, parish);
    final bLocal = _hpjProductMatchesParishPreference(b.value, parish);
    if (aLocal != bLocal) return aLocal ? -1 : 1;
    return a.key.compareTo(b.key);
  });

  return rows.map((entry) => entry.value).toList(growable: false);
}

