String normalizeCategoryKey(String? value) {
  final clean = (value ?? '').trim().toLowerCase();

  switch (clean) {
    case 'fruit':
    case 'fruits':
      return 'fruits';
    case 'vegetable':
    case 'vegetables':
      return 'vegetables';
    case 'ground provision':
    case 'ground provisions':
      return 'ground provisions';
    case 'herb':
    case 'herbs':
      return 'herbs';
    case 'egg':
    case 'eggs':
      return 'eggs';
    case 'prepared food':
    case 'prepared foods':
      return 'prepared foods';
    case 'all':
      return 'all';
    default:
      return clean;
  }
}

String displayCategoryLabel(String? value) {
  switch (normalizeCategoryKey(value)) {
    case 'fruits':
      return 'Fruits';
    case 'vegetables':
      return 'Vegetables';
    case 'ground provisions':
      return 'Ground Provisions';
    case 'herbs':
      return 'Herbs';
    case 'eggs':
      return 'Eggs';
    case 'prepared foods':
      return 'Prepared Foods';
    case 'all':
      return 'All';
    default:
      final clean = (value ?? '').trim();
      return clean.isEmpty ? 'Other' : clean;
  }
}

String _cleanReviewNameCandidate(String? value) {
  final clean = (value ?? '').trim().replaceAll(RegExp(r'\s+'), ' ');
  if (clean.isEmpty) return '';

  final lower = clean.toLowerCase();
  if (lower == 'null' ||
      lower == 'undefined' ||
      lower == 'unknown' ||
      lower == 'test' ||
      lower == 'demo') {
    return '';
  }

  if (_looksLikeEmailAddress(clean)) return '';
  if (clean.length > 60) return clean.substring(0, 60).trim();
  return clean;
}

Future<String> currentReviewCustomerName() async {
  final user = supabase.auth.currentUser;
  String? profileName;

  try {
    final profile = await fetchCurrentCustomerProfile();
    profileName = profile?.fullName;
  } catch (_) {
    profileName = null;
  }

  final metadata = user?.userMetadata ?? const <String, dynamic>{};
  final metadataName =
      (metadata['full_name'] ?? metadata['name'] ?? metadata['display_name'])
          ?.toString();

  return safeReviewDisplayName(
    profileName: profileName,
    metadataName: metadataName,
    email: user?.email,
  );
}


