// ============================================================================
// HPJ PHASE 91 — GROWTOGETHER / HARVEST CIRCLES
// Customer demand is captured before harvest and shown back to farmers as
// Grow Signals. Social follows stay separate from real reservations.
// ============================================================================

class HpjHarvestCircle {
  final String id;
  final String productId;
  final String productName;
  final String category;
  final String imageUrl;
  final String farmName;
  final String farmerName;
  final String parish;
  final String unit;
  final double targetQuantity;
  final DateTime? harvestStart;
  final DateTime? harvestEnd;
  final String description;
  final String status;
  final bool featured;
  final double reservedQuantity;
  final int householdCount;
  final int followerCount;
  final double supplyCommitted;
  final int farmerCount;
  final String myCommitmentType;
  final double myQuantity;
  final int myRepeatWeeks;

  const HpjHarvestCircle({
    required this.id,
    required this.productId,
    required this.productName,
    required this.category,
    required this.imageUrl,
    required this.farmName,
    required this.farmerName,
    required this.parish,
    required this.unit,
    required this.targetQuantity,
    required this.harvestStart,
    required this.harvestEnd,
    required this.description,
    required this.status,
    required this.featured,
    required this.reservedQuantity,
    required this.householdCount,
    required this.followerCount,
    required this.supplyCommitted,
    required this.farmerCount,
    required this.myCommitmentType,
    required this.myQuantity,
    required this.myRepeatWeeks,
  });

  factory HpjHarvestCircle.fromSupabase(Map<String, dynamic> data) {
    double number(dynamic value) {
      if (value is num) return value.toDouble();
      return double.tryParse(value?.toString() ?? '') ?? 0;
    }

    int integer(dynamic value) {
      if (value is num) return value.toInt();
      return int.tryParse(value?.toString() ?? '') ?? 0;
    }

    return HpjHarvestCircle(
      id: (data['id'] ?? '').toString(),
      productId: (data['product_id'] ?? '').toString(),
      productName: (data['product_name'] ?? 'Upcoming harvest').toString().trim(),
      category: (data['category'] ?? '').toString().trim(),
      imageUrl: (data['image_url'] ?? '').toString().trim(),
      farmName: (data['farm_name'] ?? '').toString().trim(),
      farmerName: (data['farmer_name'] ?? '').toString().trim(),
      parish: (data['parish'] ?? '').toString().trim(),
      unit: (data['unit'] ?? 'unit').toString().trim(),
      targetQuantity: number(data['target_quantity']),
      harvestStart: parseProductDate(data['harvest_start']),
      harvestEnd: parseProductDate(data['harvest_end']),
      description: (data['description'] ?? '').toString().trim(),
      status: (data['status'] ?? 'open').toString().trim().toLowerCase(),
      featured: data['featured'] == true,
      reservedQuantity: number(data['reserved_quantity']),
      householdCount: integer(data['household_count']),
      followerCount: integer(data['follower_count']),
      supplyCommitted: number(data['supply_committed']),
      farmerCount: integer(data['farmer_count']),
      myCommitmentType:
          (data['my_commitment_type'] ?? '').toString().trim().toLowerCase(),
      myQuantity: number(data['my_quantity']),
      myRepeatWeeks: integer(data['my_repeat_weeks']).clamp(1, 12).toInt(),
    );
  }

  double get demandProgress {
    if (targetQuantity <= 0) return 0;
    return (reservedQuantity / targetQuantity).clamp(0, 1).toDouble();
  }

  double get supplyProgress {
    if (reservedQuantity <= 0) return 0;
    return (supplyCommitted / reservedQuantity).clamp(0, 1).toDouble();
  }

  bool get isFollowing => myCommitmentType == 'follow';
  bool get isReserved =>
      myCommitmentType == 'reserve' || myCommitmentType == 'repeat';

  String get statusLabel {
    if (status == 'fully_reserved' || demandProgress >= 1) {
      return 'Demand reached';
    }
    switch (status) {
      case 'growing':
        return 'Growing now';
      case 'harvesting':
        return 'Harvesting';
      default:
        return 'Building demand';
    }
  }
}

String _hpjHarvestNumber(double value) {
  if (value == value.roundToDouble()) return value.toInt().toString();
  return value.toStringAsFixed(1);
}

String _hpjHarvestDate(DateTime? date) {
  if (date == null) return 'Date to be confirmed';
  const months = <String>[
    'Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun',
    'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec',
  ];
  return '${date.day} ${months[date.month - 1]}';
}

String _hpjHarvestWindow(HpjHarvestCircle circle) {
  if (circle.harvestStart == null && circle.harvestEnd == null) {
    return 'Harvest date to be confirmed';
  }
  if (circle.harvestEnd == null ||
      circle.harvestStart?.day == circle.harvestEnd?.day &&
          circle.harvestStart?.month == circle.harvestEnd?.month) {
    return 'Expected ${_hpjHarvestDate(circle.harvestStart ?? circle.harvestEnd)}';
  }
  return '${_hpjHarvestDate(circle.harvestStart)} – ${_hpjHarvestDate(circle.harvestEnd)}';
}

Future<List<HpjHarvestCircle>> fetchHpjHarvestCircles({
  int limit = 30,
}) async {
  try {
    final response = await supabase.rpc(
      'hpj_get_harvest_circles',
      params: {'p_limit': limit},
    );

    return (response as List)
        .map(
          (row) => HpjHarvestCircle.fromSupabase(
            Map<String, dynamic>.from(row as Map),
          ),
        )
        .where((circle) => circle.id.isNotEmpty)
        .toList(growable: false);
  } catch (error) {
    farmDebugLog('Harvest Circles unavailable: $error');
    return const <HpjHarvestCircle>[];
  }
}

Future<void> saveHpjHarvestCircleCommitment({
  required String circleId,
  required String commitmentType,
  double quantity = 0,
  int repeatWeeks = 1,
}) async {
  if (!isLoggedIn) throw Exception('Sign in first.');

  await supabase.rpc(
    'hpj_upsert_harvest_circle_commitment',
    params: <String, dynamic>{
      'p_circle_id': circleId,
      'p_commitment_type': commitmentType,
      'p_quantity': quantity,
      'p_repeat_weeks': repeatWeeks,
    },
  );
}

Future<void> cancelHpjHarvestCircleCommitment(String circleId) async {
  if (!isLoggedIn) throw Exception('Sign in first.');
  await supabase.rpc(
    'hpj_cancel_harvest_circle_commitment',
    params: {'p_circle_id': circleId},
  );
}

