class _HpjHarvestCommitmentSheet extends StatefulWidget {
  final HpjHarvestCircle circle;

  const _HpjHarvestCommitmentSheet({required this.circle});

  @override
  State<_HpjHarvestCommitmentSheet> createState() =>
      _HpjHarvestCommitmentSheetState();
}

class _HpjHarvestCommitmentSheetState
    extends State<_HpjHarvestCommitmentSheet> {
  late final TextEditingController quantityController;
  int repeatWeeks = 1;
  bool saving = false;

  @override
  void initState() {
    super.initState();
    quantityController = TextEditingController(
      text: widget.circle.myQuantity > 0
          ? _hpjHarvestNumber(widget.circle.myQuantity)
          : '1',
    );
    repeatWeeks = widget.circle.myCommitmentType == 'repeat'
        ? widget.circle.myRepeatWeeks
        : 1;
  }

  @override
  void dispose() {
    quantityController.dispose();
    super.dispose();
  }

  Future<void> _save() async {
    if (saving) return;
    final quantity = double.tryParse(
      quantityController.text.trim().replaceAll(',', ''),
    );
    if (quantity == null || !quantity.isFinite || quantity <= 0) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Enter the quantity you want to reserve.')),
      );
      return;
    }

    setState(() => saving = true);
    try {
      await saveHpjHarvestCircleCommitment(
        circleId: widget.circle.id,
        commitmentType: repeatWeeks > 1 ? 'repeat' : 'reserve',
        quantity: quantity,
        repeatWeeks: repeatWeeks,
      );
      if (!mounted) return;
      Navigator.of(context).pop(true);
    } catch (error) {
      if (!mounted) return;
      setState(() => saving = false);
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(friendlyAppError(error))),
      );
    }
  }

  @override
  Widget build(BuildContext context) {
    final bottom = MediaQuery.viewInsetsOf(context).bottom;
    return Container(
      constraints: const BoxConstraints(maxWidth: 660),
      margin: EdgeInsets.only(top: 20, bottom: kIsWeb ? 18 : 0),
      padding: EdgeInsets.fromLTRB(20, 18, 20, bottom + 22),
      decoration: const BoxDecoration(
        color: Color(0xFFF9FAF6),
        borderRadius: BorderRadius.vertical(top: Radius.circular(28)),
      ),
      child: SingleChildScrollView(
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Row(
              children: [
                _HpjHarvestImage(imageUrl: widget.circle.imageUrl, size: 62),
                const SizedBox(width: 11),
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      const Text(
                        'Reserve your harvest',
                        style: TextStyle(
                          color: Color(0xFF173C2F),
                          fontSize: 18,
                          fontWeight: FontWeight.w900,
                        ),
                      ),
                      const SizedBox(height: 3),
                      Text(
                        widget.circle.productName,
                        style: const TextStyle(
                          color: Color(0xFF557064),
                          fontSize: 11,
                          fontWeight: FontWeight.w800,
                        ),
                      ),
                    ],
                  ),
                ),
              ],
            ),
            const SizedBox(height: 18),
            TextField(
              controller: quantityController,
