  }

  Widget _weekChip(int weeks, String label) {
    return ChoiceChip(
      label: Text(label),
      selected: repeatWeeks == weeks,
      onSelected: (_) => setState(() => repeatWeeks = weeks),
      selectedColor: const Color(0xFF0C4B36),
      labelStyle: TextStyle(
        color: repeatWeeks == weeks ? Colors.white : const Color(0xFF345848),
        fontWeight: FontWeight.w800,
        fontSize: 10,
      ),
    );
  }
}



// ============================================================================
// HPJ PHASE 93 — HARVEST DROP + REAL ORDER HANDOFF
//
// Harvest Circle reservation -> crop-ready field update -> private 48-hour
// Harvest Drop -> My Box -> existing secure HPJ checkout -> real Order tracking.
//
// Important: claiming a Harvest Drop does NOT create a second stock ledger.
// The existing secure checkout remains the inventory/payment source of truth.
// ============================================================================

class HpjHarvestDrop {
  final String circleId;
  final String productId;
  final String productName;
  final String imageUrl;
  final String farmName;
  final String parish;
  final String unit;
  final double reservedQuantity;
  final int repeatWeeks;
  final String dropStatus;
  final DateTime? dropReadyAt;
  final DateTime? dropOpenedAt;
  final DateTime? dropClosesAt;
  final String claimStatus;
  final DateTime? claimedAt;
  final DateTime? orderedAt;
  final String orderId;
  final double orderedQuantity;
  final String orderStatus;
  final String fulfillmentType;
  final String deliveryStatus;
  final bool productAvailable;
  final int stockQuantity;

  const HpjHarvestDrop({
    required this.circleId,
    required this.productId,
    required this.productName,
    required this.imageUrl,
    required this.farmName,
    required this.parish,
    required this.unit,
    required this.reservedQuantity,
    required this.repeatWeeks,
    required this.dropStatus,
    required this.dropReadyAt,
    required this.dropOpenedAt,
    required this.dropClosesAt,
    required this.claimStatus,
    required this.claimedAt,
    required this.orderedAt,
    required this.orderId,
    required this.orderedQuantity,
    required this.orderStatus,
    required this.fulfillmentType,
    required this.deliveryStatus,
    required this.productAvailable,
    required this.stockQuantity,
  });

  factory HpjHarvestDrop.fromSupabase(Map<String, dynamic> data) {
    double number(dynamic value) {
      if (value is num) return value.toDouble();
      return double.tryParse(value?.toString() ?? '') ?? 0;
    }

    int integer(dynamic value) {
      if (value is num) return value.toInt();
      return int.tryParse(value?.toString() ?? '') ?? 0;
    }

    return HpjHarvestDrop(
      circleId: (data['circle_id'] ?? '').toString(),
      productId: (data['product_id'] ?? '').toString(),
      productName: (data['product_name'] ?? 'Your harvest').toString().trim(),
      imageUrl: (data['image_url'] ?? '').toString().trim(),
      farmName: (data['farm_name'] ?? '').toString().trim(),
      parish: (data['parish'] ?? '').toString().trim(),
      unit: (data['unit'] ?? 'unit').toString().trim(),
      reservedQuantity: number(data['reserved_quantity']),
      repeatWeeks: integer(data['repeat_weeks']).clamp(1, 12).toInt(),
      dropStatus:
          (data['drop_status'] ?? 'waiting').toString().trim().toLowerCase(),
      dropReadyAt: parseProductDate(data['drop_ready_at']),
      dropOpenedAt: parseProductDate(data['drop_opened_at']),
      dropClosesAt: parseProductDate(data['drop_closes_at']),
      claimStatus:
          (data['claim_status'] ?? 'unclaimed').toString().trim().toLowerCase(),
      claimedAt: parseProductDate(data['claimed_at']),
      orderedAt: parseProductDate(data['ordered_at']),
      orderId: (data['order_id'] ?? '').toString().trim(),
      orderedQuantity: number(data['ordered_quantity']),
      orderStatus:
          (data['order_status'] ?? '').toString().trim().toLowerCase(),
      fulfillmentType:
          (data['fulfillment_type'] ?? '').toString().trim().toLowerCase(),
      deliveryStatus:
          (data['delivery_status'] ?? '').toString().trim().toLowerCase(),
      productAvailable: data['product_available'] == true,
      stockQuantity: integer(data['stock_quantity']),
    );
  }

  bool get isOpen =>
      dropStatus == 'open' &&
      (dropClosesAt == null || dropClosesAt!.isAfter(DateTime.now()));
  bool get isReady => dropStatus == 'ready';
  bool get isClaimed => claimStatus == 'claimed' || dropStatus == 'claimed';
  bool get isOrdered =>
      claimStatus == 'ordered' || dropStatus == 'ordered' || orderId.isNotEmpty;
  bool get isClosed =>
      dropStatus == 'closed' ||
      (dropClosesAt != null &&
          !dropClosesAt!.isAfter(DateTime.now()) &&
          !isOrdered);
  bool get canMoveToBox =>
      !isOrdered && (isClaimed || (isOpen && productAvailable));

  String get shortOrderId {
    if (orderId.isEmpty) return '';
    return orderId.length <= 6 ? orderId.toUpperCase() : orderId.substring(0, 6).toUpperCase();
  }

  String get statusLabel {
    if (isOrdered) {
      switch (orderStatus) {
        case 'preparing':
          return 'HPJ is preparing it';
        case 'ready':
        case 'ready_for_pickup':
          return 'Ready for handoff';
        case 'out_for_delivery':
          return 'On the way';
        case 'delivered':
        case 'completed':
          return 'Delivered';
        case 'cancelled':
          return 'Order cancelled';
        default:
          return 'Order placed';
      }
    }
    if (isClaimed) return 'Claimed • finish checkout';
    if (isOpen) return 'Ready to claim';
    if (isReady) return 'HPJ is preparing stock';
    if (isClosed) return 'Drop closed';
    return 'Growing for you';
  }
}

Future<List<HpjHarvestDrop>> fetchMyHpjHarvestDrops({
  int limit = 30,
}) async {
  if (!isLoggedIn || supabase.auth.currentUser == null) {
    return const <HpjHarvestDrop>[];
  }

  try {
    final response = await supabase.rpc(
      'hpj_get_my_harvest_drops',
      params: {'p_limit': limit},
    );

    return (response as List)
        .map(
          (row) => HpjHarvestDrop.fromSupabase(
            Map<String, dynamic>.from(row as Map),
          ),
        )
        .where((item) => item.circleId.isNotEmpty)
        .toList(growable: false);
  } catch (error) {
    farmDebugLog('Harvest Drops unavailable: $error');
    return const <HpjHarvestDrop>[];
  }
}

Future<void> claimHpjHarvestDrop(String circleId) async {
  if (!isLoggedIn) throw Exception('Sign in first.');
  final clean = circleId.trim();
  if (clean.isEmpty) throw Exception('Harvest Drop could not be identified.');

  await supabase.rpc(
    'hpj_claim_harvest_drop',
    params: {'p_circle_id': clean},
  );
}

Future<void> linkHpjHarvestDropClaimsToOrder(String orderId) async {
  if (!isLoggedIn) return;
  final clean = orderId.trim();
  if (clean.isEmpty) return;

  await supabase.rpc(
    'hpj_link_claimed_harvest_drops_to_order',
    params: {'p_order_id': clean},
  );
}

String _hpjHarvestDropDeadline(DateTime? closesAt) {
  if (closesAt == null) return '48-hour priority window';
  final remaining = closesAt.difference(DateTime.now());
  if (remaining.isNegative) return 'Priority window ended';
  if (remaining.inHours < 1) {
    return '${remaining.inMinutes.clamp(1, 59)} min left';
  }
  if (remaining.inHours < 24) return '${remaining.inHours} hr left';
  final days = remaining.inDays;
  final hours = remaining.inHours - days * 24;
  return hours <= 0 ? '$days day${days == 1 ? '' : 's'} left' : '$days d $hours hr left';
}

Future<void> _hpjOpenHarvestDropOrder(
  BuildContext context,
  HpjHarvestDrop drop,
) async {
  if (drop.orderId.isEmpty) return;
  await Navigator.of(context).push<void>(
    MaterialPageRoute<void>(
      builder: (_) => OrderDetailsScreen(orderId: drop.orderId),
    ),
  );
}

Future<bool> _hpjMoveHarvestDropToMyBox(
  BuildContext context,
  HpjHarvestDrop drop,
) async {
  if (!isLoggedIn) {
    final authenticated = await Navigator.of(context).push<bool>(
      MaterialPageRoute<bool>(
        builder: (_) => const LoginScreen(returnToPrevious: true),
      ),
    );
    if (!context.mounted || (authenticated != true && !isLoggedIn)) return false;
  }

  if (drop.isOrdered) {
    await _hpjOpenHarvestDropOrder(context, drop);
    return true;
  }

  final product = await fetchProductById(drop.productId);
  if (!context.mounted) return false;

  if (product == null || !product.canAddToCart || product.stockQuantity <= 0) {
    ScaffoldMessenger.of(context).showSnackBar(
      const SnackBar(
        content: Text(
          'HPJ is still preparing this harvest for checkout. Your reservation is still on your Harvest Journey.',
        ),
      ),
    );
    return false;
  }

  try {
    if (!drop.isClaimed) {
      await claimHpjHarvestDrop(drop.circleId);
    }
  } catch (error) {
    if (!context.mounted) return false;
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(content: Text(friendlyAppError(error))),
    );
    return false;
  }

  if (!context.mounted) return false;

  final cart = OfflineCartStore.restore();
  final alreadyInBox = cart.where((item) => item.id == product.id).length;

  // Existing Customer cart quantities are retail units. Harvest Circle demand
  // can be decimal (for example 2.5 lb), so Phase 93 never pretends these are
  // identical. It adds the nearest whole retail-unit count and asks the
  // customer to review My Box before secure checkout.
  var targetUnits = drop.reservedQuantity.ceil();
  if (targetUnits < 1) targetUnits = 1;
  if (targetUnits > 20) targetUnits = 20;

  var additional = targetUnits - alreadyInBox;
  final stockRemaining = product.stockQuantity - alreadyInBox;
  if (additional > stockRemaining) additional = stockRemaining;
  if (additional < 0) additional = 0;

  for (var i = 0; i < additional; i++) {
    cart.add(product);
  }

  if (additional > 0) {
    OfflineCartStore.save(cart);
    if (isLoggedIn) {
      for (var i = 0; i < additional; i++) {
        try {
          await saveCartItemForCurrentUser(product);
        } catch (error) {
          farmDebugLog('Harvest Drop saved-cart sync skipped: $error');
          break;
        }
      }
    }
  }

  if (!context.mounted) return false;

  final exactWholeQuantity =
      drop.reservedQuantity == drop.reservedQuantity.roundToDouble();

  ScaffoldMessenger.of(context).showSnackBar(
    SnackBar(
      content: Text(
        additional <= 0
            ? '${product.name} is already in My Box. Review the quantity before checkout.'
            : exactWholeQuantity
                ? 'Added $additional ${additional == 1 ? 'unit' : 'units'} of ${product.name} to My Box. Secure it by completing checkout.'
                : 'Added $additional retail ${additional == 1 ? 'unit' : 'units'} based on your ${_hpjHarvestNumber(drop.reservedQuantity)} ${drop.unit} reservation. Review My Box before checkout.',
      ),
    ),
  );

  await Navigator.of(context).push<void>(
    MaterialPageRoute<void>(
      builder: (_) => const MainNavigation(initialIndex: 2),
    ),
  );

  return true;
}

