class HpjHarvestDropJourneyCard extends StatefulWidget {
  final String circleId;

  const HpjHarvestDropJourneyCard({
    super.key,
    required this.circleId,
  });

  @override
  State<HpjHarvestDropJourneyCard> createState() =>
      _HpjHarvestDropJourneyCardState();
}

class _HpjHarvestDropJourneyCardState
    extends State<HpjHarvestDropJourneyCard> {
  late Future<HpjHarvestDrop?> _future;

  @override
  void initState() {
    super.initState();
    _future = _load();
  }

  Future<HpjHarvestDrop?> _load() async {
    if (!isLoggedIn) return null;
    final rows = await fetchMyHpjHarvestDrops(limit: 60);
    for (final row in rows) {
      if (row.circleId == widget.circleId) return row;
    }
    return null;
  }

  Future<void> _refresh() async {
    final next = _load();
    if (mounted) setState(() => _future = next);
    await next;
  }

  Future<void> _action(HpjHarvestDrop item) async {
    if (item.isOrdered) {
      await _hpjOpenHarvestDropOrder(context, item);
    } else {
      await _hpjMoveHarvestDropToMyBox(context, item);
    }
    if (mounted) await _refresh();
  }

  int _orderProgress(HpjHarvestDrop item) {
    if (!item.isOrdered) return 0;
    switch (item.orderStatus) {
      case 'preparing':
        return 2;
      case 'ready':
      case 'ready_for_pickup':
        return 3;
      case 'out_for_delivery':
        return 4;
      case 'delivered':
      case 'completed':
        return 5;
      default:
        return 1;
    }
  }

  @override
  Widget build(BuildContext context) {
    if (!isLoggedIn) return const SizedBox.shrink();

    return FutureBuilder<HpjHarvestDrop?>(
      future: _future,
      builder: (context, snapshot) {
        final item = snapshot.data;
        if (item == null) return const SizedBox.shrink();

        final orderProgress = _orderProgress(item);

        return Container(
          width: double.infinity,
          padding: const EdgeInsets.all(17),
          decoration: BoxDecoration(
            color: Colors.white,
            borderRadius: BorderRadius.circular(23),
            border: Border.all(color: const Color(0xFFDCE5DA)),
            boxShadow: [
              BoxShadow(
                color: const Color(0xFF173C2F).withOpacity(.045),
                blurRadius: 20,
                offset: const Offset(0, 8),
              ),
            ],
          ),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Row(
                children: [
                  Container(
                    width: 41,
                    height: 41,
                    decoration: BoxDecoration(
                      color: const Color(0xFFFFF3C7),
                      borderRadius: BorderRadius.circular(13),
                    ),
                    child: const Icon(
                      Icons.inventory_2_outlined,
                      color: Color(0xFF8B6507),
                      size: 20,
                    ),
                  ),
                  const SizedBox(width: 10),
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        const Text(
                          'Your Harvest Drop',
                          style: TextStyle(
                            color: Color(0xFF173C2F),
                            fontSize: 15.5,
                            fontWeight: FontWeight.w900,
                          ),
                        ),
                        const SizedBox(height: 2),
                        Text(
                          item.isOrdered
                              ? 'The farm story has now handed off to a real HPJ order.'
                              : item.isOpen
                                  ? 'Your priority checkout window is open now.'
                                  : item.isReady
                                      ? 'The crop is ready. HPJ is preparing Customer Shop stock.'
