      child: LayoutBuilder(
        builder: (context, constraints) {
          final wide = constraints.maxWidth >= 720;

          final copy = Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              const Text(
                'HPJ FARM-TO-BOX PASSPORT',
                style: TextStyle(
                  color: Color(0xFFFFD55A),
                  fontSize: 8.8,
                  letterSpacing: .9,
                  fontWeight: FontWeight.w900,
