              const SizedBox(height: 7),
              const Text(
                'See the verified story behind your food.',
                style: TextStyle(
                  color: Colors.white,
                  fontSize: 26,
                  height: 1.05,
                  letterSpacing: -.45,
                  fontWeight: FontWeight.w900,
                ),
              ),
              const SizedBox(height: 8),
              Text(
                'Order #$displayOrder • GrowTogether harvest trace',
                style: TextStyle(
                  color: Colors.white.withOpacity(.73),
                  fontSize: 10.3,
                  fontWeight: FontWeight.w700,
                ),
              ),
            ],
          );

          final metrics = Container(
            padding: const EdgeInsets.all(14),
            decoration: BoxDecoration(
              color: Colors.white.withOpacity(.08),
              borderRadius: BorderRadius.circular(19),
              border: Border.all(color: Colors.white.withOpacity(.10)),
            ),
            child: Row(
              mainAxisSize: MainAxisSize.min,
              children: [
                _HpjPassportHeroMetric(
                  value: '${groups.length}',
                  label: 'Harvests',
                ),
                const SizedBox(width: 20),
                _HpjPassportHeroMetric(
                  value: '${farms.length}',
                  label: 'Farms',
                ),
                const SizedBox(width: 20),
                _HpjPassportHeroMetric(
                  value: _hpjPassportBestLabel(items),
                  label: 'Strongest trace',
                  compact: true,
