class _HpjPassportFarmSourceCard extends StatelessWidget {
  final HpjFarmPassportSource source;

  const _HpjPassportFarmSourceCard({
    required this.source,
  });

  String _supplyText() {
    if (source.exactLotVerified && source.lotCode.isNotEmpty) {
      return 'Exact packed lot ${source.lotCode} verified';
    }
    if (source.hasReceiving) {
      final qty = source.acceptedQuantity > 0
          ? '${_hpjPassportNumber(source.acceptedQuantity)} ${source.unit} accepted'
          : 'Completed receiving record';
      return source.lotCode.isEmpty
          ? '$qty • associated HPJ receiving'
          : '$qty • receiving lot ${source.lotCode}';
    }
    if (source.hasVerifiedSupply) {
      return source.confirmedQuantity > 0
          ? '${_hpjPassportNumber(source.confirmedQuantity)} ${source.unit} HPJ-confirmed supply'
          : 'Supply verified by HPJ';
    }
    if (source.hasFieldUpdate) {
      return '${_hpjJourneyStageLabel(source.latestStage)} field update';
    }
    return 'Linked to this Harvest Circle';
  }

  @override
  Widget build(BuildContext context) {
    final latestPhoto = source.latestImageUrl.trim();
    final detail = source.traceMessage.isNotEmpty
        ? source.traceMessage
        : _supplyText();

    return Container(
      width: double.infinity,
      padding: const EdgeInsets.all(13),
      decoration: BoxDecoration(
        color: const Color(0xFFF7F9F5),
        borderRadius: BorderRadius.circular(18),
        border: Border.all(color: const Color(0xFFE1E7DE)),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Container(
                width: 41,
                height: 41,
                decoration: BoxDecoration(
                  color: const Color(0xFFE9F3E5),
                  borderRadius: BorderRadius.circular(13),
                ),
                child: const Icon(
                  Icons.agriculture_outlined,
                  color: Color(0xFF176044),
                  size: 21,
                ),
              ),
              const SizedBox(width: 10),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      source.farmDisplayName,
                      style: const TextStyle(
                        color: Color(0xFF173C2F),
                        fontSize: 12,
                        fontWeight: FontWeight.w900,
                      ),
                    ),
                    if (source.sourceLocation.isNotEmpty) ...[
                      const SizedBox(height: 2),
                      Text(
                        source.sourceLocation,
                        style: const TextStyle(
                          color: Color(0xFF7A867F),
                          fontSize: 8.8,
                          fontWeight: FontWeight.w700,
                        ),
                      ),
                    ],
                  ],
                ),
              ),
              Container(
                padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 5),
                decoration: BoxDecoration(
                  color: source.exactLotVerified
                      ? const Color(0xFFE3F4E8)
                      : const Color(0xFFFFF3C9),
                  borderRadius: BorderRadius.circular(999),
                ),
                child: Text(
                  source.traceLabel,
                  style: TextStyle(
                    color: source.exactLotVerified
                        ? const Color(0xFF176044)
                        : const Color(0xFF775B12),
                    fontSize: 7.5,
                    fontWeight: FontWeight.w900,
                  ),
                ),
              ),
            ],
          ),
          const SizedBox(height: 10),
          Text(
            _supplyText(),
            style: const TextStyle(
              color: Color(0xFF345447),
              fontSize: 9.2,
              height: 1.35,
              fontWeight: FontWeight.w800,
            ),
          ),
          if (source.hasFieldUpdate) ...[
            const SizedBox(height: 8),
            Container(
              width: double.infinity,
              padding: const EdgeInsets.all(10),
              decoration: BoxDecoration(
                color: Colors.white,
                borderRadius: BorderRadius.circular(14),
              ),
              child: Row(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  if (latestPhoto.isNotEmpty) ...[
                    ClipRRect(
                      borderRadius: BorderRadius.circular(10),
                      child: Image.network(
                        latestPhoto,
                        width: 56,
                        height: 56,
                        fit: BoxFit.cover,
                        errorBuilder: (_, __, ___) => const SizedBox.shrink(),
                      ),
                    ),
                    const SizedBox(width: 9),
                  ],
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(
                          _hpjJourneyStageLabel(source.latestStage),
                          style: const TextStyle(
                            color: Color(0xFF176044),
                            fontSize: 8.8,
                            fontWeight: FontWeight.w900,
                          ),
                        ),
                        if (source.latestMessage.isNotEmpty) ...[
                          const SizedBox(height: 3),
                          Text(
                            source.latestMessage,
                            maxLines: 3,
                            overflow: TextOverflow.ellipsis,
                            style: const TextStyle(
                              color: Color(0xFF66746C),
                              fontSize: 8.5,
                              height: 1.35,
                              fontWeight: FontWeight.w600,
                            ),
                          ),
                        ],
                        if (source.latestUpdateAt != null) ...[
                          const SizedBox(height: 4),
                          Text(
                            _hpjPassportDate(source.latestUpdateAt),
                            style: const TextStyle(
                              color: Color(0xFF98A19B),
                              fontSize: 7.6,
                              fontWeight: FontWeight.w700,
                            ),
                          ),
                        ],
                      ],
                    ),
                  ),
                ],
              ),
            ),
          ],
          if (source.hasReceiving) ...[
            const SizedBox(height: 8),
            Wrap(
              spacing: 7,
              runSpacing: 7,
              children: [
                if (source.lotCode.isNotEmpty)
                  _HpjPassportDetailPill(
                    label: 'Lot',
                    value: source.lotCode,
                  ),
                if (source.qualityGrade.isNotEmpty)
                  _HpjPassportDetailPill(
                    label: 'Grade',
                    value: source.qualityGrade,
                  ),
                if (source.completedAt != null)
                  _HpjPassportDetailPill(
                    label: 'HPJ completed',
                    value: _hpjPassportDate(source.completedAt),
                  ),
              ],
            ),
          ],
          if (detail.isNotEmpty && detail != _supplyText()) ...[
            const SizedBox(height: 8),
            Text(
              detail,
              style: const TextStyle(
                color: Color(0xFF78847D),
                fontSize: 8.2,
                height: 1.35,
                fontWeight: FontWeight.w600,
              ),
            ),
          ],
        ],
      ),
    );
  }
}

