// ============================================================================
// HPJ PHASE 92 — HARVEST JOURNEY + RESCUE HARVEST
// Customers can follow a reserved crop from real farmer field updates, while
// HPJ can surface verified near-term surplus as a Rescue Harvest opportunity.
// ============================================================================

class HpjHarvestJourneyUpdate {
  final String id;
  final String circleId;
  final String farmName;
  final String stage;
  final String message;
  final String imageUrl;
  final DateTime? createdAt;

  const HpjHarvestJourneyUpdate({
    required this.id,
    required this.circleId,
    required this.farmName,
    required this.stage,
    required this.message,
    required this.imageUrl,
    required this.createdAt,
  });

  factory HpjHarvestJourneyUpdate.fromSupabase(Map<String, dynamic> data) {
    return HpjHarvestJourneyUpdate(
      id: (data['id'] ?? '').toString(),
      circleId: (data['circle_id'] ?? '').toString(),
      farmName: (data['farm_name'] ?? 'Jamaican farm').toString().trim(),
      stage: (data['stage'] ?? 'growing').toString().trim().toLowerCase(),
      message: (data['message'] ?? '').toString().trim(),
      imageUrl: (data['image_url'] ?? '').toString().trim(),
      createdAt: parseProductDate(data['created_at']),
    );
  }
}

Future<List<HpjHarvestJourneyUpdate>> fetchHpjHarvestJourney(
  String circleId, {
  int limit = 60,
}) async {
  final cleanId = circleId.trim();
  if (cleanId.isEmpty) return const <HpjHarvestJourneyUpdate>[];

  try {
    final response = await supabase.rpc(
      'hpj_get_harvest_journey',
      params: <String, dynamic>{
        'p_circle_id': cleanId,
        'p_limit': limit,
      },
    );

    return (response as List)
        .map(
          (row) => HpjHarvestJourneyUpdate.fromSupabase(
            Map<String, dynamic>.from(row as Map),
          ),
        )
        .where((item) => item.id.isNotEmpty)
        .toList(growable: false);
  } catch (error) {
    farmDebugLog('Harvest Journey unavailable: $error');
    return const <HpjHarvestJourneyUpdate>[];
  }
}

String _hpjJourneyStageLabel(String stage) {
  switch (stage.trim().toLowerCase()) {
    case 'planted':
      return 'Planted';
    case 'established':
      return 'Crop established';
    case 'flowering':
      return 'Flowering';
    case 'fruiting':
      return 'Producing';
    case 'harvest_ready':
      return 'Harvest ready';
    case 'harvesting':
      return 'Harvesting';
    case 'collected':
      return 'Collected by HPJ';
    case 'growing':
    default:
      return 'Growing';
  }
}

IconData _hpjJourneyStageIcon(String stage) {
  switch (stage.trim().toLowerCase()) {
    case 'planted':
      return Icons.grass_rounded;
    case 'established':
      return Icons.eco_rounded;
    case 'flowering':
      return Icons.local_florist_rounded;
    case 'fruiting':
      return Icons.spa_rounded;
    case 'harvest_ready':
      return Icons.task_alt_rounded;
    case 'harvesting':
      return Icons.agriculture_rounded;
    case 'collected':
      return Icons.local_shipping_rounded;
    default:
      return Icons.eco_outlined;
  }
}

