class _HpjRescueReserveSheet extends StatefulWidget {
  final HpjRescueHarvest item;

  const _HpjRescueReserveSheet({required this.item});

  @override
  State<_HpjRescueReserveSheet> createState() =>
      _HpjRescueReserveSheetState();
}

class _HpjRescueReserveSheetState extends State<_HpjRescueReserveSheet> {
  final TextEditingController quantityController = TextEditingController(text: '1');
  bool saving = false;

  @override
  void dispose() {
    quantityController.dispose();
    super.dispose();
  }

  Future<void> _save() async {
    if (saving) return;
    final extra = double.tryParse(quantityController.text.trim().replaceAll(',', ''));
    if (extra == null || !extra.isFinite || extra <= 0) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Enter the quantity you can use.')),
      );
      return;
    }
    if (extra > widget.item.rescueQuantity + 0.0001) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            'Up to ${_hpjHarvestNumber(widget.item.rescueQuantity)} ${widget.item.unit} is currently available for rescue.',
          ),
        ),
      );
      return;
    }

    setState(() => saving = true);
    try {
      final total = widget.item.myQuantity + extra;
      final keepRepeat = widget.item.myCommitmentType == 'repeat';
      await saveHpjHarvestCircleCommitment(
        circleId: widget.item.circleId,
        commitmentType: keepRepeat ? 'repeat' : 'reserve',
        quantity: total,
        repeatWeeks: keepRepeat ? widget.item.myRepeatWeeks : 1,
      );
      if (!mounted) return;
      Navigator.of(context).pop(true);
    } catch (error) {
      if (!mounted) return;
      setState(() => saving = false);
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(friendlyAppError(error))),
      );
    }
  }

  @override
  Widget build(BuildContext context) {
    final bottom = MediaQuery.viewInsetsOf(context).bottom;
    return Container(
      constraints: const BoxConstraints(maxWidth: 620),
      margin: EdgeInsets.only(top: 20, bottom: kIsWeb ? 18 : 0),
      padding: EdgeInsets.fromLTRB(20, 18, 20, bottom + 22),
      decoration: const BoxDecoration(
        color: Color(0xFFFFFCF5),
        borderRadius: BorderRadius.vertical(top: Radius.circular(28)),
      ),
      child: SingleChildScrollView(
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            const Text(
              'Help rescue this harvest',
              style: TextStyle(
                color: Color(0xFF503D0E),
                fontSize: 18,
                fontWeight: FontWeight.w900,
              ),
            ),
            const SizedBox(height: 4),
            Text(
              '${widget.item.productName} • ${_hpjHarvestNumber(widget.item.rescueQuantity)} ${widget.item.unit} still need homes',
              style: const TextStyle(
                color: Color(0xFF88733F),
                fontSize: 10,
                fontWeight: FontWeight.w700,
              ),
            ),
            const SizedBox(height: 16),
            TextField(
              controller: quantityController,
              keyboardType: const TextInputType.numberWithOptions(decimal: true),
              decoration: InputDecoration(
                labelText: 'Extra quantity (${widget.item.unit})',
                helperText: widget.item.myQuantity > 0
                    ? 'This is added to your existing Harvest Circle reservation.'
                    : 'This becomes a real Harvest Circle reservation.',
              ),
            ),
            const SizedBox(height: 14),
            Container(
              width: double.infinity,
              padding: const EdgeInsets.all(12),
              decoration: BoxDecoration(
                color: const Color(0xFFFFF2CB),
                borderRadius: BorderRadius.circular(15),
              ),
              child: const Text(
                'HPJ only shows Rescue Harvest after supply has been confirmed. Payment is still handled when the harvest becomes ready for ordering and fulfillment.',
                style: TextStyle(
                  color: Color(0xFF715614),
                  fontSize: 9.3,
                  height: 1.4,
                  fontWeight: FontWeight.w700,
                ),
              ),
            ),
            const SizedBox(height: 16),
            SizedBox(
              width: double.infinity,
              child: FilledButton.icon(
                onPressed: saving ? null : _save,
                style: FilledButton.styleFrom(
                  backgroundColor: const Color(0xFF9C6A0A),
                  padding: const EdgeInsets.symmetric(vertical: 14),
                ),
                icon: saving
                    ? const SizedBox(
                        width: 17,
                        height: 17,
                        child: CircularProgressIndicator(
                          strokeWidth: 2,
                          color: Colors.white,
                        ),
                      )
                    : const Icon(Icons.favorite_rounded),
                label: Text(saving ? 'Saving...' : 'Add my rescue reservation'),
              ),
            ),
          ],
        ),
      ),
    );
  }
}

class AccountScreen extends StatelessWidget {
  final List<Product> favoriteProducts;
