class _HpjMobileCleanAccountHero extends StatelessWidget {
  final String name;
  final String email;

  const _HpjMobileCleanAccountHero({
    required this.name,
    required this.email,
  });

  String? _profileImageUrl() {
    final metadata =
        supabase.auth.currentUser?.userMetadata ?? const <String, dynamic>{};

    for (final key in const <String>[
      'avatar_url',
      'picture',
      'photo_url',
      'profile_photo_url',
      'image_url',
    ]) {
      final raw = metadata[key]?.toString().trim() ?? '';
      if (raw.isEmpty) continue;

      final clean = cleanHostedImageUrl(raw);
      if (clean != null && clean.isNotEmpty) return clean;
    }

    return null;
  }

  Widget _identityImage({
    required String initial,
    required String? imageUrl,
  }) {
    Widget fallback() => Container(
          color: const Color(0xFFDDEBDD),
          alignment: Alignment.center,
          child: Text(
            initial,
            style: const TextStyle(
              color: FarmColors.deepGreen,
              fontSize: 19,
              fontWeight: FontWeight.w900,
            ),
          ),
        );

    return Container(
      width: 56,
      height: 56,
      padding: const EdgeInsets.all(2.5),
      decoration: BoxDecoration(
        color: Colors.white,
        shape: BoxShape.circle,
        border: Border.all(
          color: const Color(0xFFDCE7D8),
        ),
      ),
      child: ClipOval(
        child: imageUrl == null
            ? fallback()
            : Image.network(
                imageUrl,
                fit: BoxFit.cover,
                errorBuilder: (_, __, ___) => fallback(),
              ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final clean = name.trim().isEmpty ? 'HPJ Member' : name.trim();
    final initial = clean.substring(0, 1).toUpperCase();
    final imageUrl = _profileImageUrl();

    return Container(
      decoration: BoxDecoration(
        color: const Color(0xFFFFFEFB),
        borderRadius: BorderRadius.circular(24),
        border: Border.all(color: const Color(0xFFE1E8DE)),
        boxShadow: [
          BoxShadow(
            color: const Color(0xFF174B36).withOpacity(.045),
            blurRadius: 18,
            offset: const Offset(0, 8),
          ),
        ],
      ),
      clipBehavior: Clip.antiAlias,
      child: Stack(
        children: [
          Positioned(
            right: -17,
            top: -22,
            child: Icon(
              Icons.eco_rounded,
              size: 126,
              color: const Color(0xFF76A86E).withOpacity(.075),
            ),
          ),
          Padding(
            padding: const EdgeInsets.fromLTRB(16, 15, 15, 15),
            child: Row(
              children: [
                _identityImage(
                  initial: initial,
                  imageUrl: imageUrl,
                ),
                const SizedBox(width: 13),
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      const Text(
                        'MY HPJ ACCOUNT',
                        style: TextStyle(
                          color: FarmColors.green,
                          fontSize: 8.7,
                          fontWeight: FontWeight.w900,
                          letterSpacing: .82,
                        ),
                      ),
                      const SizedBox(height: 3),
                      Text(
                        clean,
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: const TextStyle(
                          color: FarmColors.ink,
                          fontSize: 18.5,
                          height: 1.05,
                          fontWeight: FontWeight.w900,
                          letterSpacing: -.35,
                        ),
                      ),
                      if (email.trim().isNotEmpty) ...[
                        const SizedBox(height: 4),
                        Text(
                          email.trim(),
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: const TextStyle(
                            color: FarmColors.mutedText,
                            fontSize: 9.7,
                            fontWeight: FontWeight.w600,
                          ),
                        ),
                      ],
                    ],
                  ),
                ),
                const SizedBox(width: 9),
                Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 11,
                    vertical: 7,
                  ),
                  decoration: BoxDecoration(
                    color: const Color(0xFFF1F6EF),
                    borderRadius: BorderRadius.circular(999),
                    border: Border.all(
                      color: FarmColors.green.withOpacity(.08),
                    ),
                  ),
                  child: const Text(
                    'SHOP HPJ',
                    style: TextStyle(
                      color: FarmColors.deepGreen,
                      fontSize: 8.2,
                      fontWeight: FontWeight.w900,
                      letterSpacing: .42,
                    ),
                  ),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }
