  @override
  Widget build(BuildContext context) {
    final desktopWeb =
        kIsWeb && MediaQuery.sizeOf(context).width >= 1100;
    final heroHeight = desktopWeb ? 248.0 : 128.0;
    final heroRadius = desktopWeb ? 28.0 : 22.0;

    return FutureBuilder<List<HomeHeroSlide>>(
      future: _slidesFuture,
      builder: (context, snapshot) {
        // Keep the hero visually stable while waiting for the
        // Admin-managed/uploaded images. Defaults are used only after the
        // lookup finishes, never as a temporary loading photo.
        if (snapshot.connectionState == ConnectionState.waiting &&
            !snapshot.hasData) {
          return ClipRRect(
            borderRadius: BorderRadius.circular(heroRadius),
            child: Container(
              height: heroHeight,
              decoration: BoxDecoration(
                color: FarmColors.primarySoft,
                borderRadius: BorderRadius.circular(heroRadius),
                border: Border.all(color: FarmColors.line),
                boxShadow: [
                  BoxShadow(
                    color: FarmColors.shadow.withOpacity(0.06),
                    blurRadius: desktopWeb ? 24 : 18,
                    offset: Offset(0, desktopWeb ? 10 : 8),
                  ),
                ],
              ),
            ),
          );
        }

        final existingSlides = _cleanHomeHeroSlides(
          snapshot.data ?? const <HomeHeroSlide>[],
        );

        final firstSlide = existingSlides.isNotEmpty
            ? existingSlides.first
            : defaultHomeHeroSlides().first;

        final differentSlides = existingSlides.where((slide) {
          return slide.imageUrl.trim() != firstSlide.imageUrl.trim();
        }).toList();

        final secondSlide =
            differentSlides.isNotEmpty ? differentSlides.first : firstSlide;

        // Preserve the current 3-slide sequence:
        // Admin hero 1 -> Weekly Meal -> Admin hero 2.
        const totalCount = 3;
        _lastSlideCount = totalCount;

        if (_index >= totalCount) _index = 0;

        return ClipRRect(
          borderRadius: BorderRadius.circular(heroRadius),
          child: Container(
            height: heroHeight,
            decoration: BoxDecoration(
              color: FarmColors.primarySoft,
              borderRadius: BorderRadius.circular(heroRadius),
              border: Border.all(color: FarmColors.line),
              boxShadow: [
                BoxShadow(
                  color: FarmColors.shadow.withOpacity(0.06),
                  blurRadius: desktopWeb ? 24 : 18,
                  offset: Offset(0, desktopWeb ? 10 : 8),
                ),
              ],
            ),
            child: PageView.builder(
              controller: _controller,
              itemCount: totalCount,
              onPageChanged: (value) {
                if (!mounted) return;
                setState(() => _index = value);
              },
              itemBuilder: (context, pageIndex) {
                if (pageIndex == 0) {
                  return _buildExistingSlide(
                    slide: firstSlide,
                    totalCount: totalCount,
                  );
                }

                if (pageIndex == 1) {
                  return _buildWeeklyMealSlide(totalCount: totalCount);
                }

                return _buildExistingSlide(
                  slide: secondSlide,
                  totalCount: totalCount,
                );
              },
            ),
          ),
        );
      },
    );
  }
}

class WeeklyMealIdeasScreen extends StatefulWidget {
  final VoidCallback? onShopTap;
  final int? initialMealWeekday;

  const WeeklyMealIdeasScreen({
    super.key,
    this.onShopTap,
    this.initialMealWeekday,
  });

  @override
  State<WeeklyMealIdeasScreen> createState() => _WeeklyMealIdeasScreenState();
}

class _WeeklyMealIdeasScreenState extends State<WeeklyMealIdeasScreen> {
  String _selectedFilter = 'All';

  Future<void> _refreshMealsFromAdmin() async {
    await fetchPublicWeeklyMealIdeas();
    if (mounted) setState(() {});
  }

  @override
  void initState() {
    super.initState();
    unawaited(_refreshMealsFromAdmin());
    final preferences = hpjCurrentUserExperiencePreferences;
    if (preferences.dietaryStyle == 'vegan' ||
        preferences.recommendationStyle == 'vegan') {
      _selectedFilter = 'Ital / Vegan';
    } else if (preferences.dietaryStyle == 'vegetarian' ||
        preferences.recommendationStyle == 'vegetarian') {
      _selectedFilter = 'Vegetarian';
    }

    final returnWeekday = widget.initialMealWeekday;
    if (returnWeekday != null) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (!mounted) return;
        _openMeal(_mealForWeekday(returnWeekday));
      });
    }
  }

  List<_WeeklyMealIdea> get _filteredMeals {
    switch (_selectedFilter) {
      case 'Classic':
        return _weeklyMealIdeas.where((meal) => meal.isClassic).toList();
      case 'Vegetarian':
        return _weeklyMealIdeas.where((meal) => meal.isVegetarian).toList();
      case 'Ital / Vegan':
        return _weeklyMealIdeas.where((meal) => meal.isPlantBased).toList();
      default:
        return _weeklyMealIdeas;
    }
  }

  void _openMeal(_WeeklyMealIdea meal) {
    showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      useSafeArea: true,
      backgroundColor: Colors.transparent,
      builder: (sheetContext) {
        return _EliteMealDetailsSheet(
          meal: meal,
          showShopAction: widget.onShopTap != null,
          onShopTap: () {
            Navigator.of(sheetContext).pop();
            Navigator.of(context).pop();
            WidgetsBinding.instance.addPostFrameCallback((_) {
              widget.onShopTap?.call();
            });
          },
        );
      },
    );
  }

