class _EliteMealDetailsSheet extends StatefulWidget {
  final _WeeklyMealIdea meal;
  final bool showShopAction;
  final VoidCallback onShopTap;

  const _EliteMealDetailsSheet({
    required this.meal,
    required this.showShopAction,
    required this.onShopTap,
  });

  @override
  State<_EliteMealDetailsSheet> createState() => _EliteMealDetailsSheetState();
}

class _EliteMealDetailsSheetState extends State<_EliteMealDetailsSheet> {
  late Future<List<Product>> _productsFuture;
  final Set<String> _selectedIngredients = <String>{};

  _WeeklyMealIdea get meal => widget.meal;
  bool get showShopAction => widget.showShopAction;

  @override
  void initState() {
    super.initState();
    _productsFuture = showShopAction
        ? fetchProductsForCustomerUi(
            forceRefresh: false,
            timeout: const Duration(seconds: 8),
          )
        : Future<List<Product>>.value(const <Product>[]);
  }

  String _ingredientKey(String value) {
    return value
        .trim()
        .toLowerCase()
        .replaceAll(RegExp(r'[_-]+'), ' ')
        .replaceAll(RegExp(r'[^a-z0-9 ]+'), ' ')
        .replaceAll(RegExp(r'\s+'), ' ')
        .trim();
  }

  Product? _matchingProduct(
    String ingredient,
    List<Product> products, {
    bool requireAvailable = false,
  }) {
    final ingredientKey = _ingredientKey(ingredient);
    if (ingredientKey.isEmpty) return null;

    final candidates = products.where((product) {
      final productKey = _ingredientKey(product.name);
      if (productKey.isEmpty) return false;
      if (requireAvailable && !product.canAddToCart) return false;
      return productKey == ingredientKey ||
          productKey.contains(ingredientKey) ||
          ingredientKey.contains(productKey);
    }).toList();

    if (candidates.isEmpty) return null;

    candidates.sort((a, b) {
      final aExact = _ingredientKey(a.name) == ingredientKey;
      final bExact = _ingredientKey(b.name) == ingredientKey;
      if (aExact != bExact) return aExact ? -1 : 1;
      if (a.canAddToCart != b.canAddToCart) {
        return a.canAddToCart ? -1 : 1;
      }
      return a.name.toLowerCase().compareTo(b.name.toLowerCase());
    });

    return candidates.first;
  }

  String _recipeIngredientKey(HpjMealProductIngredient ingredient) {
    final id = ingredient.productId.trim();
    if (id.isNotEmpty) return 'id:$id';
    return 'name:${_ingredientKey(ingredient.productName)}';
  }

  Product? _matchingRecipeProduct(
    HpjMealProductIngredient ingredient,
    List<Product> products, {
    bool requireAvailable = false,
  }) {
    final productId = ingredient.productId.trim();

    if (productId.isNotEmpty) {
      for (final product in products) {
        if (product.id.trim() != productId) continue;
        if (requireAvailable && !product.canAddToCart) return null;
        return product;
      }
    }

    return _matchingProduct(
      ingredient.productName,
      products,
      requireAvailable: requireAvailable,
    );
  }

  List<Product> _availableIngredientProducts(List<Product> products) {
    final result = <Product>[];
    final seen = <String>{};

    for (final ingredient in meal.resolvedProductIngredients) {
      final product = _matchingRecipeProduct(
        ingredient,
        products,
        requireAvailable: true,
      );
      if (product == null) continue;
      final id = product.id.trim();
      if (id.isEmpty || !seen.add(id)) continue;
      result.add(product);
    }

    return result;
  }

  List<Product> _selectedProducts(List<Product> products) {
    final result = <Product>[];
    final seen = <String>{};

    for (final ingredient in meal.resolvedProductIngredients) {
      if (!_selectedIngredients.contains(_recipeIngredientKey(ingredient))) {
        continue;
      }

      final product = _matchingRecipeProduct(
        ingredient,
        products,
        requireAvailable: true,
      );
      if (product == null) continue;
      final id = product.id.trim();
      if (id.isEmpty || !seen.add(id)) continue;
      result.add(product);
    }

    return result;
  }

  void _openIngredientInShop(String ingredient) {
    final query = ingredient.trim();
    if (query.isEmpty) return;

    mealIngredientShopSearchRequest.value = null;
    mealIngredientShopSearchRequest.value = query;
    mealIngredientReturnLabel.value = query;
    mealIngredientReturnWeekday.value = meal.weekday;

    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text('Searching shop for $query...'),
        behavior: SnackBarBehavior.floating,
      ),
    );

    widget.onShopTap();
  }

  void _openAllFreshIngredientsInShop() {
    mealIngredientShopSearchRequest.value = null;
    mealIngredientReturnLabel.value = meal.name;
    mealIngredientReturnWeekday.value = meal.weekday;
    widget.onShopTap();
  }

  void _addOneIngredientToMyBox(
    HpjMealProductIngredient ingredient,
    List<Product> products,
  ) {
    final product = _matchingRecipeProduct(
      ingredient,
      products,
      requireAvailable: true,
    );

    if (product == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text('${ingredient.productName} is not available right now.'),
          behavior: SnackBarBehavior.floating,
        ),
      );
      return;
    }

    mealIngredientCartAddRequest.value = null;
    mealIngredientCartAddRequest.value = <Product>[product];

    setState(() {
      _selectedIngredients.remove(_recipeIngredientKey(ingredient));
    });

    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text('${product.name} added to My Box.'),
        behavior: SnackBarBehavior.floating,
      ),
    );
  }

  void _addSelectedToMyBox(List<Product> products) {
    final selectedProducts = _selectedProducts(products);
    if (selectedProducts.isEmpty) return;

    mealIngredientCartAddRequest.value = null;
    mealIngredientCartAddRequest.value = selectedProducts;

    final count = selectedProducts.length;
    setState(() => _selectedIngredients.clear());

    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(
          '$count ${count == 1 ? 'ingredient was' : 'ingredients were'} added to My Box.',
        ),
        behavior: SnackBarBehavior.floating,
      ),
    );
  }

  void _selectAllAvailable(List<Product> products) {
    final next = <String>{};

    for (final ingredient in meal.resolvedProductIngredients) {
      if (_matchingRecipeProduct(
            ingredient,
            products,
            requireAvailable: true,
          ) !=
          null) {
        next.add(_recipeIngredientKey(ingredient));
      }
    }

    setState(() {
      _selectedIngredients
        ..clear()
        ..addAll(next);
    });
  }

  Widget _infoItem({
    required IconData icon,
    required String label,
    required String value,
  }) {
    return Expanded(
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 9, vertical: 10),
        decoration: BoxDecoration(
          color: FarmColors.card,
          borderRadius: BorderRadius.circular(16),
          border: Border.all(color: FarmColors.line),
        ),
        child: Column(
          children: [
            Icon(icon, color: FarmColors.green, size: 19),
            const SizedBox(height: 5),
            Text(
              value,
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              style: const TextStyle(
                color: FarmColors.ink,
                fontSize: 12,
                fontWeight: FontWeight.w900,
              ),
            ),
            const SizedBox(height: 2),
            Text(
              label,
              style: const TextStyle(
                color: FarmColors.mutedText,
                fontSize: 9.5,
                fontWeight: FontWeight.w700,
              ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _sectionTitle(String title, String subtitle) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Text(
          title,
          style: const TextStyle(
            color: FarmColors.ink,
            fontSize: 17,
            fontWeight: FontWeight.w900,
          ),
        ),
        const SizedBox(height: 2),
        Text(
          subtitle,
          style: const TextStyle(
            color: FarmColors.mutedText,
            fontSize: 10.5,
            fontWeight: FontWeight.w700,
          ),
        ),
      ],
    );
  }

  Widget _pantryIngredientWrap(List<String> ingredients) {
    return Wrap(
      spacing: 7,
      runSpacing: 7,
      children: ingredients.map((ingredient) {
        return Container(
          padding: const EdgeInsets.symmetric(horizontal: 9, vertical: 7),
          decoration: BoxDecoration(
            color: FarmColors.card,
            borderRadius: BorderRadius.circular(999),
            border: Border.all(color: FarmColors.line),
          ),
          child: Row(
            mainAxisSize: MainAxisSize.min,
            children: [
              const Icon(
                Icons.kitchen_outlined,
                size: 13,
                color: FarmColors.mutedText,
              ),
              const SizedBox(width: 4),
              Text(
                ingredient,
                style: const TextStyle(
                  color: FarmColors.mutedText,
                  fontSize: 10.5,
                  fontWeight: FontWeight.w800,
                ),
              ),
            ],
          ),
        );
      }).toList(),
    );
  }

  Widget _freshIngredientWrap(List<Product> products) {
    final ingredients = meal.resolvedProductIngredients;

    if (ingredients.isEmpty) {
      return const Text(
        'No fresh ingredients have been added to this recipe yet.',
        style: TextStyle(
          color: FarmColors.mutedText,
          fontWeight: FontWeight.w700,
        ),
      );
    }

    return Column(
      children: [
        for (var index = 0; index < ingredients.length; index++) ...[
          Builder(
            builder: (context) {
              final ingredient = ingredients[index];
              final product = _matchingRecipeProduct(ingredient, products);
              final available = product?.canAddToCart == true;
              final key = _recipeIngredientKey(ingredient);
              final selected = _selectedIngredients.contains(key);
              final displayName = product?.name.trim().isNotEmpty == true
                  ? product!.name.trim()
                  : ingredient.productName.trim();
              final amountLabel = ingredient.amountLabel;
              final sellingUnit = product?.unit?.trim() ?? '';

              return Container(
                padding: const EdgeInsets.fromLTRB(10, 9, 8, 9),
                decoration: BoxDecoration(
                  color: selected
                      ? FarmColors.successSoft
                      : FarmColors.card,
                  borderRadius: BorderRadius.circular(16),
                  border: Border.all(
                    color: selected
                        ? FarmColors.green.withOpacity(0.28)
                        : FarmColors.line,
                  ),
                ),
                child: Row(
                  children: [
                    Checkbox(
                      value: selected,
                      activeColor: FarmColors.green,
                      visualDensity: VisualDensity.compact,
                      onChanged: available
                          ? (value) {
                              setState(() {
                                if (value == true) {
                                  _selectedIngredients.add(key);
                                } else {
                                  _selectedIngredients.remove(key);
                                }
                              });
                            }
                          : null,
                    ),
                    const SizedBox(width: 3),
                    Expanded(
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Text(
                            displayName,
                            style: TextStyle(
                              color: available
                                  ? FarmColors.ink
                                  : FarmColors.mutedText,
                              fontSize: 12.5,
                              fontWeight: FontWeight.w900,
                            ),
                          ),
                          const SizedBox(height: 2),
                          Text(
                            [
                              if (amountLabel.isNotEmpty)
                                'Recipe: $amountLabel',
                              if (available && sellingUnit.isNotEmpty)
                                'HPJ unit: $sellingUnit',
                              if (!available) 'Currently unavailable',
                            ].join(' • '),
                            style: const TextStyle(
                              color: FarmColors.mutedText,
                              fontSize: 9.5,
                              height: 1.25,
                              fontWeight: FontWeight.w700,
                            ),
                          ),
                        ],
                      ),
                    ),
                    if (showShopAction) ...[
                      IconButton(
                        tooltip: 'Find $displayName in Shop',
                        visualDensity: VisualDensity.compact,
                        onPressed: () => _openIngredientInShop(displayName),
                        icon: const Icon(
                          Icons.search_rounded,
                          size: 18,
                          color: FarmColors.green,
                        ),
                      ),
                      const SizedBox(width: 2),
                      FilledButton(
                        onPressed: available
                            ? () => _addOneIngredientToMyBox(
                                  ingredient,
                                  products,
                                )
                            : null,
                        style: FilledButton.styleFrom(
                          minimumSize: const Size(66, 36),
                          padding: const EdgeInsets.symmetric(
                            horizontal: 10,
                            vertical: 8,
                          ),
                          tapTargetSize: MaterialTapTargetSize.shrinkWrap,
                        ),
                        child: const Text(
                          '+ Add',
                          style: TextStyle(
                            fontSize: 10.5,
                            fontWeight: FontWeight.w900,
                          ),
                        ),
                      ),
                    ],
                  ],
                ),
              );
            },
          ),
          if (index != ingredients.length - 1)
            const SizedBox(height: 8),
        ],
      ],
    );
  }

  @override
  Widget build(BuildContext context) {
    final height = MediaQuery.sizeOf(context).height;

    return Container(
      constraints: BoxConstraints(maxHeight: height * 0.93),
      decoration: const BoxDecoration(
        color: FarmColors.cream,
        borderRadius: BorderRadius.vertical(top: Radius.circular(30)),
      ),
      child: Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          const SizedBox(height: 10),
          Container(
            height: 5,
            width: 44,
            decoration: BoxDecoration(
              color: FarmColors.line,
              borderRadius: BorderRadius.circular(999),
            ),
          ),
          const SizedBox(height: 10),
          Flexible(
            child: SingleChildScrollView(
              padding: const EdgeInsets.fromLTRB(16, 0, 16, 20),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  ClipRRect(
                    borderRadius: BorderRadius.circular(24),
                    child: AspectRatio(
                      aspectRatio: 16 / 9,
                      child: Stack(
