class _HpjCustomerHeaderActions extends StatelessWidget {
  final String parish;
  final String firstName;
  final VoidCallback? onParishTap;
  final bool compact;
  final bool includeCart;
  final int cartItemCount;
  final VoidCallback? onCartTap;

  const _HpjCustomerHeaderActions({
    required this.parish,
    required this.firstName,
    this.onParishTap,
    this.compact = true,
    this.includeCart = false,
    this.cartItemCount = 0,
    this.onCartTap,
  });

  String? _profileImageUrl() {
    final metadata =
        supabase.auth.currentUser?.userMetadata ?? const <String, dynamic>{};

    for (final key in const <String>[
      'avatar_url',
      'picture',
      'photo_url',
      'profile_photo_url',
      'image_url',
    ]) {
      final raw = metadata[key]?.toString().trim() ?? '';
      if (raw.isEmpty) continue;

      final uri = Uri.tryParse(raw);
      if (uri != null && (uri.scheme == 'https' || uri.scheme == 'http')) {
        return raw;
      }
    }

    return null;
  }

  void _openNotifications(BuildContext context) {
    Navigator.of(context).push<void>(
      MaterialPageRoute<void>(
        builder: (_) => const NotificationsScreen(),
      ),
    );
  }

  Future<void> _handleAccountMenuSelection(
    BuildContext context,
    String value,
  ) async {
    if (value == 'customer') return;

    if (value == 'account') {
      await Navigator.of(context).push<void>(
        MaterialPageRoute<void>(
          builder: (_) => const CustomerProfileScreen(),
        ),
      );
      return;
    }

    if (value == 'signout') {
      await signOutFromHpjSession();
      if (!context.mounted) return;
      Navigator.of(context).pushAndRemoveUntil(
        MaterialPageRoute<void>(builder: (_) => const AuthGate()),
        (route) => false,
      );
      return;
    }

    await _openHpjMobilePortalRoot(
      context,
      portal: value,
    );
  }

  @override
  Widget build(BuildContext context) {
    final cleanParish =
        parish.trim().isEmpty ? 'St. Elizabeth' : parish.trim();
    final cleanName = firstName.trim().isEmpty ? 'HPJ' : firstName.trim();
    final initial = cleanName.substring(0, 1).toUpperCase();
    final imageUrl = _profileImageUrl();
    final controlSize = compact ? 42.0 : 44.0;

    return Row(
      mainAxisSize: MainAxisSize.min,
      children: [
        Semantics(
          button: true,
          label: 'Shopping parish: $cleanParish',
          child: Material(
            color: Colors.transparent,
            child: InkWell(
              onTap: onParishTap,
              customBorder: const CircleBorder(),
              child: Ink(
                width: controlSize,
                height: controlSize,
                decoration: BoxDecoration(
                  color: const Color(0xFFF4F7F1),
                  shape: BoxShape.circle,
                  border: Border.all(
                    color: const Color(0xFFDDE5DA),
                  ),
                ),
                child: const Center(
                  child: Icon(
                    Icons.location_on_rounded,
                    color: FarmColors.deepGreen,
                    size: 18,
                  ),
                ),
              ),
            ),
          ),
        ),
        SizedBox(width: compact ? 6 : 8),
        FutureBuilder<List<FarmNotification>>(
          future: fetchFarmNotifications(),
          builder: (context, snapshot) {
            final unreadCount = (snapshot.data ?? const <FarmNotification>[])
                .where((notice) => !notice.isRead)
                .length;

            return Tooltip(
              message: 'Notifications',
              child: Material(
                color: Colors.transparent,
                child: InkWell(
                  onTap: () => _openNotifications(context),
                  customBorder: const CircleBorder(),
                  child: Ink(
                    width: controlSize,
                    height: controlSize,
                    decoration: BoxDecoration(
                      color: const Color(0xFFFFFEFB),
                      shape: BoxShape.circle,
                      border: Border.all(
                        color: const Color(0xFFE2E7DE),
                      ),
                    ),
                    child: Stack(
                      clipBehavior: Clip.none,
                      children: [
                        const Center(
                          child: Icon(
                            Icons.notifications_none_rounded,
                            color: FarmColors.deepGreen,
                            size: 21,
                          ),
                        ),
                        if (unreadCount > 0)
                          Positioned(
                            right: -1,
                            top: -2,
                            child: Container(
                              constraints: const BoxConstraints(
                                minWidth: 17,
                                minHeight: 17,
                              ),
                              padding: const EdgeInsets.symmetric(
                                horizontal: 4,
                                vertical: 2,
                              ),
                              decoration: BoxDecoration(
                                color: const Color(0xFFE53935),
                                borderRadius: BorderRadius.circular(999),
                                border: Border.all(
                                  color: const Color(0xFFFFFEFB),
                                  width: 1.5,
                                ),
                              ),
                              alignment: Alignment.center,
                              child: Text(
                                unreadCount > 99 ? '99+' : '$unreadCount',
                                style: const TextStyle(
                                  color: Colors.white,
                                  fontSize: 8.5,
                                  height: 1,
                                  fontWeight: FontWeight.w900,
                                ),
                              ),
                            ),
                          ),
                      ],
                    ),
                  ),
                ),
              ),
            );
          },
        ),
        SizedBox(width: compact ? 6 : 8),
        FutureBuilder<OwnerWorkspaceAccessSnapshot>(
          future: fetchOwnerWorkspaceAccessSnapshot(),
          builder: (context, accessSnapshot) {
            final access = accessSnapshot.data;
            final farmer = access?.farmerProfile;
            final business = access?.businessAccount;
            final settings = access?.programSettings;
            final staffRole = normalizeStaffRole(access?.staffRole ?? '');
            final hasStaff = access?.hasStaffAccess == true;

            final farmerApproved = farmer?.isApproved == true &&
                (settings?.farmerWorkspaceEnabled ?? false);
            final businessApproved = business?.isApproved == true &&
                (settings?.wholesaleWorkspaceEnabled ?? false);

            PopupMenuItem<String> portalItem({
              required String value,
              required IconData icon,
              required String title,
              String? subtitle,
              bool current = false,
            }) {
              return PopupMenuItem<String>(
                value: value,
                height: subtitle == null ? 48 : 58,
                child: Row(
                  children: [
                    Container(
                      width: 34,
                      height: 34,
                      alignment: Alignment.center,
                      decoration: BoxDecoration(
                        color: current
                            ? FarmColors.primarySoft
                            : const Color(0xFFF4F7F1),
                        borderRadius: BorderRadius.circular(11),
                      ),
                      child: Icon(
                        icon,
                        size: 18,
                        color: FarmColors.deepGreen,
                      ),
                    ),
                    const SizedBox(width: 10),
                    Expanded(
                      child: Column(
                        mainAxisSize: MainAxisSize.min,
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Text(
                            title,
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: const TextStyle(
                              color: FarmColors.ink,
                              fontSize: 12.2,
                              fontWeight: FontWeight.w900,
                            ),
                          ),
                          if (subtitle != null && subtitle.trim().isNotEmpty) ...[
                            const SizedBox(height: 2),
                            Text(
                              subtitle,
                              maxLines: 1,
                              overflow: TextOverflow.ellipsis,
                              style: const TextStyle(
                                color: FarmColors.mutedText,
                                fontSize: 9.2,
                                fontWeight: FontWeight.w700,
                              ),
                            ),
                          ],
                        ],
                      ),
                    ),
                    if (current)
                      const Icon(
                        Icons.check_circle_rounded,
                        color: FarmColors.green,
                        size: 18,
                      ),
                  ],
                ),
              );
            }

            return Tooltip(
              message: 'Account & portals',
              child: PopupMenuButton<String>(
                tooltip: '',
                color: const Color(0xFFFFFEFB),
                elevation: 12,
                offset: const Offset(0, 8),
                shape: RoundedRectangleBorder(
                  borderRadius: BorderRadius.circular(18),
                  side: const BorderSide(color: Color(0xFFE0E6DD)),
                ),
                onSelected: (value) {
                  unawaited(_handleAccountMenuSelection(context, value));
                },
                itemBuilder: (menuContext) => <PopupMenuEntry<String>>[
                  portalItem(
                    value: 'customer',
                    icon: Icons.shopping_bag_outlined,
                    title: 'Shop HPJ',
                    subtitle: 'Customer marketplace',
                    current: true,
                  ),
                  if (farmer != null)
                    portalItem(
                      value: 'farmer',
                      icon: Icons.agriculture_outlined,
                      title: farmerApproved
                          ? 'Farmer Portal'
                          : 'Farmer Application',
                      subtitle: farmerApproved
                          ? (farmer.farmName.trim().isEmpty
