const List<String> _hpjCustomerParishes = <String>[
  'Hanover',
  'Westmoreland',
  'St. James',
  'Trelawny',
  'St. Elizabeth',
  'Manchester',
  'Clarendon',
  'St. Ann',
  'St. Catherine',
  'St. Mary',
  'St. Andrew',
  'Kingston',
  'Portland',
  'St. Thomas',
];

String _hpjCanonicalCustomerParish(String value) {
  final clean = value.trim();
  if (clean.isEmpty) return 'St. Elizabeth';

  String key(String input) => input
      .trim()
      .toLowerCase()
      .replaceAll('saint ', 'st ')
      .replaceAll('.', '')
      .replaceAll(' parish', '')
      .replaceAll(RegExp(r'\s+'), ' ');

  final normalized = key(clean.split('•').first.split(' - ').first);
  for (final parish in _hpjCustomerParishes) {
    if (key(parish) == normalized) return parish;
  }

  return 'St. Elizabeth';
}

class _HpjGlobalCustomerUtilityBar extends StatefulWidget {
  const _HpjGlobalCustomerUtilityBar();

  @override
  State<_HpjGlobalCustomerUtilityBar> createState() =>
      _HpjGlobalCustomerUtilityBarState();
}

class _HpjGlobalCustomerUtilityBarState
    extends State<_HpjGlobalCustomerUtilityBar> {
  late Future<CustomerProfile?> _profileFuture;
  String _parish = 'St. Elizabeth';

  @override
  void initState() {
    super.initState();
    _profileFuture = fetchCurrentCustomerProfile();
    unawaited(_restoreParish());
  }

  Future<void> _restoreParish() async {
    try {
      final saved = await HpjSmartLocalStore.readString('shop_near_area');
      final checkout = await HpjSmartLocalStore.readString('checkout_zone');
      final raw = (saved ?? '').trim().isNotEmpty
          ? saved!.trim()
          : (checkout ?? '').trim();
      final next = _hpjCanonicalCustomerParish(raw);
      if (!mounted) return;
      setState(() => _parish = next);
      if (hpjCustomerParishPreference.value != next) {
        hpjCustomerParishPreference.value = next;
      }
    } catch (_) {
      // Keep the safe St. Elizabeth default.
    }
  }

  Future<void> _pickParish() async {
    final picked = await showModalBottomSheet<String>(
      context: context,
      useSafeArea: true,
      showDragHandle: true,
      backgroundColor: const Color(0xFFFFFEFB),
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(26)),
      ),
      builder: (sheetContext) {
        return ListView(
          shrinkWrap: true,
          padding: const EdgeInsets.fromLTRB(18, 4, 18, 24),
          children: [
            const Text(
              'Shopping parish',
              style: TextStyle(
                color: FarmColors.ink,
                fontSize: 18,
                fontWeight: FontWeight.w900,
                letterSpacing: -.25,
              ),
            ),
            const SizedBox(height: 4),
            const Text(
              'Parish first, Jamaica always. HPJ will show farms and fresh produce from your selected parish first, then the rest of Jamaica.',
              style: TextStyle(
                color: FarmColors.mutedText,
                fontSize: 10.5,
                height: 1.35,
                fontWeight: FontWeight.w700,
              ),
            ),
            const SizedBox(height: 12),
            ..._hpjCustomerParishes.map((parish) {
              final selected = parish == _parish;
              return ListTile(
                dense: true,
                contentPadding: const EdgeInsets.symmetric(horizontal: 4),
                leading: Container(
                  width: 34,
                  height: 34,
                  alignment: Alignment.center,
                  decoration: BoxDecoration(
                    color: selected
                        ? const Color(0xFFE6F1E2)
                        : const Color(0xFFF4F7F1),
                    borderRadius: BorderRadius.circular(11),
                  ),
                  child: Icon(
                    Icons.location_on_outlined,
                    color: selected ? FarmColors.green : FarmColors.deepGreen,
                    size: 18,
                  ),
                ),
                title: Text(
                  parish,
                  style: TextStyle(
                    color: FarmColors.ink,
                    fontSize: 12.2,
                    fontWeight: selected ? FontWeight.w900 : FontWeight.w800,
                  ),
                ),
                trailing: selected
                    ? const Icon(
                        Icons.check_circle_rounded,
                        color: FarmColors.green,
                        size: 19,
                      )
                    : null,
                onTap: () => Navigator.of(sheetContext).pop(parish),
              );
            }),
          ],
        );
      },
    );

    if (!mounted || picked == null || picked.trim().isEmpty) return;
    final canonical = _hpjCanonicalCustomerParish(picked);
    setState(() => _parish = canonical);

    await HpjSmartLocalStore.writeString('shop_near_area', canonical);

    if (hpjCustomerParishPreference.value != canonical) {
      hpjCustomerParishPreference.value = canonical;
    }

    hpjShopParishRequest.value = canonical;
  }

  @override
  Widget build(BuildContext context) {
    if (!hpjUseMobileAppPresentation(context)) {
      return const SizedBox.shrink();
    }

    return SafeArea(
      bottom: false,
      child: Container(
        width: double.infinity,
        padding: const EdgeInsets.fromLTRB(14, 8, 14, 6),
        color: FarmColors.background,
        child: FutureBuilder<CustomerProfile?>(
          future: _profileFuture,
          builder: (context, snapshot) {
            final firstName = personalizedFirstName(snapshot.data);
            return Row(
              children: [
                SizedBox(
                  width: 82,
                  height: 34,
                  child: Image.asset(
                    'lib/assets/images/logo.png',
                    fit: BoxFit.contain,
                    alignment: Alignment.centerLeft,
                    filterQuality: FilterQuality.high,
                    errorBuilder: (_, __, ___) => const Align(
                      alignment: Alignment.centerLeft,
                      child: Text(
                        'HPJ',
                        style: TextStyle(
                          color: FarmColors.deepGreen,
                          fontSize: 18,
                          fontWeight: FontWeight.w900,
                        ),
                      ),
                    ),
                  ),
                ),
                const Spacer(),
                _HpjCustomerHeaderActions(
                  parish: _parish,
                  firstName: firstName,
                  onParishTap: () => unawaited(_pickParish()),
                  compact: true,
                ),
              ],
            );
          },
        ),
      ),
    );
  }
}


