class _HomeScreenState extends State<HomeScreen> {
  bool _homeSocialIsFavorite(Product product) {
    final callback = widget.isFavorite;
    if (callback != null) {
      return callback(product);
    }

    final productId = product.id.trim();
    if (productId.isEmpty) return false;

    return widget.favoriteProducts.any(
      (favorite) => favorite.id.trim() == productId,
    );
  }

  void _homeSocialToggleFavorite(Product product) {
    final callback = widget.onToggleFavorite;
    if (callback != null) {
      callback(product);
      return;
    }

    // Backward-compatible fallback for older root wiring.
    // Persist the favorite even when the parent has not yet supplied
    // the Phase60 in-memory callback.
    final nextValue = !_homeSocialIsFavorite(product);
    unawaited(
      setFavoriteForCurrentUser(
        product,
        isFavorite: nextValue,
      ),
    );
  }

  void _showDealsOnHome() {
    homeSearchFocusNode.unfocus();
    homeSearchController.clear();

    setState(() {
      homeSearchQuery = '';
      selectedHomeCategory = 'All';
      selectedHomeNutrient = 'All';
      selectedHomeAvailability = 'Any availability';
      selectedHomePrice = 'Any price';
      selectedHomeFarm = 'All farms';
      selectedHomeSpecial = 'Deals';
      selectedHomeSort = 'Recommended';
    });
  }

  late Future<List<Product>> homeProductsFuture;
  late Future<List<Product>> buyAgainProductsFuture;
  late Future<CustomerProfile?> customerProfileFuture;
  late Future<LoyaltySummary> loyaltySummaryFuture;
  late Future<List<HomeHeroSlide>> homeHeroSlidesFuture;
  late Future<List<FarmOrder>> homeOrdersFuture;
  late Future<HpjSponsorCampaign?> sponsoredCampaignFuture;
  late Future<List<FarmPublicProfileRecord>> socialFarmsFuture;
  List<Product> cachedHomeProducts = const <Product>[];
  List<Product> homeRecentlyViewedProducts = const <Product>[];
  final TextEditingController homeSearchController = TextEditingController();
  final FocusNode homeSearchFocusNode = FocusNode();
  String homeSearchQuery = '';
  String selectedHomeCategory = 'All';
  String selectedHomeNutrient = 'All';
  String selectedHomeAvailability = 'Any availability';
  String selectedHomePrice = 'Any price';
  String selectedHomeFarm = 'All farms';
  String selectedHomeSpecial = 'All';
  String selectedHomeSort = 'Recommended';
  int agricultureFeedRefreshKey = 0;

  // HPJ MOBILE VISUAL MATCH — native Home mirrors the clean community-first
  // reference while all existing commerce/social systems stay intact.
  Set<String> _mobileFollowedFarmIds = <String>{};
  Set<String> _mobileFollowedProductIds = <String>{};
  Set<String> _mobileFollowedCategories = <String>{};
  String _homeNearArea = 'St. Elizabeth';
  bool _homeNearAreaReady = false;

  @override
  void initState() {
    super.initState();
    hpjCustomerParishPreference.addListener(
      _applySharedCustomerParishPreference,
    );
    homeProductsFuture = loadHomeProducts();
    buyAgainProductsFuture = fetchBuyAgainProductsForCustomerUi();
    homeOrdersFuture = fetchOrders();
    sponsoredCampaignFuture = fetchActiveCustomerHomeSponsor();
    socialFarmsFuture = fetchPublishedFarmPublicProfiles(limit: 12);
    unawaited(_loadHomeRecentlyViewed());
    unawaited(_loadUserPreferences());
    customerProfileFuture = fetchCurrentCustomerProfile();
    loyaltySummaryFuture = fetchLoyaltySummary();
    homeHeroSlidesFuture = fetchPublicHomeHeroSlides();
    if (!kIsWeb) {
      unawaited(_loadMobileReferenceSocialState());
      unawaited(_loadHomeNearArea());
    } else {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (!mounted || !hpjUseMobileAppPresentation(context)) return;
        unawaited(_loadMobileReferenceSocialState());
        unawaited(_loadHomeNearArea());
      });
    }
    homeSearchFocusNode.addListener(() {
      if (mounted) setState(() {});
    });
  }


  void _applySharedCustomerParishPreference() {
    final next = _hpjCanonicalCustomerParish(
      hpjCustomerParishPreference.value,
    );

    if (!mounted || next == _homeNearArea) return;

    setState(() {
      _homeNearArea = next;
      _homeNearAreaReady = true;
    });
  }

  Future<void> _loadHomeNearArea() async {
    try {
      final saved = await HpjSmartLocalStore.readString('shop_near_area');
      final checkout = await HpjSmartLocalStore.readString('checkout_zone');
      final value = (saved ?? '').trim().isNotEmpty
          ? saved!.trim()
          : (checkout ?? '').trim().isNotEmpty
              ? checkout!.trim()
              : 'St. Elizabeth';

      if (!mounted) return;

      final canonical = _hpjCanonicalCustomerParish(value);

      setState(() {
        _homeNearArea = canonical;
        _homeNearAreaReady = true;
      });

      if (hpjCustomerParishPreference.value != canonical) {
        hpjCustomerParishPreference.value = canonical;
      }
    } catch (_) {
      if (!mounted) return;
      setState(() => _homeNearAreaReady = true);
    }
  }

