      'St. James',
      'Trelawny',
      'St. Elizabeth',
      'Manchester',
      'Clarendon',
      'St. Ann',
      'St. Catherine',
      'St. Mary',
      'St. Andrew',
      'Kingston',
      'Portland',
      'St. Thomas',
