    final selected = await showModalBottomSheet<String>(
      context: context,
      useSafeArea: true,
      backgroundColor: Colors.transparent,
      builder: (sheetContext) {
        return Container(
          constraints: BoxConstraints(
            maxHeight: MediaQuery.sizeOf(sheetContext).height * .72,
          ),
          decoration: const BoxDecoration(
            color: Color(0xFFFFFEFB),
            borderRadius: BorderRadius.vertical(
              top: Radius.circular(28),
            ),
          ),
          child: Column(
            children: [
              const SizedBox(height: 10),
              Container(
                width: 42,
                height: 4,
                decoration: BoxDecoration(
                  color: const Color(0xFFD7DDD4),
                  borderRadius: BorderRadius.circular(999),
                ),
              ),
              const Padding(
                padding: EdgeInsets.fromLTRB(18, 18, 18, 8),
                child: Row(
                  children: [
                    Icon(
                      Icons.location_on_rounded,
                      color: FarmColors.green,
                      size: 21,
                    ),
                    SizedBox(width: 8),
                    Expanded(
                      child: Text(
                        'Choose your parish',
                        style: TextStyle(
                          color: FarmColors.deepGreen,
                          fontSize: 20,
                          fontWeight: FontWeight.w900,
                          letterSpacing: -.3,
                        ),
                      ),
                    ),
                  ],
                ),
              ),
              const Padding(
                padding: EdgeInsets.fromLTRB(18, 0, 18, 12),
                child: Align(
                  alignment: Alignment.centerLeft,
                  child: Text(
                    'HPJ will show farms and produce from this parish first, then the rest of Jamaica.',
                    style: TextStyle(
                      color: FarmColors.mutedText,
                      fontSize: 11.5,
                      fontWeight: FontWeight.w700,
                    ),
                  ),
                ),
              ),
              const Divider(height: 1),
              Expanded(
                child: ListView.separated(
                  padding: const EdgeInsets.fromLTRB(10, 8, 10, 18),
                  itemCount: parishes.length,
                  separatorBuilder: (_, __) => const SizedBox(height: 2),
                  itemBuilder: (context, index) {
                    final value = parishes[index];
                    final selectedNow =
                        _homeNearKey(value) == _homeNearKey(_homeNearArea);

                    return ListTile(
                      dense: true,
                      shape: RoundedRectangleBorder(
                        borderRadius: BorderRadius.circular(16),
                      ),
                      tileColor: selectedNow
                          ? const Color(0xFFEAF3E7)
                          : Colors.transparent,
                      leading: Icon(
                        selectedNow
                            ? Icons.check_circle_rounded
                            : Icons.location_on_outlined,
                        color: selectedNow
                            ? FarmColors.green
                            : FarmColors.mutedText,
                        size: 20,
                      ),
                      title: Text(
                        value,
