  Future<void> _openPremiumHomeOrder(FarmOrder order) async {
    await Navigator.push<void>(
      context,
      MaterialPageRoute<void>(
        builder: (_) => OrderDetailsScreen(
          orderId: order.id,
          onAddToCart: widget.onAddToCart,
          onOpenMyBox: widget.onViewMyBox,
