    FarmDataCache.clearOrders();
    setState(() {
      homeOrdersFuture = fetchOrders(forceRefresh: true);
    });
  }

  Widget _premiumContinueOrderRow(FarmOrder? activeOrder) {
    final hasBox = widget.cartItemCount > 0;
    final hasOrder = activeOrder != null;

    if (!hasBox && !hasOrder) return const SizedBox.shrink();

    Widget continueCard() {
      return Material(
        color: const Color(0xFFFFFEFB),
        borderRadius: BorderRadius.circular(20),
        child: InkWell(
          onTap: widget.onViewMyBox,
          borderRadius: BorderRadius.circular(20),
          child: Container(
            constraints: const BoxConstraints(minHeight: 98),
            padding: const EdgeInsets.fromLTRB(12, 11, 10, 11),
            decoration: BoxDecoration(
              borderRadius: BorderRadius.circular(20),
              border: Border.all(color: const Color(0xFFDCE5D8)),
              boxShadow: [
                BoxShadow(
                  color: const Color(0xFF173B30).withOpacity(.045),
                  blurRadius: 14,
                  offset: const Offset(0, 6),
                ),
              ],
            ),
            child: Row(
              children: [
                Container(
                  width: 40,
                  height: 40,
                  alignment: Alignment.center,
                  decoration: BoxDecoration(
                    color: const Color(0xFFEAF3E7),
                    borderRadius: BorderRadius.circular(13),
                  ),
                  child: const Icon(
                    Icons.shopping_bag_outlined,
                    color: FarmColors.green,
                    size: 20,
                  ),
                ),
                const SizedBox(width: 9),
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      const Text(
                        'Continue your box',
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: TextStyle(
                          color: FarmColors.ink,
                          fontSize: 12.2,
                          height: 1,
                          fontWeight: FontWeight.w900,
                        ),
                      ),
                      const SizedBox(height: 5),
                      Text(
                        '${widget.cartItemCount} ${widget.cartItemCount == 1 ? 'item is' : 'items are'} waiting. Pick up where you left off.',
                        maxLines: 2,
                        overflow: TextOverflow.ellipsis,
                        style: const TextStyle(
                          color: FarmColors.mutedText,
                          fontSize: 8.7,
                          height: 1.3,
                          fontWeight: FontWeight.w600,
                        ),
                      ),
                    ],
                  ),
                ),
                const SizedBox(width: 5),
                Container(
                  width: 32,
                  height: 32,
                  alignment: Alignment.center,
                  decoration: const BoxDecoration(
                    color: Color(0xFFE2F0DE),
                    shape: BoxShape.circle,
                  ),
                  child: const Icon(
                    Icons.arrow_forward_rounded,
                    color: FarmColors.green,
                    size: 18,
                  ),
                ),
              ],
            ),
          ),
        ),
      );
    }

    Widget orderCard(FarmOrder order) {
      final status = order.status.trim().replaceAll('_', ' ').toUpperCase();

      return Material(
        color: const Color(0xFFFFFEFB),
        borderRadius: BorderRadius.circular(20),
        child: InkWell(
          onTap: () => unawaited(_openPremiumHomeOrder(order)),
          borderRadius: BorderRadius.circular(20),
          child: Container(
            constraints: const BoxConstraints(minHeight: 98),
            padding: const EdgeInsets.fromLTRB(12, 10, 10, 10),
            decoration: BoxDecoration(
              borderRadius: BorderRadius.circular(20),
              border: Border.all(color: const Color(0xFFDCE5D8)),
              boxShadow: [
                BoxShadow(
                  color: const Color(0xFF173B30).withOpacity(.045),
                  blurRadius: 14,
                  offset: const Offset(0, 6),
                ),
              ],
            ),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Row(
                  children: [
                    Container(
                      width: 36,
                      height: 36,
                      alignment: Alignment.center,
                      decoration: BoxDecoration(
                        color: const Color(0xFFEAF3E7),
                        borderRadius: BorderRadius.circular(12),
                      ),
                      child: const Icon(
                        Icons.local_shipping_outlined,
                        color: FarmColors.green,
                        size: 19,
                      ),
                    ),
                    const SizedBox(width: 8),
                    Expanded(
                      child: Text(
                        'Order #${order.shortId}',
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: const TextStyle(
                          color: FarmColors.ink,
                          fontSize: 11.5,
                          fontWeight: FontWeight.w900,
                        ),
                      ),
                    ),
                    Container(
                      padding: const EdgeInsets.symmetric(
                        horizontal: 7,
                        vertical: 4,
                      ),
                      decoration: BoxDecoration(
                        color: const Color(0xFFFFF5DE),
                        borderRadius: BorderRadius.circular(999),
                      ),
                      child: Text(
                        status,
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: const TextStyle(
                          color: Color(0xFF946716),
                          fontSize: 7.1,
                          fontWeight: FontWeight.w900,
                        ),
                      ),
                    ),
                  ],
                ),
                const SizedBox(height: 8),
                Text(
                  order.formattedType,
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: const TextStyle(
                    color: FarmColors.mutedText,
                    fontSize: 8.6,
                    fontWeight: FontWeight.w700,
                  ),
                ),
                const SizedBox(height: 8),
                Row(
                  children: List.generate(4, (index) {
                    final active = index == 0 ||
                        order.status.trim().toLowerCase() != 'pending';
                    return Expanded(
                      child: Container(
                        height: 5,
                        margin: EdgeInsets.only(right: index == 3 ? 0 : 4),
                        decoration: BoxDecoration(
                          color: active
                              ? FarmColors.green
                              : const Color(0xFFDCE5D8),
                          borderRadius: BorderRadius.circular(999),
                        ),
                      ),
                    );
                  }),
                ),
              ],
            ),
          ),
        ),
      );
    }

    return LayoutBuilder(
      builder: (context, constraints) {
        if (hasBox && hasOrder && constraints.maxWidth >= 330) {
          // This row sits inside the Home ListView, so its vertical constraint
          // is intentionally unbounded. Give the premium two-card strip an
          // explicit height before using CrossAxisAlignment.stretch.
          return SizedBox(
            height: 104,
            child: Row(
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                Expanded(child: continueCard()),
                const SizedBox(width: 8),
                Expanded(child: orderCard(activeOrder!)),
              ],
            ),
          );
        }

        return Column(
          children: [
            if (hasBox) continueCard(),
            if (hasBox && hasOrder) const SizedBox(height: 8),
            if (hasOrder) orderCard(activeOrder!),
          ],
        );
      },
    );
  }

