  Widget _premiumFarmStoriesAndFollowFresh({
    required List<FarmPublicProfileRecord> farms,
    required List<Product> products,
  }) {
    final visible = farms.take(6).toList(growable: false);
    final totalFresh =
        _mobileFollowedProductIds.length + _mobileFollowedCategories.length;

    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Row(
          children: [
            const Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    'Farm Stories',
                    style: TextStyle(
                      color: FarmColors.ink,
                      fontSize: 16.5,
                      height: 1,
                      fontWeight: FontWeight.w900,
                      letterSpacing: -.25,
                    ),
                  ),
                  SizedBox(height: 4),
                  Text(
                    'Meet the farmers behind your food',
                    style: TextStyle(
                      color: FarmColors.mutedText,
                      fontSize: 9.2,
                      fontWeight: FontWeight.w700,
                    ),
                  ),
                ],
              ),
            ),
            TextButton(
              onPressed: () => unawaited(
                _openReferenceFarmStories(
                  farms: farms,
                  products: products,
                ),
              ),
              child: const Text('See all'),
            ),
          ],
        ),
        const SizedBox(height: 7),
        SizedBox(
          height: 78,
          child: ListView.separated(
            scrollDirection: Axis.horizontal,
            physics: const BouncingScrollPhysics(),
            itemCount: visible.length + 1,
            separatorBuilder: (_, __) => const SizedBox(width: 8),
            itemBuilder: (context, index) {
              if (index == visible.length) {
                return InkWell(
                  borderRadius: BorderRadius.circular(999),
                  onTap: () => unawaited(
                    _openReferenceFarmStories(
                      farms: farms,
                      products: products,
                    ),
                  ),
                  child: const SizedBox(
                    width: 56,
                    child: Column(
                      children: [
                        CircleAvatar(
                          radius: 23,
                          backgroundColor: Color(0xFFF0F6EC),
                          child: Icon(
                            Icons.add_rounded,
                            color: FarmColors.green,
                          ),
                        ),
                        SizedBox(height: 3),
                        Text(
                          'More',
                          style: TextStyle(
                            color: FarmColors.mutedText,
                            fontSize: 7.4,
                            fontWeight: FontWeight.w800,
                          ),
                        ),
                      ],
                    ),
                  ),
                );
              }

              final farm = visible[index];
              final image = cleanHostedImageUrl(farm.logoImageUrl) ??
                  cleanHostedImageUrl(farm.coverImageUrl);
              final following =
                  _mobileFollowedFarmIds.contains(farm.farmerId.trim());

              return InkWell(
                borderRadius: BorderRadius.circular(999),
                onTap: () => unawaited(
                  _openReferenceFarmStories(
                    farms: farms,
                    products: products,
                  ),
                ),
                child: SizedBox(
                  width: 56,
                  child: Column(
                    children: [
                      Container(
                        width: 48,
                        height: 48,
                        padding: const EdgeInsets.all(2.4),
                        decoration: BoxDecoration(
                          shape: BoxShape.circle,
                          border: Border.all(
                            color: following
                                ? FarmColors.green
                                : const Color(0xFFE4A51A),
                            width: 2,
                          ),
                        ),
                        child: ClipOval(
                          child: image == null
                              ? Container(
                                  color: FarmColors.primarySoft,
                                  child: const Icon(
                                    Icons.eco_outlined,
                                    color: FarmColors.green,
                                  ),
                                )
                              : Image.network(
                                  image,
                                  fit: BoxFit.cover,
                                  errorBuilder: (_, __, ___) => Container(
                                    color: FarmColors.primarySoft,
                                    child: const Icon(
                                      Icons.eco_outlined,
                                      color: FarmColors.green,
                                    ),
                                  ),
                                ),
                        ),
                      ),
                      const SizedBox(height: 3),
                      Text(
                        farm.publicName,
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        textAlign: TextAlign.center,
                        style: const TextStyle(
                          color: FarmColors.ink,
                          fontSize: 7.1,
                          fontWeight: FontWeight.w800,
                        ),
                      ),
                    ],
                  ),
                ),
              );
            },
          ),
        ),
        const SizedBox(height: 5),
        Align(
          alignment: Alignment.centerRight,
          child: Material(
            color: const Color(0xFFF7FAF5),
            borderRadius: BorderRadius.circular(12),
            child: InkWell(
              borderRadius: BorderRadius.circular(12),
              onTap: () => unawaited(
                _showPremiumFollowFreshPanel(products),
              ),
              child: Container(
                width: 156,
                padding: const EdgeInsets.symmetric(
                  horizontal: 10,
                  vertical: 7,
                ),
                decoration: BoxDecoration(
                  borderRadius: BorderRadius.circular(12),
                  border: Border.all(color: const Color(0xFFDCE5D8)),
                ),
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    const Text(
                      'Follow Fresh',
                      maxLines: 1,
                      style: TextStyle(
                        color: FarmColors.ink,
                        fontSize: 9.1,
                        fontWeight: FontWeight.w900,
                      ),
                    ),
                    const SizedBox(height: 1),
                    Text(
                      totalFresh == 0
                          ? 'Fresh alerts & farm updates'
                          : '$totalFresh followed • alerts on',
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: const TextStyle(
                        color: FarmColors.mutedText,
                        fontSize: 6.8,
                        fontWeight: FontWeight.w600,
                      ),
                    ),
                  ],
                ),
              ),
            ),
          ),
        ),
      ],
    );
  }

