  Widget _premiumMiniProductRail({
    required List<Product> products,
    int maxItems = 8,
  }) {
    final rows = products.take(maxItems).toList(growable: false);
    if (rows.isEmpty) return const SizedBox.shrink();

    return SizedBox(
      height: 138,
      child: ListView.separated(
        scrollDirection: Axis.horizontal,
        physics: const BouncingScrollPhysics(),
        padding: const EdgeInsets.only(right: 4),
        itemCount: rows.length,
        separatorBuilder: (_, __) => const SizedBox(width: 9),
        itemBuilder: (context, index) {
          final product = rows[index];

          return SizedBox(
            width: 124,
            child: Material(
              color: Colors.transparent,
              child: InkWell(
                borderRadius: BorderRadius.circular(18),
                onTap: () => unawaited(openProduct(product)),
                child: Container(
                  padding: const EdgeInsets.fromLTRB(6, 6, 6, 5),
                  decoration: BoxDecoration(
                    color: const Color(0xFFFFFEFB),
                    borderRadius: BorderRadius.circular(18),
                    border: Border.all(color: const Color(0xFFE0E6DD)),
                  ),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      SizedBox(
                        height: 101,
                        width: double.infinity,
                        child: ClipRRect(
                          borderRadius: BorderRadius.circular(14),
                          child: Stack(
                            fit: StackFit.expand,
                            children: [
                              Container(
                                color: const Color(0xFFF3F6F0),
                                child: Center(
                                  child: ProductVisual(
                                    product: product,
                                    size: 94,
                                    showOrganicBadge: false,
                                  ),
                                ),
                              ),
                              Positioned(
                                left: 5,
                                bottom: (product.isLowStock ||
                                        product.isOutOfStock)
                                    ? 30
                                    : 5,
                                child: ProductOriginBadge(
                                  product: product,
                                  compact: true,
                                  includeIcon: false,
                                ),
                              ),
                              if (product.isLowStock || product.isOutOfStock)
                                Positioned(
                                  left: 5,
                                  bottom: 5,
                                  child: ProductAvailabilityChip(
                                    product: product,
                                    compact: true,
                                  ),
                                ),
                            ],
                          ),
                        ),
                      ),
                      const SizedBox(height: 5),
                      Text(
                        product.name,
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: const TextStyle(
                          color: FarmColors.ink,
                          fontSize: 9.4,
                          fontWeight: FontWeight.w900,
                        ),
                      ),
                    ],
                  ),
                ),
              ),
            ),
          );
        },
      ),
    );
  }

