        'Magnesium',
        'Iron',
        'Fiber',
        'Potassium',
        'Vitamin C',
        'Protein',
        'Calcium',
        'Antioxidants',
      ];

  String _cleanHomeSearchValue(String value) {
    return value
        .trim()
        .toLowerCase()
        .replaceAll(RegExp(r'[_-]+'), ' ')
        .replaceAll(RegExp(r'[^a-z0-9 ]+'), ' ')
        .replaceAll(RegExp(r'\s+'), ' ')
        .trim();
  }

  bool _homeListHasNutrient(List<String> values, String nutrient) {
    final key = _cleanHomeSearchValue(nutrient);
    if (key.isEmpty) return false;

    return values.any((value) => _cleanHomeSearchValue(value) == key);
  }

  int _homeProductNutrientLevel(Product product, String nutrient) {
    if (_homeListHasNutrient(product.nutrientStrong, nutrient)) return 3;
    if (_homeListHasNutrient(product.nutrientGood, nutrient)) return 2;
    if (_homeListHasNutrient(product.nutrientContains, nutrient)) return 1;
    return 0;
  }

  String? _homeNutrientFromQuery(String value) {
    final clean = _cleanHomeSearchValue(value);
    if (clean.isEmpty) return null;

    for (final nutrient in _homeNutrientOptions) {
      final nutrientKey = _cleanHomeSearchValue(nutrient);
      if (clean == nutrientKey || clean.contains(nutrientKey)) {
        return nutrient;
      }
    }

    if (clean == 'vit c' || clean.contains('vit c')) return 'Vitamin C';
    if (clean == 'antioxidant' || clean.contains('antioxidant')) {
      return 'Antioxidants';
    }

    return null;
  }

  String _homeSearchTextForProduct(Product product) {
    return _cleanHomeSearchValue([
      product.name,
      product.category,
      product.description ?? '',
      product.unit ?? '',
      product.farmName ?? '',
      product.farmerName ?? '',
      ...product.nutrientStrong,
      ...product.nutrientGood,
      ...product.nutrientContains,
    ].join(' '));
  }

  bool _homeProductMatchesSearch(Product product, String query) {
    final cleanQuery = _cleanHomeSearchValue(query);
    if (cleanQuery.isEmpty) return true;

    final nutrient = _homeNutrientFromQuery(query);
    if (nutrient != null && _homeProductNutrientLevel(product, nutrient) > 0) {
      return true;
    }

    return _homeSearchTextForProduct(product).contains(cleanQuery) ||
        hpjSmartProductMatchesSearch(product, query);
  }

  int _homeSearchRankScore(Product product, String query) {
    final cleanQuery = _cleanHomeSearchValue(query);
    final nutrient = _homeNutrientFromQuery(query);
    var score = 0;

    final cleanName = _cleanHomeSearchValue(product.name);
    final cleanCategory = _cleanHomeSearchValue(product.category);
    final cleanFarm = _cleanHomeSearchValue(
      product.farmName ?? product.farmerName ?? '',
    );

    if (cleanName == cleanQuery) score += 5000;
    if (cleanName.startsWith(cleanQuery)) score += 3000;
    if (cleanName.contains(cleanQuery)) score += 1800;
    if (cleanCategory.contains(cleanQuery)) score += 900;
    if (cleanFarm.contains(cleanQuery)) score += 700;

    if (nutrient != null) {
      score += _homeProductNutrientLevel(product, nutrient) * 1200;
      if (product.nutritionVerified) score += 220;
    }

    final smartScore = hpjSmartProductSearchScore(product, query);
    if (smartScore > 0) score += smartScore;

    if (product.canAddToCart) score += 160;
    if (product.hasActiveDiscount) score += 80;
    if (product.isOrganic) score += 30;

    return score;
  }

  List<String> get _homeNutrientFilterOptions => [
        'All',
        ..._homeNutrientOptions,
      ];

  List<String> get _homeAvailabilityOptions => const [
        'Any availability',
        'In stock',
        'Low stock',
        'Fresh this week',
        'Out of stock',
      ];

  List<String> get _homePriceOptions => const [
        'Any price',
        'Under J\$500',
        'J\$500–1,000',
        'J\$1,000–2,500',
        'J\$2,500+',
      ];

  List<String> get _homeSpecialOptions => const [
        'All',
        'Deals',
        'Organic',
        'Local',
      ];

  List<String> get _homeSortOptions => const [
        'Recommended',
        'Newest',
        'Price: Low to High',
        'Price: High to Low',
        'A-Z',
      ];

  bool get _hasActiveHomeFilters {
    return selectedHomeCategory != 'All' ||
        selectedHomeNutrient != 'All' ||
        selectedHomeAvailability != 'Any availability' ||
        selectedHomePrice != 'Any price' ||
        selectedHomeFarm != 'All farms' ||
        selectedHomeSpecial != 'All' ||
        selectedHomeSort != 'Recommended';
  }

  int get _homeActiveFilterCount {
    return <bool>[
      selectedHomeCategory != 'All',
      selectedHomeNutrient != 'All',
      selectedHomeAvailability != 'Any availability',
      selectedHomePrice != 'Any price',
      selectedHomeFarm != 'All farms',
      selectedHomeSpecial != 'All',
      selectedHomeSort != 'Recommended',
    ].where((active) => active).length;
  }

  List<String> _homeCategoryOptions(List<Product> products) {
    final values = <String>{'All'};

    for (final product in products) {
      final category = product.category.trim();
      if (category.isNotEmpty) values.add(category);
    }

    final output = values.toList();
    output.sort((a, b) {
      if (a == 'All') return -1;
      if (b == 'All') return 1;
      return a.toLowerCase().compareTo(b.toLowerCase());
    });

    return output;
  }

  String _homeProductFarm(Product product) {
    return (product.farmName ?? product.farmerName ?? '').trim();
  }

  List<String> _homeFarmOptions(List<Product> products) {
    final values = <String>{'All farms'};

    for (final product in products) {
      final farm = _homeProductFarm(product);
      if (farm.isNotEmpty) values.add(farm);
    }

    final output = values.toList();
    output.sort((a, b) {
      if (a == 'All farms') return -1;
      if (b == 'All farms') return 1;
      return a.toLowerCase().compareTo(b.toLowerCase());
    });

    return output;
  }

  int _homeCategoryCount(
    List<Product> products,
    String category,
  ) {
    if (category == 'All') return products.length;

    final selected = category.trim().toLowerCase();

    return products.where((product) {
      final productCategory = product.category.trim().toLowerCase();
      final productName = product.name.trim().toLowerCase();

      return productCategory == selected ||
          productName.contains(selected);
    }).length;
  }

  int _homeFarmCount(
    List<Product> products,
    String farm,
  ) {
    if (farm == 'All farms') return products.length;

    final selected = farm.trim().toLowerCase();

    return products.where((product) {
      return _homeProductFarm(product).toLowerCase() == selected;
    }).length;
  }

  bool _homeProductMatchesPrice(Product product) {
    final price = product.effectivePrice;

    switch (selectedHomePrice) {
      case 'Under J\$500':
        return price >= 0 && price < 500;

      case 'J\$500–1,000':
        return price >= 500 && price <= 1000;

      case 'J\$1,000–2,500':
        return price > 1000 && price <= 2500;

      case 'J\$2,500+':
        return price > 2500;

      case 'Any price':
      default:
        return true;
    }
  }

  bool _homeProductMatchesFilters(Product product) {
    final category = product.category.trim().toLowerCase();
    final selectedCategory =
        selectedHomeCategory.trim().toLowerCase();

    final matchesCategory =
        selectedHomeCategory == 'All' ||
            category == selectedCategory ||
            product.name
                .trim()
                .toLowerCase()
                .contains(selectedCategory);

    final matchesNutrient =
        selectedHomeNutrient == 'All' ||
            _homeProductNutrientLevel(
                  product,
                  selectedHomeNutrient,
                ) >
                0;

    final availability =
        selectedHomeAvailability.trim().toLowerCase();

    final matchesAvailability =
        availability == 'any availability' ||
            (availability == 'in stock' &&
                product.canAddToCart) ||
            (availability == 'low stock' &&
                product.isLowStock) ||
            (availability == 'fresh this week' &&
                product.canAddToCart &&
                isProductHarvestedThisWeek(product)) ||
            (availability == 'out of stock' &&
                product.isOutOfStock);

    final farm = _homeProductFarm(product);

    final matchesFarm =
        selectedHomeFarm == 'All farms' ||
            farm.toLowerCase() ==
                selectedHomeFarm.trim().toLowerCase();

    final special =
        selectedHomeSpecial.trim().toLowerCase();

    final matchesSpecial =
        special == 'all' ||
            (special == 'deals' &&
                product.hasActiveDiscount) ||
            (special == 'organic' &&
                product.isOrganic) ||
            (special == 'local' &&
                product.isLocal);

    return matchesCategory &&
        matchesNutrient &&
        matchesAvailability &&
        _homeProductMatchesPrice(product) &&
        matchesFarm &&
        matchesSpecial;
  }

  int _homeFilterRankScore(Product product) {
    var score = 0;

    if (selectedHomeNutrient != 'All') {
      score +=
          _homeProductNutrientLevel(
            product,
            selectedHomeNutrient,
          ) *
          1200;

      if (product.nutritionVerified) {
        score += 180;
      }
    }

    if (product.canAddToCart) score += 120;
    if (product.hasActiveDiscount) score += 70;
    if (product.isOrganic) score += 30;
    if (product.isLocal) score += 15;
    if (isProductHarvestedThisWeek(product)) score += 20;
    if (product.isLowStock) score -= 20;
    if (product.isOutOfStock) score -= 500;

    return score;
  }

  List<Product> _homeSearchResults(
    List<Product> products,
  ) {
    final query = homeSearchQuery.trim();
    final hasQuery = query.isNotEmpty;

    if (!hasQuery && !_hasActiveHomeFilters) {
      return const <Product>[];
    }

    final output = products.where((product) {
      final matchesSearch =
          !hasQuery ||
          _homeProductMatchesSearch(
            product,
            query,
          );

      return matchesSearch &&
          _homeProductMatchesFilters(product);
    }).toList();

    switch (selectedHomeSort) {
      case 'Newest':
        output.sort((a, b) {
          if (a.canAddToCart != b.canAddToCart) {
            return a.canAddToCart ? -1 : 1;
          }

          final aDate =
              a.createdAt ??
              DateTime.fromMillisecondsSinceEpoch(0);
          final bDate =
              b.createdAt ??
              DateTime.fromMillisecondsSinceEpoch(0);

          final dateCompare = bDate.compareTo(aDate);
          if (dateCompare != 0) return dateCompare;

          return a.name
              .toLowerCase()
              .compareTo(b.name.toLowerCase());
        });
        break;

      case 'Price: Low to High':
        output.sort((a, b) {
          if (a.canAddToCart != b.canAddToCart) {
            return a.canAddToCart ? -1 : 1;
          }

          final priceCompare =
              a.effectivePrice.compareTo(
            b.effectivePrice,
          );

          if (priceCompare != 0) {
            return priceCompare;
          }

          return a.name
              .toLowerCase()
              .compareTo(b.name.toLowerCase());
        });
        break;

      case 'Price: High to Low':
        output.sort((a, b) {
          if (a.canAddToCart != b.canAddToCart) {
            return a.canAddToCart ? -1 : 1;
          }

          final priceCompare =
              b.effectivePrice.compareTo(
            a.effectivePrice,
          );

          if (priceCompare != 0) {
            return priceCompare;
          }

          return a.name
              .toLowerCase()
              .compareTo(b.name.toLowerCase());
        });
        break;

      case 'A-Z':
        output.sort((a, b) {
          if (a.canAddToCart != b.canAddToCart) {
            return a.canAddToCart ? -1 : 1;
          }

          return a.name
              .toLowerCase()
              .compareTo(b.name.toLowerCase());
        });
        break;

      case 'Recommended':
      default:
        output.sort((a, b) {
          if (hasQuery) {
            final scoreCompare =
                _homeSearchRankScore(
                  b,
                  query,
                ).compareTo(
                  _homeSearchRankScore(
                    a,
                    query,
                  ),
                );

            if (scoreCompare != 0) {
              return scoreCompare;
            }
          }

          final filterCompare =
              _homeFilterRankScore(
                b,
              ).compareTo(
                _homeFilterRankScore(a),
              );

          if (filterCompare != 0) {
            return filterCompare;
          }

          if (a.canAddToCart !=
              b.canAddToCart) {
            return a.canAddToCart ? -1 : 1;
          }

          return a.name
              .toLowerCase()
              .compareTo(b.name.toLowerCase());
        });
        break;
    }

    return output;
  }

  int _homeFilterPreviewCount(
    List<Product> products,
  ) {
    final query = homeSearchQuery.trim();

    return products.where((product) {
      final matchesSearch =
          query.isEmpty ||
          _homeProductMatchesSearch(
            product,
            query,
          );

      return matchesSearch &&
          _homeProductMatchesFilters(product);
    }).length;
  }

  void _clearHomeSearch() {
    if (homeSearchController.text.isEmpty &&
        homeSearchQuery.isEmpty) {
      return;
    }

    homeSearchController.clear();
    setState(() => homeSearchQuery = '');
    homeSearchFocusNode.requestFocus();
  }

  void _resetHomeSearchAndFilters() {
    homeSearchController.clear();

    setState(() {
      homeSearchQuery = '';
      selectedHomeCategory = 'All';
      selectedHomeNutrient = 'All';
      selectedHomeAvailability =
          'Any availability';
      selectedHomePrice = 'Any price';
      selectedHomeFarm = 'All farms';
      selectedHomeSpecial = 'All';
      selectedHomeSort = 'Recommended';
    });

    homeSearchFocusNode.requestFocus();
  }


