    if (selectedHomeSpecial == 'Organic') {
      return 'Organic';
    }

    switch (selectedHomeAvailability) {
      case 'In stock':
        return 'In stock';

      case 'Low stock':
        return 'Low stock';

      case 'Out of stock':
        return 'Out of stock';

      default:
        return 'All items';
    }
  }

  void _applyOriginalAppShowFilter(String filter) {
    setState(() {
      // Reset only the current engine fields represented by the
      // original native-app "Show" row.
      selectedHomeAvailability = 'Any availability';
      selectedHomeSpecial = 'All';

      switch (filter) {
        case 'In stock':
          selectedHomeAvailability = 'In stock';
          break;

        case 'Low stock':
          selectedHomeAvailability = 'Low stock';
          break;

        case 'Out of stock':
          selectedHomeAvailability = 'Out of stock';
          break;

        case 'Deals':
          selectedHomeSpecial = 'Deals';
          break;

        case 'Organic':
          selectedHomeSpecial = 'Organic';
          break;

        case 'All items':
        default:
          break;
      }
    });
  }


