  Widget _premiumDesktopHomeSearchEntry(
    List<Product> products,
  ) {
    final categories = _homeCategoryOptions(products);
    final activeFilterCount =
        _homeActiveFilterCount;

    final categoryLabel = selectedHomeCategory == 'All'
        ? 'All Products'
        : _homeCategoryDisplayName(
            selectedHomeCategory,
          );

    final wideDesktop =
        MediaQuery.sizeOf(context).width >= 1380;

    Future<void> runSearch() async {
      final query = homeSearchController.text.trim();

      if (query.isEmpty) {
        homeSearchFocusNode.requestFocus();
        return;
      }

      homeSearchFocusNode.unfocus();
      await HpjSmartLocalStore.rememberRecentSearch(
        query,
      );
    }

    Widget filterButton() {
      return Stack(
        clipBehavior: Clip.none,
        children: [
          OutlinedButton.icon(
            onPressed: () =>
                _showHomeFilterSheet(products),
            style: OutlinedButton.styleFrom(
              foregroundColor:
                  FarmColors.deepGreen,
              backgroundColor: Colors.white,
              side: BorderSide(
                color: _hasActiveHomeFilters
                    ? FarmColors.green
                    : const Color(0xFFD6DFD5),
                width:
                    _hasActiveHomeFilters ? 1.4 : 1,
              ),
              padding:
                  const EdgeInsets.symmetric(
                horizontal: 15,
                vertical: 14,
              ),
              shape: RoundedRectangleBorder(
                borderRadius:
                    BorderRadius.circular(14),
              ),
              textStyle: const TextStyle(
                fontSize: 10,
                fontWeight: FontWeight.w900,
              ),
            ),
            icon: const Icon(
              Icons.tune_rounded,
              size: 17,
            ),
            label: const Text('Filters'),
          ),
          if (activeFilterCount > 0)
            Positioned(
              right: -5,
              top: -6,
              child: Container(
                constraints:
                    const BoxConstraints(
                  minWidth: 19,
                  minHeight: 19,
                ),
                padding:
                    const EdgeInsets.symmetric(
                  horizontal: 5,
                ),
                alignment: Alignment.center,
                decoration: BoxDecoration(
                  color:
                      const Color(0xFFFFB91F),
                  borderRadius:
                      BorderRadius.circular(999),
                  border: Border.all(
                    color: Colors.white,
                    width: 1.5,
                  ),
                  boxShadow: [
                    BoxShadow(
                      color: Colors.black
                          .withOpacity(.10),
                      blurRadius: 6,
                      offset:
                          const Offset(0, 2),
                    ),
                  ],
                ),
                child: Text(
                  '$activeFilterCount',
                  style: const TextStyle(
                    color:
                        FarmColors.deepGreen,
                    fontSize: 8.2,
                    height: 1,
                    fontWeight:
                        FontWeight.w900,
                  ),
                ),
              ),
            ),
        ],
      );
    }

    return Container(
      height: 72,
      padding: const EdgeInsets.fromLTRB(
        10,
        8,
        10,
        8,
      ),
      decoration: BoxDecoration(
        color: const Color(0xFFFFFEFB),
        borderRadius:
            BorderRadius.circular(20),
        border: Border.all(
          color: const Color(0xFFE6B341)
              .withOpacity(.72),
          width: 1.15,
        ),
        boxShadow: [
          BoxShadow(
            color: const Color(0xFF173D30)
                .withOpacity(.10),
            blurRadius: 24,
            offset: const Offset(0, 9),
          ),
          BoxShadow(
            color: const Color(0xFFFFC62A)
                .withOpacity(.06),
            blurRadius: 12,
            spreadRadius: 1,
          ),
        ],
      ),
      child: Row(
        children: [
          PopupMenuButton<String>(
            tooltip: 'Browse product categories',
            color: Colors.white,
            elevation: 12,
            position:
                PopupMenuPosition.under,
            offset: const Offset(0, 8),
            shape: RoundedRectangleBorder(
              borderRadius:
                  BorderRadius.circular(16),
              side: const BorderSide(
                color: Color(0xFFDDE5DD),
              ),
            ),
            onSelected: (category) {
              setState(() {
                selectedHomeCategory =
                    category;
              });
              homeSearchFocusNode
                  .unfocus();
            },
            itemBuilder: (context) {
              return categories.map(
                (category) {
                  final selected =
                      selectedHomeCategory ==
                          category;
                  final label =
                      category == 'All'
                          ? 'All Products'
                          : _homeCategoryDisplayName(
                              category,
                            );

                  return PopupMenuItem<String>(
                    value: category,
                    height: 42,
                    child: Row(
                      children: [
                        Icon(
                          category == 'All'
                              ? Icons
                                  .eco_outlined
                              : _homeCategoryIcon(
                                  category,
                                ),
                          color: selected
                              ? FarmColors.green
                              : FarmColors
                                  .mutedText,
                          size: 17,
                        ),
                        const SizedBox(
                          width: 9,
                        ),
                        Expanded(
                          child: Text(
                            label,
                            maxLines: 1,
                            overflow:
                                TextOverflow
                                    .ellipsis,
                            style: TextStyle(
                              color: selected
                                  ? FarmColors
                                      .deepGreen
                                  : FarmColors.ink,
                              fontSize: 10.5,
                              fontWeight:
                                  selected
                                      ? FontWeight
                                          .w900
                                      : FontWeight
                                          .w700,
                            ),
                          ),
                        ),
                        if (selected)
                          const Icon(
                            Icons
                                .check_rounded,
                            color:
                                FarmColors
                                    .green,
                            size: 16,
                          ),
                      ],
                    ),
                  );
                },
              ).toList();
            },
            child: Container(
              width: 190,
              height: 52,
              padding:
                  const EdgeInsets.symmetric(
                horizontal: 14,
              ),
              decoration: BoxDecoration(
                color:
                    const Color(0xFFFAFBF8),
                borderRadius:
                    BorderRadius.circular(14),
                border: Border.all(
                  color:
                      const Color(0xFFDCE4DA),
                ),
              ),
              child: Row(
                children: [
                  Container(
                    width: 30,
                    height: 30,
                    alignment:
                        Alignment.center,
                    decoration: BoxDecoration(
                      color:
                          const Color(
                        0xFFEAF3E7,
                      ),
                      borderRadius:
                          BorderRadius.circular(
                        9,
                      ),
                    ),
                    child: const Icon(
                      Icons.eco_rounded,
                      color:
                          FarmColors.green,
                      size: 17,
                    ),
                  ),
                  const SizedBox(width: 9),
                  Expanded(
                    child: Text(
                      categoryLabel,
                      maxLines: 1,
                      overflow:
                          TextOverflow.ellipsis,
                      style: const TextStyle(
                        color:
                            FarmColors.ink,
                        fontSize: 10.5,
                        fontWeight:
                            FontWeight.w900,
                      ),
                    ),
                  ),
                  const Icon(
                    Icons
                        .keyboard_arrow_down_rounded,
                    color:
                        FarmColors.deepGreen,
                    size: 18,
                  ),
                ],
              ),
            ),
          ),

          const SizedBox(width: 12),

          Container(
            width: 1,
            height: 34,
            color:
                const Color(0xFFDDE4DC),
          ),

          const SizedBox(width: 12),

          Expanded(
            child: Container(
              height: 52,
              decoration: BoxDecoration(
                color: Colors.white,
                borderRadius:
                    BorderRadius.circular(14),
              ),
              child: Row(
                children: [
                  const SizedBox(width: 15),
                  const Icon(
                    Icons.search_rounded,
                    color:
                        FarmColors.deepGreen,
                    size: 21,
                  ),
                  const SizedBox(width: 10),
                  Expanded(
                    child: TextField(
                      controller:
                          homeSearchController,
                      focusNode:
                          homeSearchFocusNode,
                      textInputAction:
                          TextInputAction.search,
                      cursorColor:
                          FarmColors.green,
                      style:
                          const TextStyle(
                        color: FarmColors.ink,
                        fontSize: 12.4,
                        fontWeight:
                            FontWeight.w700,
                        letterSpacing:
                            -.05,
                      ),
                      decoration:
                          const InputDecoration(
                        isDense: true,
                        border:
                            InputBorder.none,
                        enabledBorder:
                            InputBorder.none,
                        focusedBorder:
                            InputBorder.none,
                        disabledBorder:
                            InputBorder.none,
                        errorBorder:
                            InputBorder.none,
                        focusedErrorBorder:
                            InputBorder.none,
                        contentPadding:
                            EdgeInsets.zero,
                        hintText:
                            'Search produce, farms or nutrients...',
                        hintStyle:
                            TextStyle(
                          color:
                              Color(
                            0xFF7D8780,
                          ),
                          fontSize: 11.8,
                          fontWeight:
                              FontWeight.w600,
                        ),
                      ),
                      onChanged: (value) {
                        setState(() {
                          homeSearchQuery =
                              value;
                        });
                      },
                      onSubmitted: (_) =>
                          runSearch(),
                    ),
                  ),
                  if (homeSearchQuery
                      .trim()
                      .isNotEmpty)
                    IconButton(
                      tooltip:
                          'Clear search',
                      visualDensity:
                          VisualDensity
                              .compact,
                      onPressed:
                          _clearHomeSearch,
                      icon: const Icon(
                        Icons
                            .close_rounded,
                        color:
                            FarmColors
                                .mutedText,
                        size: 17,
                      ),
                    ),
                  const SizedBox(width: 3),
                ],
              ),
            ),
          ),

          const SizedBox(width: 8),

          SizedBox(
            height: 52,
            child: FilledButton.icon(
              onPressed: runSearch,
              style: FilledButton.styleFrom(
                backgroundColor:
                    FarmColors.deepGreen,
                foregroundColor:
                    Colors.white,
                padding:
                    const EdgeInsets
                        .symmetric(
                  horizontal: 20,
                ),
                shape:
                    RoundedRectangleBorder(
                  borderRadius:
                      BorderRadius.circular(
                    14,
                  ),
                ),
                textStyle:
