  Widget _eliteHomeSearchEntry(List<Product> products) {
    final activeFilterCount =
        _homeActiveFilterCount;

    return Material(
      color: Colors.transparent,
      child: Container(
        height: 60,
        padding: const EdgeInsets.fromLTRB(9, 7, 7, 7),
        decoration: BoxDecoration(
          color: const Color(0xFFFFFEFB).withOpacity(0.98),
          borderRadius: BorderRadius.circular(22),
          border: Border.all(
            color: homeSearchFocusNode.hasFocus ||
                    homeSearchQuery.isNotEmpty ||
                    _hasActiveHomeFilters
                ? FarmColors.green.withOpacity(0.30)
                : const Color(0xFFE5E0D7),
            width: homeSearchFocusNode.hasFocus ? 1.4 : 1,
          ),
          boxShadow: [
            BoxShadow(
              color: const Color(0xFF14382D).withOpacity(0.11),
              blurRadius: 24,
              offset: const Offset(0, 10),
            ),
          ],
        ),
        child: Row(
          children: [
            Container(
              width: 42,
              height: 42,
              decoration: BoxDecoration(
                gradient: const LinearGradient(
                  begin: Alignment.topLeft,
                  end: Alignment.bottomRight,
                  colors: [
                    Color(0xFFE9F3E7),
                    Color(0xFFF4F7EF),
                  ],
                ),
                borderRadius: BorderRadius.circular(15),
                border: Border.all(
                  color: FarmColors.green.withOpacity(0.09),
                ),
              ),
              child: const Icon(
                Icons.search_rounded,
