// ============================================================================
// HPJ PHASE 99–110 — SOCIAL GROWTH + TRUST + STORY-TO-SALE
// ============================================================================
//
// Phase 102: followed farms/products/categories create useful Fresh Alerts.
// Phase 103: Farm Stories can link a real HPJ product and convert directly.
// Phase 104: Follow Fresh is unified with the existing private Watch/Updates
//            notification system instead of creating a duplicate alert system.
// ============================================================================

String hpjFreshFollowKey(String value) => value
    .trim()
    .toLowerCase()
    .replaceAll(RegExp(r'\s+'), ' ');

class HpjFarmStoryRecord {
  final String id;
  final String farmerProfileId;
  final String farmerUserId;
  final String farmName;
  final String parish;
  final String stage;
  final String caption;
  final String imageUrl;
  final String productId;
  final String productName;
  final DateTime createdAt;
  final DateTime expiresAt;

  const HpjFarmStoryRecord({
    required this.id,
    required this.farmerProfileId,
    required this.farmerUserId,
    required this.farmName,
    required this.parish,
    required this.stage,
    required this.caption,
    required this.imageUrl,
    required this.productId,
    required this.productName,
    required this.createdAt,
    required this.expiresAt,
  });

  factory HpjFarmStoryRecord.fromSupabase(Map<String, dynamic> row) {
    DateTime date(dynamic value, DateTime fallback) =>
        DateTime.tryParse(value?.toString() ?? '')?.toLocal() ?? fallback;
    final now = DateTime.now();
    return HpjFarmStoryRecord(
      id: (row['id'] ?? '').toString(),
      farmerProfileId: (row['farmer_profile_id'] ?? '').toString(),
      farmerUserId: (row['farmer_user_id'] ?? '').toString(),
      farmName: (row['farm_name'] ?? 'Jamaican Farm').toString().trim(),
      parish: (row['parish'] ?? '').toString().trim(),
      stage: (row['stage'] ?? 'update').toString().trim().toLowerCase(),
      caption: (row['caption'] ?? '').toString().trim(),
      imageUrl: (row['image_url'] ?? '').toString().trim(),
      productId: (row['product_id'] ?? '').toString().trim(),
      productName: (row['product_name'] ?? '').toString().trim(),
      createdAt: date(row['created_at'], now),
      expiresAt: date(row['expires_at'], now.add(const Duration(hours: 24))),
    );
  }

  String get stageLabel {
    switch (stage) {
      case 'planting': return 'Planting';
      case 'growing': return 'Growing';
      case 'almost_ready': return 'Almost ready';
      case 'harvesting': return 'Harvesting';
      case 'available_now': return 'Available now';
      default: return 'Farm update';
    }
  }
 }

// ============================================================================
// HPJ PHASE 110 — STORY → SALE ATTRIBUTION
// ============================================================================
// A Story interaction is measured without exposing a customer's identity to
// the Farmer. Signed-in product interactions create a short-lived attribution
// token so a later checkout can be tied to the Story that helped generate it.
// ============================================================================

final String _hpjFarmStorySessionKey =
    '${DateTime.now().microsecondsSinceEpoch}-${Object().hashCode}';

Future<void> recordHpjFarmStoryEvent({
  required HpjFarmStoryRecord story,
  required String eventType,
  Product? product,
}) async {
  final storyId = story.id.trim();
  final event = eventType.trim().toLowerCase();
  if (storyId.isEmpty || event.isEmpty) return;

  try {
    await supabase.rpc(
      'hpj_record_farm_story_event',
      params: <String, dynamic>{
        'p_story_id': storyId,
        'p_event_type': event,
        'p_session_key': _hpjFarmStorySessionKey,
        'p_product_id': product?.id.trim().isEmpty == false
            ? product!.id.trim()
            : null,
      },
    );
  } catch (error) {
    // Analytics must never interrupt Story viewing, shopping or checkout.
    farmDebugLog('Farm Story event skipped safely: $error');
  }
}

Future<void> finalizeHpjFarmStorySalesAttribution(String orderId) async {
  final cleanOrderId = orderId.trim();
  if (cleanOrderId.isEmpty || supabase.auth.currentUser == null) return;

  try {
    await supabase.rpc(
      'hpj_finalize_story_order_attribution',
      params: <String, dynamic>{
        'p_order_id': cleanOrderId,
      },
    );
  } catch (error) {
    // A successful HPJ checkout must never fail because analytics did not save.
    farmDebugLog('Story-to-sale attribution skipped safely: $error');
  }
}

Future<List<HpjFarmStoryRecord>> fetchHpjActiveFarmStories({int limit = 60}) async {
  try {
    final response = await supabase
        .from('hpj_farm_stories')
        .select()
        .eq('is_active', true)
        .gt('expires_at', DateTime.now().toUtc().toIso8601String())
        .order('created_at', ascending: false)
        .limit(limit.clamp(1, 100));
    return (response as List)
        .map((row) => HpjFarmStoryRecord.fromSupabase(
              Map<String, dynamic>.from(row as Map),
            ))
        .where((story) => story.id.isNotEmpty)
        .toList(growable: false);
  } catch (error) {
    farmDebugLog('Farm Stories unavailable: $error');
    return const <HpjFarmStoryRecord>[];
  }
}

Future<Set<String>> fetchHpjFollowedProductIds() async {
  final user = supabase.auth.currentUser;
  if (user == null) return <String>{};
  try {
    final response = await supabase
        .from('hpj_product_follows')
        .select('product_id')
        .eq('user_id', user.id);
    return (response as List)
        .map((row) => (row as Map)['product_id']?.toString().trim() ?? '')
        .where((id) => id.isNotEmpty)
        .toSet();
  } catch (error) {
    farmDebugLog('Product follows unavailable: $error');
    return <String>{};
  }
}

Future<Set<String>> fetchHpjFollowedCategoryKeys() async {
  final user = supabase.auth.currentUser;
  if (user == null) return <String>{};
  try {
    final response = await supabase
        .from('hpj_category_follows')
        .select('category')
        .eq('user_id', user.id);
    return (response as List)
        .map((row) => hpjFreshFollowKey((row as Map)['category']?.toString() ?? ''))
        .where((value) => value.isNotEmpty)
        .toSet();
  } catch (error) {
    farmDebugLog('Category follows unavailable: $error');
    return <String>{};
  }
}

Future<void> setHpjProductFollow({
  required Product product,
  required bool follow,
}) async {
  final user = supabase.auth.currentUser;
  if (user == null) throw Exception('Sign in first.');
  final productId = product.id.trim();
  if (productId.isEmpty) throw Exception('Product could not be identified.');
  if (follow) {
    await supabase.from('hpj_product_follows').upsert({
      'user_id': user.id,
      'product_id': productId,
      'product_name': product.name.trim(),
    }, onConflict: 'user_id,product_id');
  } else {
    await supabase
        .from('hpj_product_follows')
        .delete()
        .eq('user_id', user.id)
        .eq('product_id', productId);
  }
}

Future<void> setHpjCategoryFollow({
  required String category,
  required bool follow,
}) async {
  final user = supabase.auth.currentUser;
  if (user == null) throw Exception('Sign in first.');
  final key = hpjFreshFollowKey(category);
  if (key.isEmpty) return;
  if (follow) {
    await supabase.from('hpj_category_follows').upsert({
      'user_id': user.id,
      'category': key,
    }, onConflict: 'user_id,category');
  } else {
    await supabase
        .from('hpj_category_follows')
        .delete()
        .eq('user_id', user.id)
        .eq('category', key);
  }
}

class _HpjFollowFreshCard extends StatelessWidget {
  final List<Product> products;
  final Set<String> followedProductIds;
  final Set<String> followedCategories;
  final Future<void> Function(Product product) onToggleProduct;
  final Future<void> Function(String category) onToggleCategory;

  const _HpjFollowFreshCard({
    required this.products,
    required this.followedProductIds,
    required this.followedCategories,
    required this.onToggleProduct,
    required this.onToggleCategory,
  });

  List<String> get _categories {
    final values = products
        .map((p) => p.category.trim())
        .where((value) => value.isNotEmpty)
        .toSet()
        .toList()..sort();
    return values;
  }

  List<Product> get _followedProducts => products
      .where((p) => followedProductIds.contains(p.id.trim()))
      .take(6)
      .toList(growable: false);

  Future<void> _manage(BuildContext context) async {
    if (!isLoggedIn || supabase.auth.currentUser == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Sign in to follow fresh produce.')),
      );
      return;
    }
    final localProducts = Set<String>.from(followedProductIds);
    final localCategories = Set<String>.from(followedCategories);
    final candidates = products
        .where((p) => p.id.trim().isNotEmpty && !p.isOutOfStock)
        .take(30)
        .toList(growable: false);

    await showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      useSafeArea: true,
      backgroundColor: Colors.transparent,
      builder: (sheetContext) => StatefulBuilder(
        builder: (context, setSheetState) {
          return Container(
            constraints: BoxConstraints(
              maxHeight: MediaQuery.sizeOf(context).height * .86,
            ),
            decoration: const BoxDecoration(
              color: Color(0xFFFCFDF9),
              borderRadius: BorderRadius.vertical(top: Radius.circular(26)),
            ),
            child: ListView(
              padding: const EdgeInsets.fromLTRB(18, 14, 18, 28),
              children: [
                Center(
                  child: Container(
                    width: 44,
                    height: 5,
                    decoration: BoxDecoration(
                      color: FarmColors.line,
                      borderRadius: BorderRadius.circular(999),
                    ),
                  ),
                ),
                const SizedBox(height: 14),
                const Text(
                  'Follow Fresh',
                  style: TextStyle(
                    color: FarmColors.deepGreen,
                    fontSize: 21,
                    fontWeight: FontWeight.w900,
                  ),
                ),
                const SizedBox(height: 4),
                const Text(
                  'Choose produce and categories you care about. HPJ will prioritize them and send useful harvest, availability and price-drop alerts.',
                  style: TextStyle(
                    color: FarmColors.mutedText,
                    fontSize: 10.5,
                    height: 1.35,
                    fontWeight: FontWeight.w600,
                  ),
                ),
                const SizedBox(height: 16),
                const Text('Categories', style: TextStyle(fontWeight: FontWeight.w900)),
                const SizedBox(height: 8),
                Wrap(
                  spacing: 7,
                  runSpacing: 7,
                  children: _categories.map((category) {
                    final key = hpjFreshFollowKey(category);
                    final selected = localCategories.contains(key);
                    return FilterChip(
                      label: Text(category),
                      selected: selected,
                      onSelected: (_) async {
                        setSheetState(() {
                          if (selected) {
                            localCategories.remove(key);
                          } else {
                            localCategories.add(key);
                          }
                        });
                        await onToggleCategory(category);
                      },
                    );
                  }).toList(),
                ),
                const SizedBox(height: 18),
                const Text('Produce', style: TextStyle(fontWeight: FontWeight.w900)),
                const SizedBox(height: 8),
                ...candidates.map((product) {
                  final selected = localProducts.contains(product.id.trim());
                  return SwitchListTile.adaptive(
                    value: selected,
                    contentPadding: EdgeInsets.zero,
                    title: Text(
                      product.name,
                      style: const TextStyle(fontWeight: FontWeight.w800),
                    ),
                    subtitle: Text(product.category),
                    onChanged: (_) async {
                      setSheetState(() {
                        if (selected) {
                          localProducts.remove(product.id.trim());
                        } else {
                          localProducts.add(product.id.trim());
                        }
                      });
                      await onToggleProduct(product);
                    },
                  );
                }),
              ],
            ),
          );
        },
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final followed = _followedProducts;
    final categoryLabels = _categories
        .where((category) => followedCategories.contains(hpjFreshFollowKey(category)))
        .take(5)
        .toList(growable: false);
    final total = followedProductIds.length + followedCategories.length;

    return Container(
      width: double.infinity,
      padding: const EdgeInsets.fromLTRB(14, 12, 14, 12),
      decoration: BoxDecoration(
        color: const Color(0xFFF7FAF4),
        borderRadius: BorderRadius.circular(16),
        border: Border.all(color: const Color(0xFFDCE7D8)),
      ),
      child: Row(
        children: [
          Container(
            width: 38,
            height: 38,
            decoration: BoxDecoration(
              color: FarmColors.primarySoft,
              borderRadius: BorderRadius.circular(12),
            ),
            child: const Icon(Icons.notifications_active_outlined,
                color: FarmColors.deepGreen, size: 19),
          ),
          const SizedBox(width: 10),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                const Text(
                  'Follow Fresh',
                  style: TextStyle(
                    color: FarmColors.deepGreen,
                    fontSize: 13.5,
                    fontWeight: FontWeight.w900,
                  ),
                ),
                const SizedBox(height: 2),
                Text(
                  total == 0
                      ? 'Follow produce or categories for smarter Fresh Picks and useful Fresh Alerts.'
                      : '$total followed • Fresh Picks + private availability, price and harvest alerts are active.',
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: const TextStyle(
                    color: FarmColors.mutedText,
                    fontSize: 8.8,
                    fontWeight: FontWeight.w600,
                  ),
                ),
                if (followed.isNotEmpty || categoryLabels.isNotEmpty) ...[
                  const SizedBox(height: 7),
                  Wrap(
                    spacing: 5,
                    runSpacing: 5,
                    children: [
                      ...categoryLabels.map((c) => _SmallShopChip(
                            label: c,
                            color: FarmColors.deepGreen,
                            backgroundColor: FarmColors.primarySoft,
                          )),
                      ...followed.take(3).map((p) => _SmallShopChip(
                            label: p.name,
                            color: FarmColors.deepGreen,
                            backgroundColor: const Color(0xFFFFF3CE),
                          )),
                    ],
                  ),
                ],
              ],
            ),
          ),
          const SizedBox(width: 10),
          OutlinedButton.icon(
            onPressed: () => _manage(context),
            icon: const Icon(Icons.tune_rounded, size: 15),
            label: Text(total == 0 ? 'Choose' : 'Manage'),
          ),
        ],
      ),
    );
  }
}

class _HpjFarmStoriesStrip extends StatelessWidget {
  final List<FarmPublicProfileRecord> farms;
  final List<Product> products;
  final Set<String> followedFarmIds;
  final Future<void> Function(FarmPublicProfileRecord farm) onFarm;
  final void Function(Product product) onProduct;
  final void Function(Product product) onAddProduct;
  final VoidCallback onViewAll;

  const _HpjFarmStoriesStrip({
    required this.farms,
    required this.products,
    required this.followedFarmIds,
    required this.onFarm,
    required this.onProduct,
    required this.onAddProduct,
    required this.onViewAll,
  });

  FarmPublicProfileRecord? _farmFor(HpjFarmStoryRecord story) {
    for (final farm in farms) {
      if (story.farmerProfileId.isNotEmpty &&
          farm.farmerId.trim() == story.farmerProfileId) return farm;
    }
    final key = story.farmName.trim().toLowerCase();
    if (key.isNotEmpty) {
      for (final farm in farms) {
        if (farm.publicName.trim().toLowerCase() == key) return farm;
      }
    }
    return null;
  }

  Product? _productFor(HpjFarmStoryRecord story) {
    final productId = story.productId.trim();
    if (productId.isNotEmpty) {
      for (final product in products) {
        if (product.id.trim() == productId) return product;
      }
    }

    final key = story.productName.trim().toLowerCase();
    if (key.isEmpty) return null;
    for (final product in products) {
      if (product.name.trim().toLowerCase() == key) return product;
    }
    return null;
  }

  String _age(DateTime date) {
    final diff = DateTime.now().difference(date);
    if (diff.inMinutes < 60) return '${diff.inMinutes.clamp(1, 59)}m';
    return '${diff.inHours.clamp(1, 23)}h';
  }

  Future<void> _openStories(
    BuildContext context,
    List<HpjFarmStoryRecord> stories,
  ) async {
    if (stories.isEmpty) return;
    var index = 0;

    unawaited(
      recordHpjFarmStoryEvent(
        story: stories.first,
        eventType: 'view',
      ),
    );

    await showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      useSafeArea: true,
      backgroundColor: Colors.transparent,
      builder: (sheetContext) => StatefulBuilder(
        builder: (context, setSheetState) {
          final story = stories[index];
          final farm = _farmFor(story);
          final product = _productFor(story);
