class _HpjFarmStudyScreenState extends State<HpjFarmStudyScreen> {
  String filter = 'All';

  static const items = <_HpjFarmStudyItem>[
    _HpjFarmStudyItem(
      category: 'Soil & Land',
      title: 'Soil Health for Better Yields',
      subtitle: 'Healthy soil grows stronger communities.',
      readTime: '5 min read',
      imageUrl:
