  }
}

class _HpjFeaturedFarmSocialCard extends StatelessWidget {
  final List<FarmPublicProfileRecord> farms;
  final List<Product> products;
  final String feedMode;
  final Set<String> followedFarmIds;
  final void Function(String farmerId, bool isFollowing)
      onFollowChanged;
  final VoidCallback onOpenReels;
  final Future<void> Function(FarmPublicProfileRecord farm) onOpenFarm;
  final VoidCallback onDiscoverFarms;
  final void Function(Product product) onAddProduct;

  const _HpjFeaturedFarmSocialCard({
    required this.farms,
    required this.products,
    required this.feedMode,
    required this.followedFarmIds,
    required this.onFollowChanged,
    required this.onOpenReels,
    required this.onOpenFarm,
    required this.onDiscoverFarms,
    required this.onAddProduct,
  });

  FarmPublicProfileRecord? _pickFarm() {
    if (farms.isEmpty) return null;

    switch (feedMode) {
      case 'Near You':
        return farms.length > 2 ? farms[2] : farms.first;
      case 'Trending':
        return farms.length > 3 ? farms[3] : farms.first;
      case 'Following':
      case 'For You':
      default:
        return farms.first;
    }
  }

  @override
  Widget build(BuildContext context) {
    final farm = _pickFarm();

    if (feedMode == 'Following' && farm == null) {
      return Container(
        height: 254,
        padding: const EdgeInsets.all(24),
        decoration: BoxDecoration(
          color: Colors.white,
          borderRadius: BorderRadius.circular(16),
          border: Border.all(color: HpjWebUi.border),
        ),
        child: Row(
          children: [
            Container(
              width: 72,
              height: 72,
              alignment: Alignment.center,
              decoration: BoxDecoration(
                color: FarmColors.primarySoft,
                borderRadius: BorderRadius.circular(22),
              ),
              child: const Icon(
                Icons.notifications_none_rounded,
                color: FarmColors.primary,
                size: 34,
              ),
            ),
            const SizedBox(width: 18),
            const Expanded(
              child: Column(
                mainAxisAlignment: MainAxisAlignment.center,
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    'Build your Following feed',
                    style: TextStyle(
                      color: FarmColors.deepGreen,
                      fontSize: 22,
                      fontWeight: FontWeight.w900,
                    ),
                  ),
                  SizedBox(height: 7),
                  Text(
                    'Follow Jamaican farms to see their harvests, Fresh Reels and marketplace updates here.',
                    style: TextStyle(
                      color: FarmColors.mutedText,
                      fontSize: 11,
                      height: 1.35,
                      fontWeight: FontWeight.w600,
                    ),
                  ),
                ],
              ),
            ),
            const SizedBox(width: 18),
            FilledButton.icon(
              onPressed: onDiscoverFarms,
              icon: const Icon(Icons.travel_explore_rounded),
              label: const Text('Discover Farms'),
            ),
          ],
        ),
      );
    }

    final farmProducts = farm == null
        ? products.take(2).toList()
        : products
            .where(
              (product) =>
                  product.farmerId?.trim() ==
                  farm.farmerId.trim(),
            )
            .take(2)
            .toList();

    final fallbackProduct =
        farmProducts.isNotEmpty ? farmProducts.first : null;

    final cover = cleanHostedImageUrl(farm?.coverImageUrl);
    final farmName = farm?.publicName.trim().isNotEmpty == true
        ? farm!.publicName.trim()
        : (fallbackProduct?.farmName ??
                fallbackProduct?.farmerName ??
                'HPJ Jamaican Farm')
            .trim();

    final location = farm?.locationLine ?? 'Jamaica';

    return Container(
      height: 254,
      clipBehavior: Clip.antiAlias,
      decoration: BoxDecoration(
        color: FarmColors.deepGreen,
        borderRadius: BorderRadius.circular(16),
        border: Border.all(color: HpjWebUi.border),
      ),
      child: Stack(
        fit: StackFit.expand,
        children: [
          if (cover != null)
            Image.network(
              cover,
              fit: BoxFit.cover,
              errorBuilder: (_, __, ___) =>
                  const ColoredBox(
                color: FarmColors.deepGreen,
              ),
            )
          else if (fallbackProduct != null)
            Container(
              color: const Color(0xFFEAF2E7),
              alignment: Alignment.center,
              child: ProductVisual(
                product: fallbackProduct,
                size: 360,
                showOrganicBadge: false,
              ),
            )
          else
            const DecoratedBox(
              decoration: BoxDecoration(
                gradient: LinearGradient(
                  begin: Alignment.topLeft,
                  end: Alignment.bottomRight,
                  colors: [
                    Color(0xFF0A422E),
                    Color(0xFF2D7747),
                  ],
                ),
              ),
            ),
          DecoratedBox(
            decoration: BoxDecoration(
              gradient: LinearGradient(
                begin: Alignment.centerLeft,
                end: Alignment.centerRight,
                colors: [
                  const Color(0xFF061E16).withOpacity(0.88),
                  const Color(0xFF0B3828).withOpacity(0.60),
                  Colors.transparent,
                  const Color(0xFF061E16).withOpacity(0.22),
                ],
                stops: const [0.0, 0.42, 0.70, 1.0],
              ),
            ),
          ),
          Positioned(
            left: 18,
            top: 14,
            right: 18,
            child: Row(
              children: [
                CircleAvatar(
                  radius: 18,
                  backgroundColor: Colors.white,
                  backgroundImage:
                      cleanHostedImageUrl(farm?.logoImageUrl) == null
                          ? null
                          : NetworkImage(
                              cleanHostedImageUrl(
                                farm?.logoImageUrl,
                              )!,
                            ),
                  child:
                      cleanHostedImageUrl(farm?.logoImageUrl) == null
                          ? const Icon(
                              Icons.eco_outlined,
                              color: FarmColors.primary,
                            )
                          : null,
                ),
                const SizedBox(width: 9),
                Expanded(
                  child: Column(
                    crossAxisAlignment:
                        CrossAxisAlignment.start,
                    children: [
                      Row(
                        children: [
                          Flexible(
                            child: Text(
                              farmName,
                              maxLines: 1,
                              overflow: TextOverflow.ellipsis,
                              style: const TextStyle(
                                color: Colors.white,
                                fontSize: 12.5,
                                fontWeight: FontWeight.w900,
                              ),
                            ),
                          ),
                          if (farm?.hpjVerified == true) ...[
                            const SizedBox(width: 5),
                            const Icon(
                              Icons.verified_rounded,
                              color: Color(0xFFF1C44D),
                              size: 15,
                            ),
                          ],
                        ],
                      ),
                      const SizedBox(height: 2),
                      Text(
                        location,
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: TextStyle(
                          color: Colors.white.withOpacity(0.84),
                          fontSize: 8.8,
                          fontWeight: FontWeight.w600,
                        ),
                      ),
                    ],
                  ),
                ),
                if (farm != null) ...[
                  FarmFollowButton(
                    farmerId: farm.farmerId,
                    compact: true,
                    onDark: true,
                    onChanged: (value) {
                      onFollowChanged(
                        farm.farmerId,
                        value,
                      );
                    },
                  ),
                  const SizedBox(width: 7),
                  OutlinedButton(
                    onPressed: () => onOpenFarm(farm),
                    style: OutlinedButton.styleFrom(
                      foregroundColor: Colors.white,
                      side: BorderSide(
                        color: Colors.white.withOpacity(0.65),
                      ),
                      padding: const EdgeInsets.symmetric(
                        horizontal: 16,
                        vertical: 9,
                      ),
                      shape: RoundedRectangleBorder(
                        borderRadius: BorderRadius.circular(999),
                      ),
                    ),
                    child: const Text('View Farm'),
                  ),
                ],
              ],
            ),
          ),
          Positioned(
            left: 20,
            bottom: 25,
            child: ConstrainedBox(
              constraints: const BoxConstraints(maxWidth: 285),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  const Text(
                    'Farm Fresh',
                    style: TextStyle(
                      color: Colors.white,
                      fontSize: 26,
                      height: 0.95,
                      fontWeight: FontWeight.w900,
                      letterSpacing: -0.5,
                    ),
                  ),
                  const Text(
                    'Straight from Jamaica.',
                    style: TextStyle(
                      color: Color(0xFFF1C44D),
                      fontSize: 24,
                      height: 1,
                      fontWeight: FontWeight.w900,
                      letterSpacing: -0.5,
                    ),
                  ),
                  const SizedBox(height: 9),
                  Text(
                    farm?.publicBio.trim().isNotEmpty == true
                        ? farm!.publicBio.trim()
                        : 'Real farms, fresh produce and stories from the people growing Jamaica.',
                    maxLines: 2,
                    overflow: TextOverflow.ellipsis,
                    style: TextStyle(
                      color: Colors.white.withOpacity(0.90),
                      fontSize: 10,
                      height: 1.25,
                      fontWeight: FontWeight.w600,
                    ),
                  ),
                ],
              ),
            ),
          ),
          Center(
            child: Material(
              color: Colors.black.withOpacity(0.28),
              shape: const CircleBorder(),
              child: InkWell(
                customBorder: const CircleBorder(),
                onTap: onOpenReels,
                child: Container(
                  width: 62,
                  height: 62,
                  alignment: Alignment.center,
                  decoration: BoxDecoration(
                    shape: BoxShape.circle,
                    border: Border.all(
                      color: Colors.white.withOpacity(0.92),
                      width: 2,
                    ),
                  ),
                  child: const Icon(
                    Icons.play_arrow_rounded,
                    color: Colors.white,
                    size: 34,
                  ),
                ),
              ),
            ),
          ),
          if (farmProducts.isNotEmpty)
            Positioned(
              right: 18,
              top: 72,
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.end,
                children: farmProducts
                    .map(
                      (product) => Padding(
                        padding: const EdgeInsets.only(bottom: 8),
                        child: _HpjShoppableFarmTag(
                          product: product,
                          onAdd: () => onAddProduct(product),
                        ),
                      ),
                    )
                    .toList(),
              ),
            ),
          Positioned(
            left: 18,
            right: 18,
            bottom: 8,
            child: Row(
              children: [
                const Icon(
                  Icons.eco_outlined,
                  color: Color(0xFFF1C44D),
                  size: 16,
                ),
                const SizedBox(width: 7),
                Text(
                  'Fresh. Local. Impactful.',
                  style: TextStyle(
                    color: Colors.white.withOpacity(0.92),
                    fontSize: 8.8,
                    fontWeight: FontWeight.w800,
                  ),
                ),
                const Spacer(),
                TextButton.icon(
                  onPressed: onOpenReels,
                  style: TextButton.styleFrom(
                    foregroundColor: Colors.white,
                  ),
                  icon: const Icon(
                    Icons.play_circle_outline_rounded,
                    size: 16,
                  ),
                  label: const Text('Fresh Reels'),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }
}

class _HpjShoppableFarmTag extends StatelessWidget {
  final Product product;
  final VoidCallback onAdd;

  const _HpjShoppableFarmTag({
    required this.product,
    required this.onAdd,
  });

  @override
  Widget build(BuildContext context) {
    final unit = (product.unit ?? '').trim();

    return Container(
      constraints: const BoxConstraints(maxWidth: 185),
      padding: const EdgeInsets.fromLTRB(9, 7, 7, 7),
      decoration: BoxDecoration(
        color: const Color(0xFF0B3527).withOpacity(0.88),
        borderRadius: BorderRadius.circular(12),
        border: Border.all(
          color: Colors.white.withOpacity(0.22),
        ),
      ),
      child: Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  product.name,
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: const TextStyle(
                    color: Colors.white,
                    fontSize: 9,
                    fontWeight: FontWeight.w900,
                  ),
                ),
                const SizedBox(height: 1),
                Text(
                  'J\$${product.effectivePrice.toStringAsFixed(0)}${unit.isEmpty ? '' : '/$unit'}',
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: const TextStyle(
                    color: Color(0xFFF2E7B8),
                    fontSize: 8,
                    fontWeight: FontWeight.w700,
                  ),
                ),
              ],
            ),
          ),
          const SizedBox(width: 8),
          IconButton(
            onPressed: product.canAddToCart ? onAdd : null,
            padding: EdgeInsets.zero,
            constraints: const BoxConstraints(
              minWidth: 30,
              minHeight: 30,
            ),
            style: IconButton.styleFrom(
              backgroundColor: const Color(0xFFF1C44D),
              foregroundColor: FarmColors.deepGreen,
            ),
            icon: const Icon(
              Icons.shopping_bag_outlined,
              size: 15,
            ),
          ),
        ],
      ),
    );
  }
}


class _HpjFreshPicksSocialRow extends StatelessWidget {
  final List<Product> products;
  final String selectedFilter;
  final ValueChanged<String> onFilterSelected;
  final VoidCallback onShop;
  final void Function(Product product) onOpenProduct;
  final void Function(Product product) onAddProduct;
  final bool Function(Product product) isFavorite;
  final void Function(Product product) onToggleFavorite;

  const _HpjFreshPicksSocialRow({
    required this.products,
    required this.selectedFilter,
    required this.onFilterSelected,
    required this.onShop,
    required this.onOpenProduct,
    required this.onAddProduct,
    required this.isFavorite,
    required this.onToggleFavorite,
  });

  @override
  Widget build(BuildContext context) {
    const filters = <String>[
      'All',
      'Deals',
      'Organic',
      'Fresh This Week',
    ];

    return Container(
      padding: const EdgeInsets.fromLTRB(12, 10, 12, 12),
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(15),
        border: Border.all(color: HpjWebUi.border),
      ),
      child: Column(
        children: [
          Row(
            crossAxisAlignment: CrossAxisAlignment.end,
            children: [
              const Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      'Fresh Picks from the Marketplace',
                      style: TextStyle(
                        color: FarmColors.deepGreen,
                        fontSize: 14.2,
                        height: 1,
                        fontWeight: FontWeight.w900,
                        letterSpacing: -0.2,
                      ),
                    ),
                    SizedBox(height: 4),
                    Text(
                      'Real products. Real farms. Real Jamaica.',
                      style: TextStyle(
                        color: FarmColors.mutedText,
                        fontSize: 8.6,
                        fontWeight: FontWeight.w600,
                      ),
                    ),
                  ],
                ),
              ),
              TextButton.icon(
                onPressed: onShop,
                iconAlignment: IconAlignment.end,
                icon: const Icon(
                  Icons.arrow_forward_rounded,
                  size: 15,
                ),
                label: const Text('Browse Full Shop'),
              ),
            ],
          ),
          const SizedBox(height: 8),
          Align(
            alignment: Alignment.centerLeft,
            child: Wrap(
              spacing: 7,
              runSpacing: 7,
              children: filters
                  .map(
                    (filter) => ChoiceChip(
                      label: Text(filter),
                      selected: selectedFilter == filter,
                      onSelected: (_) => onFilterSelected(filter),
                      showCheckmark: false,
                      selectedColor: FarmColors.primary,
                      backgroundColor: const Color(0xFFF6F8F4),
                      side: BorderSide(
                        color: selectedFilter == filter
                            ? FarmColors.primary
                            : HpjWebUi.border,
                      ),
                      labelStyle: TextStyle(
                        color: selectedFilter == filter
                            ? Colors.white
                            : FarmColors.deepGreen,
                        fontSize: 7.9,
                        fontWeight: FontWeight.w900,
                      ),
                      padding: const EdgeInsets.symmetric(
                        horizontal: 10,
                        vertical: 5,
                      ),
                    ),
                  )
                  .toList(),
            ),
          ),
          const SizedBox(height: 9),
          if (products.isEmpty)
            Container(
              height: 104,
              width: double.infinity,
              alignment: Alignment.center,
              decoration: BoxDecoration(
                color: const Color(0xFFF7FAF5),
                borderRadius: BorderRadius.circular(12),
                border: Border.all(color: HpjWebUi.border),
              ),
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  const Icon(
                    Icons.eco_outlined,
                    color: FarmColors.primary,
                    size: 22,
                  ),
                  const SizedBox(height: 6),
                  Text(
                    selectedFilter == 'Deals'
                        ? 'No active deals right now.'
                        : selectedFilter == 'Organic'
                            ? 'No organic picks available right now.'
                            : selectedFilter == 'Fresh This Week'
                                ? 'No products marked fresh this week yet.'
                                : 'Fresh Picks will appear here.',
                    style: const TextStyle(
                      color: FarmColors.mutedText,
                      fontSize: 8.5,
                      fontWeight: FontWeight.w700,
                    ),
                  ),
                ],
              ),
            )
          else
            SizedBox(
              height: 214,
              child: Row(
                children: [
                  for (var i = 0; i < products.length; i++) ...[
                    Expanded(
                      child: _HpjFreshPickProductCard(
                        product: products[i],
                        favorite: isFavorite(products[i]),
                        onFavorite: () =>
                            onToggleFavorite(products[i]),
                        onOpen: () => onOpenProduct(products[i]),
                        onAdd: () => onAddProduct(products[i]),
                      ),
                    ),
                    if (i != products.length - 1)
                      const SizedBox(width: 8),
                  ],
                ],
              ),
            ),
        ],
      ),
