class _HpjFreshPickProductCard extends StatelessWidget {
  final Product product;
  final bool favorite;
  final VoidCallback onFavorite;
  final VoidCallback onOpen;
  final VoidCallback onAdd;

  const _HpjFreshPickProductCard({
    required this.product,
    required this.favorite,
    required this.onFavorite,
    required this.onOpen,
    required this.onAdd,
  });

  String get _sourceName {
    final farm = (product.farmName ?? '').trim();
    if (farm.isNotEmpty) return farm;

    final farmer = (product.farmerName ?? '').trim();
    if (farmer.isNotEmpty) return farmer;

    return 'HPJ Marketplace';
  }

  List<Widget> _badges() {
    final badges = <Widget>[];

    if (product.hasActiveDiscount) {
      badges.add(
        const _HpjFreshPickBadge(
          label: 'DEAL',
          background: Color(0xFFF6C526),
          foreground: FarmColors.deepGreen,
        ),
      );
    }

    if (product.isOrganic && badges.length < 2) {
      badges.add(
        const _HpjFreshPickBadge(
          label: 'ORGANIC',
          background: FarmColors.primary,
          foreground: Colors.white,
        ),
      );
    }

    if (isProductHarvestedThisWeek(product) && badges.length < 2) {
      badges.add(
        const _HpjFreshPickBadge(
          label: 'FRESH',
          background: Color(0xFFE7F3E3),
          foreground: FarmColors.primary,
        ),
      );
    }

    return badges.take(2).toList();
  }

  @override
  Widget build(BuildContext context) {
    final unit = (product.unit ?? '').trim();
    final badges = _badges();

    return Material(
      color: const Color(0xFFFEFFFD),
      borderRadius: BorderRadius.circular(12),
      child: InkWell(
        onTap: onOpen,
        borderRadius: BorderRadius.circular(12),
