class _HpjCommunityProduceCard extends StatelessWidget {
  final Product product;
  final VoidCallback onOpen;
  final VoidCallback onAdd;

  const _HpjCommunityProduceCard({
    required this.product,
    required this.onOpen,
    required this.onAdd,
  });

  String get _signal {
    if (product.isLowStock) return 'Limited stock';
    if (isProductHarvestedThisWeek(product)) return 'Fresh this week';
    if (product.hasActiveDiscount) return 'Trending now';
    if (product.isOrganic) return 'Organic pick';
    return 'Available now';
  }

  @override
  Widget build(BuildContext context) {
    final mobilePresentation = hpjUseMobileAppPresentation(context);
    return Material(
      color: const Color(0xFFFEFFFD),
      borderRadius: BorderRadius.circular(15),
      child: InkWell(
        onTap: onOpen,
        borderRadius: BorderRadius.circular(15),
        child: Container(
          height: mobilePresentation ? 224 : 274,
          padding: const EdgeInsets.all(10),
          decoration: BoxDecoration(
            borderRadius: BorderRadius.circular(15),
            border: Border.all(color: HpjWebUi.border),
          ),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Row(
                children: [
                  Container(
                    padding: const EdgeInsets.symmetric(
                      horizontal: 8,
                      vertical: 5,
                    ),
                    decoration: BoxDecoration(
                      color: const Color(0xFFEAF5E7),
                      borderRadius: BorderRadius.circular(999),
                    ),
                    child: const Text(
                      'Fresh produce',
                      style: TextStyle(
                        color: FarmColors.deepGreen,
                        fontSize: 7.2,
                        fontWeight: FontWeight.w900,
                      ),
                    ),
                  ),
                  const Spacer(),
                  if (product.isOrganic)
                    const Icon(
                      Icons.eco_rounded,
                      color: FarmColors.success,
                      size: 16,
                    ),
                ],
              ),
              const SizedBox(height: 8),
              Expanded(
                child: Center(
                  child: ProductVisual(
                    product: product,
                    size: mobilePresentation ? 100 : 125,
                    showOrganicBadge: false,
                  ),
                ),
              ),
              Text(
                product.name,
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
                style: const TextStyle(
                  color: FarmColors.ink,
                  fontSize: 10.2,
                  fontWeight: FontWeight.w900,
                ),
              ),
              const SizedBox(height: 2),
              Text(
                _signal,
                style: const TextStyle(
                  color: FarmColors.success,
                  fontSize: 7.4,
                  fontWeight: FontWeight.w800,
                ),
              ),
              const SizedBox(height: 6),
              SizedBox(
                width: double.infinity,
                height: 31,
                child: FilledButton.icon(
                  onPressed: product.canAddToCart ? onAdd : null,
                  icon: const Icon(Icons.add_shopping_cart_rounded, size: 13),
                  label: Text(
                    product.canAddToCart ? 'Add to My Box' : 'Unavailable',
                  ),
                  style: FilledButton.styleFrom(
                    backgroundColor: FarmColors.primary,
                    foregroundColor: Colors.white,
                    textStyle: const TextStyle(
                      fontSize: 7.5,
                      fontWeight: FontWeight.w900,
                    ),
                    shape: RoundedRectangleBorder(
                      borderRadius: BorderRadius.circular(9),
                    ),
                  ),
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

