class _HpjRightRailGrowTogetherCardState
    extends State<_HpjRightRailGrowTogetherCard> {
  late Future<List<HpjHarvestCircle>> _future;

  @override
  void initState() {
    super.initState();
    _future = fetchHpjHarvestCircles(limit: 6);
  }

  Future<void> _open() async {
    await Navigator.of(context).push<void>(
      MaterialPageRoute<void>(
        builder: (_) => const HpjHarvestCirclesScreen(),
      ),
    );
    if (!mounted) return;
    setState(() {
      _future = fetchHpjHarvestCircles(limit: 6);
    });
  }

  @override
  Widget build(BuildContext context) {
    return FutureBuilder<List<HpjHarvestCircle>>(
      future: _future,
      builder: (context, snapshot) {
        final circles = snapshot.data ?? const <HpjHarvestCircle>[];
        final mine = circles.where((circle) =>
            circle.isReserved || circle.isFollowing).toList();
        final visible = (mine.isNotEmpty ? mine : circles).take(4).toList();
        final harvesting = circles.where(
          (circle) => circle.status == 'harvesting',
        ).length;

        return Material(
          color: Colors.white,
          borderRadius: BorderRadius.circular(15),
          child: InkWell(
            onTap: _open,
            borderRadius: BorderRadius.circular(15),
            child: Container(
              width: double.infinity,
              padding: const EdgeInsets.all(11),
              decoration: BoxDecoration(
                borderRadius: BorderRadius.circular(15),
                border: Border.all(color: HpjWebUi.border),
              ),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Row(
                    children: [
                      Container(
                        width: 35,
                        height: 35,
                        decoration: BoxDecoration(
                          color: FarmColors.deepGreen,
                          borderRadius: BorderRadius.circular(11),
                        ),
                        child: const Icon(
                          Icons.spa_rounded,
                          color: Color(0xFFFFD45A),
                          size: 18,
                        ),
                      ),
                      const SizedBox(width: 9),
                      const Expanded(
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Text(
                              'GrowTogether',
                              style: TextStyle(
                                color: FarmColors.deepGreen,
                                fontSize: 12.5,
                                fontWeight: FontWeight.w900,
                              ),
                            ),
                            SizedBox(height: 1),
                            Text(
                              'Help decide what Jamaica grows next.',
                              style: TextStyle(
                                color: FarmColors.mutedText,
                                fontSize: 7.4,
                                fontWeight: FontWeight.w600,
                              ),
                            ),
                          ],
                        ),
                      ),
                      if (harvesting > 0)
                        Container(
                          padding: const EdgeInsets.symmetric(
                            horizontal: 7,
                            vertical: 4,
                          ),
                          decoration: BoxDecoration(
                            color: const Color(0xFFFFF0C6),
                            borderRadius: BorderRadius.circular(999),
                          ),
                          child: const Text(
                            'Harvesting',
                            style: TextStyle(
                              color: Color(0xFF8A6200),
                              fontSize: 6.7,
                              fontWeight: FontWeight.w900,
                            ),
                          ),
                        ),
                    ],
                  ),
                  const SizedBox(height: 9),
                  if (visible.isEmpty)
                    const Text(
                      'New Harvest Circles will appear as Jamaican produce moves toward harvest.',
                      style: TextStyle(
                        color: FarmColors.mutedText,
                        fontSize: 7.7,
                        height: 1.3,
                        fontWeight: FontWeight.w600,
                      ),
                    )
                  else
                    Row(
                      children: visible.map((circle) {
                        final clean = cleanHostedImageUrl(circle.imageUrl);
                        return Expanded(
                          child: Padding(
                            padding: const EdgeInsets.only(right: 5),
                            child: ClipRRect(
                              borderRadius: BorderRadius.circular(9),
                              child: SizedBox(
                                height: 42,
                                child: clean == null
                                    ? Container(
                                        color: const Color(0xFFEAF2E6),
                                        child: const Icon(
                                          Icons.eco_rounded,
                                          size: 16,
                                          color: FarmColors.primary,
                                        ),
                                      )
                                    : Image.network(
                                        clean,
                                        fit: BoxFit.cover,
                                        errorBuilder: (_, __, ___) =>
                                            Container(
                                          color: const Color(0xFFEAF2E6),
                                          child: const Icon(
                                            Icons.eco_rounded,
                                            size: 16,
                                            color: FarmColors.primary,
                                          ),
                                        ),
                                      ),
                              ),
                            ),
                          ),
                        );
                      }).toList(),
                    ),
                  const SizedBox(height: 8),
                  Row(
                    children: [
                      Expanded(
                        child: Text(
                          mine.isNotEmpty
                              ? '${mine.length} harvest${mine.length == 1 ? '' : 's'} in your GrowTogether'
                              : 'Reserve • Follow • Support',
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: const TextStyle(
                            color: FarmColors.deepGreen,
                            fontSize: 7.5,
                            fontWeight: FontWeight.w800,
                          ),
                        ),
                      ),
                      TextButton(
                        onPressed: _open,
                        child: const Text('Explore'),
                      ),
                    ],
                  ),
                ],
              ),
            ),
          ),
        );
      },
    );
  }
}

class _HpjSocialCommerceRightRail extends StatelessWidget {
  final Future<String> customerNameFuture;
  final int cartItemCount;
  final int savedCount;
  final int followedFarmCount;
  final List<Product> trendingProducts;
  final List<Product> favoriteProducts;
  final List<Product> recentlyViewedProducts;
  final VoidCallback onShop;
  final void Function(Product product) onOpenProduct;
  final VoidCallback onFarms;

  const _HpjSocialCommerceRightRail({
    required this.customerNameFuture,
    required this.cartItemCount,
    required this.savedCount,
    required this.followedFarmCount,
    required this.trendingProducts,
    required this.favoriteProducts,
    required this.recentlyViewedProducts,
    required this.onShop,
    required this.onOpenProduct,
    required this.onFarms,
  });

  String _firstName(String fullName) {
    final clean = fullName.trim();
    if (clean.isEmpty) return 'there';
    return clean.split(RegExp(r'\s+')).first;
  }

  @override
  Widget build(BuildContext context) {
    return Column(
      children: [
        FutureBuilder<String>(
          future: customerNameFuture,
          builder: (context, snapshot) {
            final name = _firstName(snapshot.data ?? '');
            return Container(
              width: double.infinity,
              padding: const EdgeInsets.all(13),
              decoration: BoxDecoration(
                borderRadius: BorderRadius.circular(15),
                gradient: const LinearGradient(
                  begin: Alignment.topLeft,
                  end: Alignment.bottomRight,
                  colors: [
                    Color(0xFF0C4B34),
                    Color(0xFF2C7143),
                  ],
                ),
              ),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    'Good to see you, $name!',
                    style: const TextStyle(
                      color: Colors.white,
                      fontSize: 13,
                      fontWeight: FontWeight.w900,
                    ),
                  ),
                  const SizedBox(height: 4),
                  Text(
                    'Fresh food. Stronger communities. A brighter Jamaica.',
                    style: TextStyle(
                      color: Colors.white.withOpacity(0.86),
                      fontSize: 8.8,
                      height: 1.25,
                      fontWeight: FontWeight.w600,
                    ),
                  ),
                  const SizedBox(height: 12),
                  Row(
                    children: [
                      Expanded(
                        child: _HpjRightRailStat(
                          value: '$followedFarmCount',
                          label: 'Farms followed',
                        ),
                      ),
                      Expanded(
                        child: _HpjRightRailStat(
                          value: '$cartItemCount',
                          label: 'In your box',
                        ),
                      ),
                      Expanded(
                        child: _HpjRightRailStat(
                          value: '$savedCount',
                          label: 'Saved',
                        ),
                      ),
                    ],
                  ),
                ],
              ),
            );
          },
        ),
        const SizedBox(height: 10),
        _HpjTrendingProductsPanel(
          products: trendingProducts,
          onShop: onShop,
          onOpenProduct: onOpenProduct,
        ),
        const SizedBox(height: 10),
        const _HpjRightRailMealPulseCard(),
        const SizedBox(height: 10),
        const _HpjRightRailGrowTogetherCard(),
        const SizedBox(height: 10),
        _HpjYourActivityPanel(
          favoriteProducts: favoriteProducts,
          recentlyViewedProducts: recentlyViewedProducts,
          cartItemCount: cartItemCount,
        ),
        const SizedBox(height: 12),
        Material(
          color: const Color(0xFFFFF3CF),
          borderRadius: BorderRadius.circular(14),
          child: InkWell(
            onTap: onFarms,
            borderRadius: BorderRadius.circular(14),
            child: const Padding(
              padding: EdgeInsets.all(14),
              child: Row(
                children: [
                  Icon(
                    Icons.eco_outlined,
                    color: FarmColors.primary,
                  ),
                  SizedBox(width: 10),
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(
                          'Together for a Greener Jamaica',
                          style: TextStyle(
                            color: FarmColors.deepGreen,
                            fontSize: 10.2,
                            fontWeight: FontWeight.w900,
                          ),
                        ),
                        SizedBox(height: 3),
                        Text(
