class _HpjTrendingProductsPanel extends StatelessWidget {
  final List<Product> products;
  final VoidCallback onShop;
  final void Function(Product product) onOpenProduct;

  const _HpjTrendingProductsPanel({
    required this.products,
    required this.onShop,
    required this.onOpenProduct,
  });

  @override
  Widget build(BuildContext context) {
    if (products.isEmpty) return const SizedBox.shrink();

    return Container(
      padding: const EdgeInsets.fromLTRB(12, 11, 12, 8),
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(15),
        border: Border.all(color: HpjWebUi.border),
      ),
      child: Column(
        children: [
          Row(
            children: [
              const Icon(
                Icons.trending_up_rounded,
                color: FarmColors.primary,
                size: 18,
              ),
              const SizedBox(width: 6),
              const Expanded(
                child: Text(
                  'Trending Produce',
                  style: TextStyle(
                    color: FarmColors.ink,
                    fontSize: 12.5,
                    fontWeight: FontWeight.w900,
                  ),
                ),
              ),
              TextButton(
                onPressed: onShop,
                child: const Text('See All'),
              ),
            ],
          ),
          ...products.asMap().entries.map(
                (entry) => InkWell(
                  onTap: () => onOpenProduct(entry.value),
                  child: Padding(
                    padding: const EdgeInsets.symmetric(
                      vertical: 6,
                    ),
                    child: Row(
                      children: [
                        Container(
                          width: 22,
                          height: 22,
                          alignment: Alignment.center,
                          decoration: BoxDecoration(
                            color: entry.key == 0
                                ? FarmColors.primary
                                : const Color(0xFFF0F3EC),
                            shape: BoxShape.circle,
                          ),
                          child: Text(
                            '${entry.key + 1}',
                            style: TextStyle(
                              color: entry.key == 0
                                  ? Colors.white
                                  : FarmColors.ink,
                              fontSize: 8,
                              fontWeight: FontWeight.w900,
                            ),
