class _HPJCategorySwipeCarousel extends StatefulWidget {
  final List<PopularCategorySummary> categories;
  final List<Product> products;
  final List<Product> favoriteProducts;
  final ValueChanged<String> onCategoryTap;

  const _HPJCategorySwipeCarousel({
    required this.categories,
    required this.products,
    this.favoriteProducts = const <Product>[],
    required this.onCategoryTap,
  });

  @override
  State<_HPJCategorySwipeCarousel> createState() =>
      _HPJCategorySwipeCarouselState();
}

class _HPJCategorySwipeCarouselState extends State<_HPJCategorySwipeCarousel> {
  PageController? _pageController;
  bool? _desktopCategoryMode;
  int _currentPage = 0;

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();

    final desktopWeb =
        kIsWeb && MediaQuery.sizeOf(context).width >= 1100;

    if (_pageController != null &&
        _desktopCategoryMode == desktopWeb) {
      return;
    }

    final oldController = _pageController;

    _desktopCategoryMode = desktopWeb;
    _pageController = PageController(
      initialPage: _currentPage,
      viewportFraction: desktopWeb ? 1.0 : 0.98,
    );

    if (oldController != null) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        oldController.dispose();
      });
    }
  }

  List<Product> _previewProductsFor(
    PopularCategorySummary category,
  ) {
    String cleanCategory(String value) {
      final key = value
          .trim()
          .toLowerCase()
          .replaceAll('&', 'and')
          .replaceAll(RegExp(r'\s+'), ' ');

      switch (key) {
        case 'vegetable':
        case 'vegetables':
          return 'vegetables';

        case 'fruit':
        case 'fruits':
          return 'fruits';

        case 'herb':
        case 'herbs':
        case 'herbs and seasonings':
        case 'herbs & seasonings':
          return 'herbs';

        case 'ground provision':
        case 'ground provisions':
          return 'ground provisions';

        case 'egg':
        case 'eggs':
          return 'eggs';

        case 'grain':
        case 'grains':
          return 'grains';

        case 'prepared food':
        case 'prepared foods':
          return 'prepared foods';

        case 'other':
        case 'pantry':
        case 'pantry and specialty':
        case 'pantry & specialty':
          return 'other';

        default:
          return key;
      }
    }

    final targetCategory = cleanCategory(category.name);

    final result = <Product>[];
    final seenProducts = <String>{};
    final seenImages = <String>{};

    Iterable<Product> source;

    if (targetCategory == 'favorites') {
      source = widget.favoriteProducts;
    } else {
      source = widget.products.where((product) {
        final productCategory = cleanCategory(product.category);

        return productCategory == targetCategory;
      });
    }

    for (final product in source) {
      final imageUrl = cleanHostedImageUrl(product.imageUrl);

      if (imageUrl == null || imageUrl.trim().isEmpty) {
        continue;
      }

      // Avoid using the exact same product twice.
      final productKey = '${product.name.trim().toLowerCase()}|$imageUrl';

      if (!seenProducts.add(productKey)) {
        continue;
      }

      // Avoid duplicate images.
      if (!seenImages.add(imageUrl)) {
        continue;
      }

      result.add(product);

      if (result.length >= 4) {
        break;
      }
    }

    // Keep the existing preview product as a fallback.
    if (result.isEmpty) {
      final fallback = category.previewProduct;
      final fallbackUrl = cleanHostedImageUrl(fallback.imageUrl);

      if (fallbackUrl != null && fallbackUrl.trim().isNotEmpty) {
        result.add(fallback);
      }
    }

    return result;
  }

  @override
  Widget build(BuildContext context) {
    if (widget.categories.isEmpty) {
      return const SizedBox.shrink();
    }

    return LayoutBuilder(
      builder: (context, constraints) {
        final width = constraints.maxWidth;

        final int cardsPerPage;

        if (width >= 1100) {
          cardsPerPage = 4;
        } else if (width >= 700) {
          cardsPerPage = 3;
        } else {
          cardsPerPage = 2;
        }

        final pageCount = (widget.categories.length / cardsPerPage).ceil();
        final desktopWeb =
            kIsWeb && MediaQuery.sizeOf(context).width >= 1100;

        return Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            SizedBox(
              height: desktopWeb ? 318 : 166,
              child: PageView.builder(
                controller: _pageController,
                padEnds: false,
                pageSnapping: true,
                physics: const BouncingScrollPhysics(),
                itemCount: pageCount,
                onPageChanged: (index) {
                  if (!mounted) return;

                  setState(() {
                    _currentPage = index;
                  });
                },
                itemBuilder: (context, pageIndex) {
                  final start = pageIndex * cardsPerPage;

                  final proposedEnd = start + cardsPerPage;

                  final end = proposedEnd > widget.categories.length
                      ? widget.categories.length
                      : proposedEnd;

                  final pageCategories = widget.categories.sublist(
                    start,
                    end,
                  );

                  return Row(
                    crossAxisAlignment: CrossAxisAlignment.stretch,
                    children: [
                      for (int slot = 0; slot < cardsPerPage; slot++) ...[
                        if (slot > 0) SizedBox(width: desktopWeb ? 16 : 10),
                        Expanded(
                          child: slot < pageCategories.length
                              ? _HPJImageCategoryCard(
                                  category: pageCategories[slot],
                                  previewProducts: _previewProductsFor(
                                    pageCategories[slot],
                                  ),
                                  onTap: () {
                                    widget.onCategoryTap(
                                      pageCategories[slot].name,
                                    );
                                  },
                                )
                              : const SizedBox.shrink(),
                        ),
                      ],
                    ],
                  );
                },
              ),
            ),
            if (pageCount > 1) ...[
              const SizedBox(height: 9),
              Row(
                mainAxisAlignment: MainAxisAlignment.center,
                children: List.generate(
                  pageCount,
                  (index) {
                    final active = index == _currentPage;

                    return AnimatedContainer(
                      duration: const Duration(
                        milliseconds: 220,
                      ),
                      curve: Curves.easeOut,
                      margin: const EdgeInsets.symmetric(
                        horizontal: 3,
                      ),
                      width: active ? 18 : 6,
                      height: 6,
                      decoration: BoxDecoration(
                        color: active
                            ? const Color(
                                0xFF285E3D,
                              )
                            : const Color(
                                0xFFD9DED6,
                              ),
                        borderRadius: BorderRadius.circular(
                          20,
                        ),
                      ),
                    );
                  },
                ),
              ),
            ],
          ],
        );
      },
    );
  }

  @override
  void dispose() {
    _pageController?.dispose();
    super.dispose();
  }
} // closes _HPJCategorySwipeCarouselState

class _HPJImageCategoryCard extends StatelessWidget {
  final PopularCategorySummary category;
  final List<Product> previewProducts;
  final VoidCallback onTap;

  const _HPJImageCategoryCard({
    required this.category,
    required this.previewProducts,
    required this.onTap,
  });

  String get _key => category.name.trim().toLowerCase();

  String get _displayName {
    switch (_key) {
      case 'herbs':
        return 'Herbs & Seasonings';

      case 'ground provisions':
        return 'Ground Provisions';

      case 'other':
        return 'Pantry & Specialty';

      case 'prepared foods':
        return 'Prepared Foods';

      default:
        return category.name;
    }
  }

  String get _tagline {
    switch (_key) {
      case 'vegetables':
      case 'vegetable':
        return 'FRESH. LOCAL. NOURISHING.';

      case 'fruits':
      case 'fruit':
        return 'SWEETNESS FROM OUR SOIL.';

      case 'ground provisions':
      case 'ground provision':
        return 'OUR ROOTS. YOUR TABLE.';

      case 'herbs':
      case 'herb':
        return 'BOLD FLAVOURS. REAL GOODNESS.';

      case 'eggs':
      case 'egg':
        return 'FARM FRESH. EVERYDAY GOODNESS.';

      case 'prepared foods':
      case 'prepared food':
        return 'LOCAL FLAVOUR. READY TO ENJOY.';

      case 'grains':
      case 'grain':
        return 'WHOLESOME STAPLES. SIMPLY GOOD.';

      default:
        return 'FRESH PICKS FROM JAMAICA.';
    }
  }

  Widget _imageTile(
    String? imageUrl, {
    double radius = 8,
  }) {
    return ClipRRect(
      borderRadius: BorderRadius.circular(radius),
      child: Container(
        color: FarmColors.cardSoft,
        child: imageUrl == null || imageUrl.isEmpty
            ? Container(
                color: const Color(0xFFF2F5EF),
              )
            : Image.network(
                imageUrl,
                fit: BoxFit.cover,
                alignment: Alignment.center,
                gaplessPlayback: true,
                cacheWidth: 420,
                filterQuality: FilterQuality.medium,
                errorBuilder: (
                  context,
                  error,
                  stackTrace,
                ) {
                  return Container(
                    color: const Color(0xFFF2F5EF),
                  );
                },
              ),
      ),
    );
  }

  Widget _compactImageCollage(List<String> images) {
    if (images.isEmpty) {
      return Container(
        color: FarmColors.cardSoft,
      );
    }

    if (images.length == 1) {
      return _imageTile(images[0]);
    }

    if (images.length == 2) {
      return Row(
        children: [
          Expanded(
            child: _imageTile(images[0]),
          ),
          const SizedBox(width: 6),
          Expanded(
            child: _imageTile(images[1]),
          ),
        ],
      );
    }

    if (images.length == 3) {
      return Row(
        children: [
          Expanded(
            child: _imageTile(images[0]),
          ),
          const SizedBox(width: 6),
          Expanded(
            child: Column(
              children: [
                Expanded(
                  child: _imageTile(images[1]),
                ),
                const SizedBox(height: 6),
                Expanded(
                  child: _imageTile(images[2]),
                ),
              ],
            ),
          ),
        ],
      );
    }

    return Column(
      children: [
        Expanded(
          child: Row(
            children: [
              Expanded(
                child: _imageTile(images[0]),
              ),
              const SizedBox(width: 4),
              Expanded(
                child: _imageTile(images[1]),
              ),
            ],
          ),
        ),
        const SizedBox(height: 4),
        Expanded(
          child: Row(
            children: [
              Expanded(
                child: _imageTile(images[2]),
              ),
              const SizedBox(width: 4),
              Expanded(
                child: _imageTile(images[3]),
              ),
            ],
          ),
        ),
      ],
    );
  }

  Widget _desktopImageCollage(List<String> images) {
    if (images.isEmpty) {
      return Container(
        color: const Color(0xFFF1F5EF),
      );
    }

    if (images.length == 1) {
      return _imageTile(
        images[0],
        radius: 13,
      );
    }

    if (images.length == 2) {
      return Row(
        children: [
          Expanded(
            flex: 6,
            child: _imageTile(
              images[0],
              radius: 13,
            ),
          ),
          const SizedBox(width: 4),
          Expanded(
            flex: 4,
            child: _imageTile(
              images[1],
              radius: 13,
            ),
          ),
        ],
      );
    }

    return Row(
      children: [
        Expanded(
          flex: 58,
          child: _imageTile(
            images[0],
            radius: 13,
          ),
        ),
        const SizedBox(width: 4),
        Expanded(
          flex: 42,
          child: Column(
            children: [
              Expanded(
                child: _imageTile(
                  images[1],
                  radius: 13,
                ),
              ),
              const SizedBox(height: 4),
              Expanded(
                child: _imageTile(
                  images[2],
                  radius: 13,
                ),
              ),
            ],
          ),
        ),
      ],
    );
  }

  @override
  Widget build(BuildContext context) {
    final desktopWeb =
        kIsWeb && MediaQuery.sizeOf(context).width >= 1100;

    final imageUrls = previewProducts
        .map(
          (product) => cleanHostedImageUrl(product.imageUrl),
        )
        .whereType<String>()
        .where((url) => url.isNotEmpty)
        .take(desktopWeb ? 3 : 4)
        .toList();

    final count = category.availableItemCount;
    final countLabel = count == 1 ? '1 item' : '$count items';

    if (!desktopWeb) {
      return Material(
        color: Colors.transparent,
        child: InkWell(
          onTap: onTap,
          borderRadius: BorderRadius.circular(18),
          child: Ink(
            decoration: BoxDecoration(
              color: FarmColors.card,
              borderRadius: BorderRadius.circular(18),
              border: Border.all(
                color: FarmColors.line.withOpacity(0.90),
              ),
              boxShadow: [
                BoxShadow(
                  color: Colors.black.withOpacity(0.03),
                  blurRadius: 10,
                  offset: const Offset(0, 3),
                ),
              ],
            ),
            child: ClipRRect(
              borderRadius: BorderRadius.circular(18),
              child: Column(
                children: [
                  Expanded(
                    child: Padding(
                      padding: const EdgeInsets.fromLTRB(
                        6,
                        6,
                        6,
                        0,
                      ),
                      child: _compactImageCollage(imageUrls),
                    ),
                  ),
                  Padding(
                    padding: const EdgeInsets.fromLTRB(
                      10,
                      8,
                      9,
                      10,
                    ),
                    child: Row(
                      children: [
                        Expanded(
                          child: Text(
                            _displayName,
                            maxLines: 2,
                            overflow: TextOverflow.ellipsis,
                            style: const TextStyle(
                              color: FarmColors.ink,
                              fontSize: 12.5,
                              fontWeight: FontWeight.w900,
                              height: 1.04,
                              letterSpacing: -0.15,
                            ),
                          ),
                        ),
                        const SizedBox(width: 5),
                        Container(
                          padding: const EdgeInsets.symmetric(
                            horizontal: 7,
                            vertical: 4,
                          ),
                          decoration: BoxDecoration(
                            color: FarmColors.primarySoft
                                .withOpacity(0.68),
                            borderRadius:
                                BorderRadius.circular(30),
                          ),
                          child: Text(
                            countLabel,
                            maxLines: 1,
                            style: const TextStyle(
                              color: FarmColors.green,
                              fontSize: 9.8,
                              fontWeight: FontWeight.w900,
                            ),
                          ),
                        ),
                      ],
                    ),
                  ),
                ],
              ),
            ),
          ),
        ),
      );
    }

    return Material(
      color: Colors.transparent,
      child: InkWell(
        onTap: onTap,
        mouseCursor: SystemMouseCursors.click,
        borderRadius: BorderRadius.circular(20),
        child: Ink(
          decoration: BoxDecoration(
            color: const Color(0xFFFFFEFB),
            borderRadius: BorderRadius.circular(20),
            border: Border.all(
              color: const Color(0xFFDDE5D9),
              width: 1,
            ),
            boxShadow: [
              BoxShadow(
                color: const Color(0xFF143E2E)
                    .withOpacity(.065),
                blurRadius: 22,
                offset: const Offset(0, 8),
              ),
            ],
          ),
          child: ClipRRect(
            borderRadius: BorderRadius.circular(20),
            child: Column(
              children: [
                Expanded(
                  child: Padding(
                    padding: const EdgeInsets.fromLTRB(
                      8,
                      8,
                      8,
                      0,
                    ),
                    child: _desktopImageCollage(imageUrls),
                  ),
                ),
                Container(
                  height: 76,
                  padding: const EdgeInsets.fromLTRB(
                    14,
                    10,
                    12,
                    10,
