  Future<void> _openNearYouProduct(Product product) async {
    _rememberViewedProduct(product);
    final quantity = widget.quantityForProduct(product);
    final nutrientToFilter = await Navigator.push<String>(
      context,
      MaterialPageRoute(
        builder: (detailContext) => ProductDetailScreen(
          product: product,
          quantity: quantity,
          nutrientBadges: _nutrientBadgesForProduct(product, limit: null),
          onNutrientTap: (nutrient) {
            Navigator.of(detailContext).pop(nutrient);
          },
          onAdd: () => _addProductToCart(product),
          onRemove: () => _removeProductFromCart(product),
          onAddProduct: _addProductToCart,
          onViewed: _rememberViewedProduct,
          onViewMyBox: widget.onViewMyBox,
          onCheckout: widget.onCheckout,
        ),
      ),
    );

    if (!mounted || nutrientToFilter == null || nutrientToFilter.trim().isEmpty) {
      return;
    }

    setState(() {
      selectedCategory = 'All';
      selectedShopFilter = 'All items';
      selectedShopNutrient = nutrientToFilter.trim();
      selectedShopAvailability = 'Any availability';
      selectedShopPrice = 'Any price';
      selectedShopFarm = 'All farms';
      selectedShopSpecial = 'All';
      selectedSort = 'Recommended';
      searchController.clear();
    });
  }

  List<Product> _productsForJamaicaParish(String parish) {
    final canonical = _canonicalJamaicaParish(parish);
    return products
        .where(isVisibleCustomerProduct)
        .where((product) => product.canAddToCart)
        .where(
          (product) =>
              _canonicalJamaicaParish((product.parish ?? '').trim()) ==
              canonical,
        )
        .toList();
  }

  Future<void> _selectJamaicaParish(String parish) async {
    final canonical = _canonicalJamaicaParish(parish);
    if (canonical.isEmpty || !_jamaicaParishes.contains(canonical)) return;

    if (mounted) {
      setState(() {
        selectedNearArea = canonical;
        nearAreaReady = true;
      });
    }

    await HpjSmartLocalStore.writeString('shop_near_area', canonical);
  }

