  }

  int get _premiumActiveShopControlCount {
    return <bool>[
      selectedCategory != 'All',
      selectedShopNutrient != 'All',
      selectedShopAvailability != 'Any availability',
      selectedShopPrice != 'Any price',
      selectedShopFarm != 'All farms',
      selectedShopSpecial != 'All',
      selectedSort != 'Recommended',
    ].where((active) => active).length;
  }

  Widget _premiumShopHero(
    List<Product> allProducts,
    String activeCategory,
  ) {
    final availableCount = allProducts
        .where((product) => product.canAddToCart)
        .length;
    final localCount = allProducts
        .where((product) => product.canAddToCart && product.isLocal)
        .length;
    final boxCount = allProducts.fold<int>(
      0,
      (sum, product) => sum + widget.quantityForProduct(product),
    );
    final categoryLabel = activeCategory == 'All'
        ? 'Fresh Jamaican produce'
        : activeCategory == 'Favorites'
            ? 'Your saved fresh picks'
            : activeCategory;

    if (HpjWebUi.isDesktop(context)) {
      // Desktop website already has the premium storefront header.
      // Do not repeat another large marketplace hero here.
      return const SizedBox.shrink();
    }

    return Container(
      width: double.infinity,
      padding: const EdgeInsets.fromLTRB(18, 18, 16, 17),
      decoration: BoxDecoration(
        color: const Color(0xFF073F2C),
        borderRadius: BorderRadius.circular(28),
        boxShadow: [
          BoxShadow(
            color: const Color(0xFF073F2C).withOpacity(0.18),
            blurRadius: 24,
            offset: const Offset(0, 12),
          ),
        ],
      ),
      child: Stack(
        children: [
          Positioned(
            right: -38,
            top: -52,
            child: Container(
              width: 145,
              height: 145,
              decoration: BoxDecoration(
                shape: BoxShape.circle,
                color: Colors.white.withOpacity(0.035),
              ),
            ),
          ),
          Positioned(
            right: 34,
            bottom: -64,
            child: Container(
              width: 118,
              height: 118,
              decoration: BoxDecoration(
                shape: BoxShape.circle,
                border: Border.all(
                  color: const Color(0xFFE8C66A).withOpacity(0.13),
                  width: 18,
                ),
              ),
            ),
          ),
          Row(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    const Text(
                      'HPJ MARKETPLACE',
                      style: TextStyle(
                        color: Color(0xFFE8C66A),
                        fontSize: 10,
                        fontWeight: FontWeight.w900,
                        letterSpacing: 1.3,
