  Widget _premiumShopCategoryStrip(
    List<String> availableCategories,
    String activeCategory,
  ) {
    if (availableCategories.isEmpty) return const SizedBox.shrink();

    final desktopWeb = HpjWebUi.isDesktop(context);

    if (desktopWeb) {
      return Container(
        height: 44,
        padding: const EdgeInsets.symmetric(
          horizontal: 22,
        ),
        decoration: BoxDecoration(
          color: const Color(0xFFFAFBF8),
          border: Border(
            bottom: BorderSide(
              color: FarmColors.line.withOpacity(.72),
            ),
          ),
        ),
        child: ListView.separated(
          scrollDirection: Axis.horizontal,
          physics: const BouncingScrollPhysics(),
          itemCount: availableCategories.length,
          separatorBuilder: (_, __) =>
              const SizedBox(width: 23),
          itemBuilder: (context, index) {
            final category =
                availableCategories[index];
            final selected =
                activeCategory == category;
            final favorites =
                category == 'Favorites';

            return InkWell(
              onTap: () {
                setState(() {
                  selectedCategory = category;
                });
              },
              mouseCursor:
                  SystemMouseCursors.click,
              hoverColor: Colors.transparent,
              splashColor: Colors.transparent,
              child: Column(
                mainAxisAlignment:
                    MainAxisAlignment.end,
                children: [
                  Padding(
                    padding:
                        const EdgeInsets.symmetric(
                      horizontal: 2,
                      vertical: 10,
                    ),
                    child: Row(
                      mainAxisSize:
                          MainAxisSize.min,
                      children: [
                        if (favorites) ...[
                          Icon(
                            selected
                                ? Icons
                                    .favorite_rounded
                                : Icons
                                    .favorite_border_rounded,
                            size: 13,
                            color: selected
                                ? FarmColors
                                    .deepGreen
                                : FarmColors
                                    .mutedText,
                          ),
                          const SizedBox(width: 5),
                        ],
                        Text(
                          category,
                          style: TextStyle(
                            color: selected
                                ? FarmColors
                                    .deepGreen
                                : FarmColors
                                    .mutedText,
                            fontSize: 10.4,
                            letterSpacing: -.05,
                            fontWeight:
                                selected
                                    ? FontWeight
                                        .w900
                                    : FontWeight
                                        .w700,
                          ),
                        ),
                      ],
                    ),
                  ),
                  AnimatedContainer(
                    duration: const Duration(
                      milliseconds: 180,
                    ),
                    width: selected ? 24 : 0,
                    height: 2,
                    decoration: BoxDecoration(
                      color:
                          const Color(0xFFFFC62A),
                      borderRadius:
                          BorderRadius.circular(999),
                    ),
                  ),
                ],
              ),
            );
          },
        ),
      );
    }

    return SizedBox(
      height: 48,
      child: ListView.separated(
        scrollDirection: Axis.horizontal,
        physics: const BouncingScrollPhysics(),
        padding: const EdgeInsets.symmetric(
          horizontal: 18,
        ),
        itemCount: availableCategories.length,
        separatorBuilder: (_, __) => const SizedBox(width: 8),
        itemBuilder: (context, index) {
          final category = availableCategories[index];
          final selected = activeCategory == category;
          final favorites = category == 'Favorites';

          return Material(
            color: Colors.transparent,
            child: InkWell(
              borderRadius: BorderRadius.circular(999),
              onTap: () {
                setState(() {
                  selectedCategory = category;
                });
              },
              child: AnimatedContainer(
                duration: const Duration(milliseconds: 190),
                padding: const EdgeInsets.symmetric(
                  horizontal: 14,
                  vertical: 10,
                ),
                decoration: BoxDecoration(
                  color: selected
                      ? const Color(0xFF073F2C)
                      : const Color(0xFFFFFEFC),
                  borderRadius: BorderRadius.circular(999),
                  border: Border.all(
                    color: selected
                        ? const Color(0xFF073F2C)
                        : FarmColors.line.withOpacity(0.85),
                  ),
                  boxShadow: selected
                      ? [
                          BoxShadow(
                            color: const Color(0xFF073F2C).withOpacity(0.11),
                            blurRadius: 12,
                            offset: const Offset(0, 5),
                          ),
                        ]
                      : const [],
                ),
                child: Row(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    if (favorites) ...[
                      Icon(
                        selected ? Icons.favorite_rounded : Icons.favorite_border_rounded,
                        size: 15,
                        color: selected ? Colors.white : FarmColors.danger,
                      ),
                      const SizedBox(width: 6),
                    ],
                    Text(
                      category,
                      maxLines: 1,
                      style: TextStyle(
                        color: selected ? Colors.white : FarmColors.deepGreen,
                        fontSize: 12,
                        fontWeight: FontWeight.w900,
                      ),
                    ),
                  ],
                ),
              ),
            ),
          );
        },
      ),
    );
  }


