    Widget wideCard() {
      return Container(
        decoration: BoxDecoration(
          color: muted ? FarmColors.cardSoft : const Color(0xFFFFFEFC),
          borderRadius: BorderRadius.circular(desktopWeb ? 20 : 24),
          border: Border.all(
            color: muted
                ? FarmColors.danger.withOpacity(0.12)
                : FarmColors.line.withOpacity(0.82),
          ),
          boxShadow: [
            BoxShadow(
              color: FarmColors.shadow.withOpacity(muted ? 0.02 : 0.05),
              blurRadius: 17,
              offset: const Offset(0, 7),
            ),
          ],
        ),
        child: Material(
          color: Colors.transparent,
          child: InkWell(
            borderRadius: BorderRadius.circular(desktopWeb ? 20 : 24),
            hoverColor: desktopWeb ? HpjWebUi.hover : Colors.transparent,
            mouseCursor: kIsWeb ? SystemMouseCursors.click : MouseCursor.defer,
            onTap: onOpenDetails,
            child: Padding(
              padding: const EdgeInsets.all(12),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Row(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      ClipRRect(
                        borderRadius: BorderRadius.circular(19),
                        child: SizedBox(
                          width: desktopWeb ? 118 : 104,
                          height: desktopWeb ? 118 : 104,
                          child: premiumImage(compact: false),
                        ),
                      ),
                      const SizedBox(width: 13),
                      Expanded(
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Row(
                              crossAxisAlignment: CrossAxisAlignment.start,
                              children: [
                                Expanded(
                                  child: Text(
                                    name,
                                    maxLines: 2,
                                    overflow: TextOverflow.ellipsis,
                                    style: const TextStyle(
                                      color: FarmColors.ink,
                                      fontSize: 16.5,
                                      height: 1.08,
                                      fontWeight: FontWeight.w900,
                                      letterSpacing: -0.22,
                                    ),
                                  ),
                                ),
                                const SizedBox(width: 8),
                                favoriteButton(),
                              ],
                            ),
                            const SizedBox(height: 5),
                            if (farmName.isNotEmpty)
                              farmerLink(),
                            const SizedBox(height: 4),
                            Text(
                              description,
                              maxLines: 2,
                              overflow: TextOverflow.ellipsis,
                              style: const TextStyle(
                                color: FarmColors.mutedText,
                                fontSize: 11.8,
                                height: 1.25,
                                fontWeight: FontWeight.w600,
                              ),
                            ),
                            const SizedBox(height: 5),
                            fulfilmentConfidence(),
                          ],
                        ),
                      ),
                    ],
                  ),
                  const SizedBox(height: 9),
                  Wrap(
                    spacing: 5,
                    runSpacing: 5,
                    children: [
                      if (product.isOrganic) const _SmallShopChip(label: 'Organic'),
                      ProductOriginBadge(
                        product: product,
                        compact: true,
                        includeIcon: false,
                      ),
                      ProductUnitChip(product: product, compact: true),
                      ProductAvailabilityChip(product: product, compact: true),
                      for (final badge in nutrientBadges.take(2))
                        _SmallShopChip(
                          label: badge,
                          color: FarmColors.deepGreen,
                          backgroundColor: FarmColors.primarySoft.withOpacity(0.78),
                        ),
                    ],
                  ),
                  const SizedBox(height: 11),
                  Container(
                    width: double.infinity,
                    padding: const EdgeInsets.fromLTRB(12, 10, 10, 10),
                    decoration: BoxDecoration(
                      color: muted
                          ? FarmColors.cardSoft
                          : FarmColors.primarySoft.withOpacity(0.58),
                      borderRadius: BorderRadius.circular(18),
                      border: Border.all(color: FarmColors.line.withOpacity(0.60)),
                    ),
                    child: LayoutBuilder(
                      builder: (context, constraints) {
                        final narrow = constraints.maxWidth < 245;
                        if (narrow) {
                          return Column(
                            crossAxisAlignment: CrossAxisAlignment.stretch,
                            children: [
                              DiscountPriceText(product: product, compact: true),
                              const SizedBox(height: 9),
                              primaryAction(fullWidth: true),
                            ],
                          );
                        }
                        return Row(
                          children: [
                            Expanded(
                              child: DiscountPriceText(product: product, compact: true),
                            ),
                            const SizedBox(width: 10),
                            primaryAction(fullWidth: false),
                          ],
                        );
                      },
                    ),
                  ),
                ],
              ),
            ),
          ),
        ),
      );
    }

    if (desktopWeb) {
      return desktopPremiumCard();
    }

    return LayoutBuilder(
      builder: (context, constraints) {
        return constraints.maxWidth < 260
            ? compactCard()
            : wideCard();
      },
    );
  }
}

class _SmallShopChip extends StatelessWidget {
  final String label;
  final Color color;
  final Color backgroundColor;

  const _SmallShopChip({
    required this.label,
    this.color = FarmColors.green,
    this.backgroundColor = FarmColors.lightGreen,
  });

  @override
  Widget build(BuildContext context) {
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
      decoration: BoxDecoration(
        color: backgroundColor,
        borderRadius: BorderRadius.circular(999),
      ),
      child: Text(
        label,
        style: TextStyle(
          color: color,
          fontSize: 11.5,
          fontWeight: FontWeight.w900,
        ),
      ),
    );
  }
}


