// =====================================================
// HPJ PREMIUM UI PHASE 6 — MY FARM BOX + SECURE CHECKOUT
// Visual-only upgrade. Business logic, Supabase, pricing, stock, coupon,
// payment, fulfillment, idempotency, and navigation flows remain intact.
// =====================================================

class _PremiumWebMyBoxMvpHero extends StatelessWidget {
  final int totalItems;
  final int distinctItems;
  final double subtotal;
  final double savings;
  final int unavailableItems;
  final VoidCallback onContinueShopping;

  const _PremiumWebMyBoxMvpHero({
    required this.totalItems,
    required this.distinctItems,
    required this.subtotal,
    required this.savings,
    required this.unavailableItems,
    required this.onContinueShopping,
  });

  Widget _metric({
    required IconData icon,
    required String value,
    required String label,
    bool warning = false,
  }) {
    return Expanded(
      child: Container(
        padding: const EdgeInsets.all(11),
        decoration: BoxDecoration(
          color: Colors.white.withOpacity(.11),
          borderRadius: BorderRadius.circular(16),
          border: Border.all(
            color: warning
                ? const Color(0xFFE8C768).withOpacity(.45)
                : Colors.white.withOpacity(.15),
          ),
        ),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Icon(
              icon,
              color: const Color(0xFFE8C768),
              size: 17,
            ),
            const SizedBox(height: 7),
            Text(
              value,
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              style: const TextStyle(
                color: Colors.white,
                fontSize: 15,
                fontWeight: FontWeight.w900,
              ),
            ),
            const SizedBox(height: 2),
            Text(
              label,
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              style: TextStyle(
                color: Colors.white.withOpacity(.72),
                fontSize: 8.4,
                fontWeight: FontWeight.w800,
              ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _step({
    required String number,
    required String label,
    required bool active,
  }) {
    return Expanded(
      child: Row(
        children: [
          Container(
            width: 31,
            height: 31,
            alignment: Alignment.center,
            decoration: BoxDecoration(
              color: active
                  ? const Color(0xFFE8C768)
                  : Colors.white.withOpacity(.10),
              shape: BoxShape.circle,
              border: Border.all(
                color: active
                    ? const Color(0xFFE8C768)
                    : Colors.white.withOpacity(.18),
              ),
            ),
            child: Text(
              number,
              style: TextStyle(
                color: active
                    ? FarmColors.deepGreen
                    : Colors.white,
                fontSize: 9.3,
                fontWeight: FontWeight.w900,
              ),
            ),
          ),
          const SizedBox(width: 7),
          Expanded(
            child: Text(
              label,
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              style: TextStyle(
                color: active
                    ? Colors.white
                    : Colors.white.withOpacity(.66),
                fontSize: 9.4,
                fontWeight: FontWeight.w800,
              ),
            ),
          ),
        ],
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final ready = totalItems > 0 && unavailableItems == 0;

    return Container(
      padding: const EdgeInsets.all(22),
      decoration: BoxDecoration(
        borderRadius: BorderRadius.circular(30),
        gradient: const LinearGradient(
          begin: Alignment.topLeft,
          end: Alignment.bottomRight,
          colors: [
            Color(0xFF073F2C),
            FarmColors.green,
            Color(0xFF4E8157),
          ],
        ),
        boxShadow: [
          BoxShadow(
            color: const Color(0xFF073F2C).withOpacity(.15),
            blurRadius: 25,
            offset: const Offset(0, 11),
          ),
        ],
      ),
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          Expanded(
            flex: 6,
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                const Text(
                  'MY HPJ BOX',
                  style: TextStyle(
                    color: Color(0xFFE8C768),
                    fontSize: 10.2,
                    fontWeight: FontWeight.w900,
                    letterSpacing: .95,
                  ),
                ),
                const SizedBox(height: 7),
                const Text(
                  'Review your fresh picks before checkout',
                  style: TextStyle(
                    color: Colors.white,
                    fontSize: 27,
                    height: 1.03,
                    letterSpacing: -.6,
                    fontWeight: FontWeight.w900,
                  ),
                ),
                const SizedBox(height: 8),
                SizedBox(
                  width: 610,
                  child: Text(
                    ready
                        ? 'Your box is ready. Check quantities, confirm availability and continue to secure checkout when you are satisfied.'
                        : unavailableItems > 0
                            ? 'One or more items need attention before checkout. Review your selection and update unavailable products.'
                            : 'Add fresh Jamaican produce to your box, compare your selection and checkout when you are ready.',
                    style: TextStyle(
                      color: Colors.white.withOpacity(.82),
                      fontSize: 11.7,
                      height: 1.45,
                      fontWeight: FontWeight.w600,
                    ),
                  ),
                ),
                const SizedBox(height: 18),
                Container(
                  padding: const EdgeInsets.all(11),
                  decoration: BoxDecoration(
                    color: Colors.white.withOpacity(.08),
                    borderRadius: BorderRadius.circular(17),
                    border: Border.all(
                      color: Colors.white.withOpacity(.12),
                    ),
                  ),
                  child: Row(
                    children: [
                      _step(
                        number: '01',
                        label: 'Build Box',
                        active: true,
                      ),
                      Container(
                        width: 1,
                        height: 31,
                        margin: const EdgeInsets.symmetric(horizontal: 8),
                        color: Colors.white.withOpacity(.12),
                      ),
                      _step(
                        number: '02',
                        label: 'Review',
                        active: totalItems > 0,
                      ),
                      Container(
                        width: 1,
                        height: 31,
                        margin: const EdgeInsets.symmetric(horizontal: 8),
                        color: Colors.white.withOpacity(.12),
                      ),
                      _step(
                        number: '03',
                        label: 'Checkout',
                        active: ready,
                      ),
                    ],
                  ),
                ),
                const SizedBox(height: 14),
                OutlinedButton.icon(
                  onPressed: onContinueShopping,
                  style: OutlinedButton.styleFrom(
                    foregroundColor: Colors.white,
                    side: BorderSide(
                      color: Colors.white.withOpacity(.34),
                    ),
                    padding: const EdgeInsets.symmetric(
                      horizontal: 16,
                      vertical: 13,
                    ),
                    textStyle: const TextStyle(
                      fontWeight: FontWeight.w900,
                    ),
                  ),
                  icon: const Icon(
                    Icons.shopping_basket_outlined,
                    size: 17,
                  ),
                  label: const Text('Continue Shopping'),
                ),
              ],
            ),
          ),
          const SizedBox(width: 20),
          Expanded(
            flex: 4,
            child: Column(
              children: [
                Row(
                  children: [
                    _metric(
                      icon: Icons.inventory_2_outlined,
                      value: '$totalItems',
                      label: 'Items',
                    ),
                    const SizedBox(width: 8),
                    _metric(
                      icon: Icons.shopping_bag_outlined,
                      value: '$distinctItems',
                      label: 'Products',
                    ),
                  ],
                ),
                const SizedBox(height: 8),
                Row(
                  children: [
                    _metric(
                      icon: Icons.receipt_long_outlined,
                      value: formatJmd(subtotal),
                      label: 'Subtotal',
                    ),
                    const SizedBox(width: 8),
                    _metric(
                      icon: savings > 0
                          ? Icons.savings_outlined
                          : Icons.verified_outlined,
                      value: savings > 0
                          ? formatJmd(savings)
                          : (ready ? 'Ready' : 'Review'),
                      label: savings > 0
                          ? 'You save'
                          : 'Checkout',
                      warning: unavailableItems > 0,
                    ),
                  ],
                ),
                const SizedBox(height: 8),
                Container(
                  width: double.infinity,
                  padding: const EdgeInsets.all(11),
                  decoration: BoxDecoration(
                    color: unavailableItems > 0
                        ? const Color(0xFFFFF3D8).withOpacity(.95)
                        : Colors.white.withOpacity(.09),
                    borderRadius: BorderRadius.circular(15),
                    border: Border.all(
                      color: unavailableItems > 0
                          ? const Color(0xFFE8C768).withOpacity(.45)
                          : Colors.white.withOpacity(.14),
                    ),
                  ),
                  child: Row(
                    children: [
                      Icon(
                        unavailableItems > 0
                            ? Icons.warning_amber_rounded
                            : Icons.verified_outlined,
                        color: unavailableItems > 0
                            ? const Color(0xFF805512)
                            : const Color(0xFFE8C768),
                        size: 17,
                      ),
                      const SizedBox(width: 7),
                      Expanded(
                        child: Text(
                          unavailableItems > 0
                              ? '$unavailableItems item${unavailableItems == 1 ? '' : 's'} need attention before checkout.'
                              : 'HPJ rechecks stock again during secure checkout.',
                          style: TextStyle(
                            color: unavailableItems > 0
                                ? const Color(0xFF805512)
                                : Colors.white.withOpacity(.80),
                            fontSize: 8.8,
                            height: 1.3,
                            fontWeight: FontWeight.w700,
                          ),
                        ),
                      ),
                    ],
                  ),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }
}

class FarmBoxScreen extends StatefulWidget {
  final List<Product> cart;
  final void Function(Product product) onRemoveFromCart;
  final void Function(Product product) onAddToCart;
  final VoidCallback onOrderPlaced;
  final VoidCallback onShopTap;
  final VoidCallback? onInventoryChanged;
  final ValueChanged<List<CartLine>>? onSavedCartSynced;
  final int refreshVersion;

  const FarmBoxScreen({
    super.key,
    required this.cart,
    required this.onRemoveFromCart,
    required this.onAddToCart,
    required this.onOrderPlaced,
    required this.onShopTap,
    this.onInventoryChanged,
    this.onSavedCartSynced,
    this.refreshVersion = 0,
  });

  @override
  State<FarmBoxScreen> createState() => _FarmBoxScreenState();
}

class _FarmBoxScreenState extends State<FarmBoxScreen> {
  List<CartLine>? savedCartLines;
  bool loadingSavedCart = false;

  // Keep the My Box top bar consistent with Customer Home.
  // The same parish, notification and account dropdown controls are reused
  // here so portal switching is available from every primary customer tab.
  late Future<CustomerProfile?> _myBoxProfileFuture;
  String _myBoxParish = 'St. Elizabeth';
  bool _myBoxParishReady = false;

  List<Product> get cart => widget.cart;
  VoidCallback? get onInventoryChanged => widget.onInventoryChanged;

  @override
  void initState() {
    super.initState();
    _myBoxProfileFuture = fetchCurrentCustomerProfile();
    unawaited(_loadMyBoxParish());
    _loadSavedCartIfNeeded();
  }

  Future<void> _loadMyBoxParish() async {
    try {
      final saved = await HpjSmartLocalStore.readString('shop_near_area');
      final checkout = await HpjSmartLocalStore.readString('checkout_zone');
      final value = (saved ?? '').trim().isNotEmpty
          ? saved!.trim()
          : (checkout ?? '').trim().isNotEmpty
              ? checkout!.trim()
              : 'St. Elizabeth';

      if (!mounted) return;
      setState(() {
        _myBoxParish = value;
        _myBoxParishReady = true;
      });
    } catch (_) {
      if (!mounted) return;
      setState(() => _myBoxParishReady = true);
    }
  }

  Future<void> _openMyBoxParishPicker() async {
    const parishes = <String>[
      'Hanover',
      'Westmoreland',
      'St. James',
      'Trelawny',
      'St. Elizabeth',
      'Manchester',
      'Clarendon',
      'St. Ann',
      'St. Catherine',
      'St. Mary',
      'St. Andrew',
      'Kingston',
      'Portland',
      'St. Thomas',
    ];

    final selected = await showModalBottomSheet<String>(
      context: context,
      useSafeArea: true,
      backgroundColor: Colors.transparent,
      builder: (sheetContext) {
        return Container(
          constraints: BoxConstraints(
            maxHeight: MediaQuery.sizeOf(sheetContext).height * .72,
          ),
          decoration: const BoxDecoration(
            color: Color(0xFFFFFEFB),
            borderRadius: BorderRadius.vertical(top: Radius.circular(28)),
          ),
          child: Column(
            children: [
              const SizedBox(height: 10),
              Container(
                width: 42,
                height: 4,
                decoration: BoxDecoration(
                  color: const Color(0xFFD7DDD4),
                  borderRadius: BorderRadius.circular(999),
                ),
              ),
              const Padding(
                padding: EdgeInsets.fromLTRB(18, 18, 18, 10),
                child: Row(
                  children: [
                    Icon(
                      Icons.location_on_rounded,
                      color: FarmColors.green,
                      size: 21,
                    ),
                    SizedBox(width: 8),
                    Expanded(
                      child: Text(
                        'Choose your parish',
                        style: TextStyle(
                          color: FarmColors.deepGreen,
                          fontSize: 20,
                          fontWeight: FontWeight.w900,
                          letterSpacing: -.3,
                        ),
                      ),
                    ),
                  ],
                ),
              ),
              Expanded(
                child: ListView.separated(
                  padding: const EdgeInsets.fromLTRB(12, 0, 12, 18),
                  itemCount: parishes.length,
                  separatorBuilder: (_, __) => const SizedBox(height: 2),
                  itemBuilder: (context, index) {
                    final parish = parishes[index];
                    final selectedNow = parish == _myBoxParish;
                    return ListTile(
                      shape: RoundedRectangleBorder(
                        borderRadius: BorderRadius.circular(16),
                      ),
                      tileColor: selectedNow
                          ? const Color(0xFFEAF3E7)
                          : Colors.transparent,
                      leading: Icon(
                        selectedNow
                            ? Icons.location_on_rounded
                            : Icons.location_on_outlined,
                        color: FarmColors.green,
                      ),
                      title: Text(
                        parish,
                        style: const TextStyle(
                          color: FarmColors.deepGreen,
                          fontWeight: FontWeight.w800,
                        ),
                      ),
                      trailing: selectedNow
                          ? const Icon(
                              Icons.check_circle_rounded,
                              color: FarmColors.green,
                            )
                          : null,
                      onTap: () => Navigator.of(sheetContext).pop(parish),
                    );
                  },
                ),
              ),
            ],
          ),
        );
      },
    );

    final clean = selected?.trim() ?? '';
    if (!mounted || clean.isEmpty || clean == _myBoxParish) return;

    setState(() {
      _myBoxParish = clean;
      _myBoxParishReady = true;
    });
    await HpjSmartLocalStore.writeString('shop_near_area', clean);
  }

  @override
  void didUpdateWidget(covariant FarmBoxScreen oldWidget) {
    super.didUpdateWidget(oldWidget);

    if (!isLoggedIn) {
      savedCartLines = null;
      return;
    }

    if (widget.refreshVersion != oldWidget.refreshVersion) {
      _loadSavedCartIfNeeded(force: true);
      return;
    }

    if (savedCartLines == null) {
      _loadSavedCartIfNeeded();
    }
  }

  Future<void> _loadSavedCartIfNeeded({bool force = false}) async {
    if (!isLoggedIn || loadingSavedCart) return;
    if (!force && savedCartLines != null) return;

    final loadUserId = supabase.auth.currentUser?.id.trim() ?? '';
    if (loadUserId.isEmpty) return;

    setState(() => loadingSavedCart = true);
    try {
      final lines = await fetchSavedCartLinesForCurrentUser(
        throwOnError: true,
      );
      final currentUserId = supabase.auth.currentUser?.id.trim() ?? '';
      if (!mounted || currentUserId != loadUserId) return;

      setState(() => savedCartLines = lines);
      widget.onSavedCartSynced?.call(lines);
    } catch (error) {
      farmDebugLog('Saved farm box restore skipped: $error');
    } finally {
      if (mounted) setState(() => loadingSavedCart = false);
    }
  }

  void onAddToCart(Product product) {
    widget.onAddToCart(product);
    if (isLoggedIn && savedCartLines != null) {
      _adjustSavedLine(product, 1);
    }
    Future.microtask(() => saveCartItemForCurrentUser(product));
  }

  void onRemoveFromCart(Product product) {
    widget.onRemoveFromCart(product);
    if (isLoggedIn && savedCartLines != null) {
      _adjustSavedLine(product, -1);
    }
    Future.microtask(() => removeCartItemForCurrentUser(product));
  }

  void onOrderPlaced() {
    setState(() => savedCartLines = const <CartLine>[]);
    Future.microtask(clearSavedCartForCurrentUser);
    widget.onOrderPlaced();
  }

  void _adjustSavedLine(Product product, int delta) {
    final current = List<CartLine>.from(savedCartLines ?? const <CartLine>[]);
    final index = current.indexWhere((line) => line.product.id == product.id);

    if (index < 0) {
      if (delta > 0) {
        current.add(CartLine(product: product, quantity: 1));
      }
    } else {
      final nextQuantity = current[index].quantity + delta;
      if (nextQuantity <= 0) {
        current.removeAt(index);
      } else {
        current[index] = current[index].copyWith(quantity: nextQuantity);
      }
    }

    if (mounted) {
      setState(() => savedCartLines = current);
    }
  }

  Map<String, CartLine> get groupedCart {
    final restoredLines = savedCartLines;
    if (isLoggedIn && restoredLines != null) {
      return <String, CartLine>{
        for (final line in restoredLines)
          if (line.product.id.trim().isNotEmpty && line.quantity > 0)
            line.product.id: line,
      };
    }

    final grouped = <String, CartLine>{};

    for (final product in cart) {
      if (grouped.containsKey(product.id)) {
        grouped[product.id] = grouped[product.id]!.copyWith(
          quantity: grouped[product.id]!.quantity + 1,
        );
      } else {
        grouped[product.id] = CartLine(product: product, quantity: 1);
      }
    }

    return grouped;
  }

  double get subtotal {
    return groupedCart.values.fold(
      0,
      (total, line) => total + (line.product.effectivePrice * line.quantity),
    );
  }

  double get originalSubtotal {
    return groupedCart.values.fold(
      0,
      (total, line) =>
          total + (line.product.originalPriceValue * line.quantity),
    );
  }

  double get totalSavings {
    final savings = originalSubtotal - subtotal;
    return savings <= 0 ? 0 : savings;
  }

  int get totalItems {
    return groupedCart.values.fold(0, (total, line) => total + line.quantity);
  }

  int get unavailableItems {
    return groupedCart.values
        .where((line) => !line.product.canAddToCart)
        .length;
  }

  int get distinctItems => groupedCart.length;

