        child: AnimatedOpacity(
          opacity: onPressed == null ? 0.36 : 1,
          duration: const Duration(milliseconds: 140),
          child: Container(
            height: 36,
            width: 36,
            decoration: BoxDecoration(
              color: filled ? const Color(0xFF0B5138) : Colors.white,
              shape: BoxShape.circle,
              border: Border.all(
                color: filled
                    ? const Color(0xFF0B5138)
                    : FarmColors.green.withOpacity(0.17),
              ),
              boxShadow: filled
                  ? [
                      BoxShadow(
                        color: const Color(0xFF073F2C).withOpacity(0.18),
                        blurRadius: 10,
                        offset: const Offset(0, 4),
                      ),
                    ]
                  : const [],
            ),
            child: Icon(
              icon,
              size: 18,
              color: filled ? Colors.white : FarmColors.green,
            ),
          ),
        ),
      ),
    );
  }

  Widget _quantityControl(CartLine line) {
    final product = line.product;
    final canIncrease =
        product.canAddToCart && line.quantity < product.stockQuantity;

    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 5),
      decoration: BoxDecoration(
        color: const Color(0xFFF4F7F2),
        borderRadius: BorderRadius.circular(999),
        border: Border.all(color: const Color(0xFFDDE5DB)),
      ),
      child: Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          _quantityButton(
            icon: Icons.remove_rounded,
            onPressed: () => onRemoveFromCart(product),
          ),
          Container(
            constraints: const BoxConstraints(minWidth: 42),
            padding: const EdgeInsets.symmetric(horizontal: 7),
            child: Text(
              '${line.quantity}',
              textAlign: TextAlign.center,
              style: const TextStyle(
                color: FarmColors.ink,
                fontSize: 15.5,
                fontWeight: FontWeight.w900,
              ),
            ),
          ),
          _quantityButton(
            icon: Icons.add_rounded,
            filled: true,
            onPressed: canIncrease ? () => onAddToCart(product) : null,
          ),
        ],
      ),
    );
  }

