  Widget _desktopCartLineCard(
    CartLine line,
  ) {
    final product = line.product;
    final farmName =
        (product.farmName ??
                product.farmerName ??
                '')
            .trim();
    final unit =
        (product.unit ?? '').trim();
    final lineTotal =
        product.effectivePrice * line.quantity;
    final lineSavings =
        ((product.originalPriceValue -
                    product.effectivePrice) *
                line.quantity)
            .clamp(
              0,
              double.infinity,
            )
            .toDouble();

    return Container(
      margin: const EdgeInsets.only(
        bottom: 12,
      ),
      padding: const EdgeInsets.all(14),
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius:
            BorderRadius.circular(16),
        border: Border.all(
          color: product.canAddToCart
              ? const Color(0xFFDDE5DD)
              : FarmColors.danger
                  .withOpacity(.24),
        ),
        boxShadow: [
          BoxShadow(
            color: const Color(0xFF0B432F)
                .withOpacity(.035),
            blurRadius: 18,
            offset: const Offset(0, 7),
          ),
        ],
      ),
      child: Row(
        crossAxisAlignment:
            CrossAxisAlignment.center,
        children: [
          Container(
            width: 112,
            height: 112,
            padding: const EdgeInsets.all(7),
            decoration: BoxDecoration(
              color:
                  const Color(0xFFFAFBF8),
              borderRadius:
                  BorderRadius.circular(14),
            ),
            child: Center(
              child: ProductVisual(
                product: product,
                size: 98,
                showOrganicBadge: false,
              ),
            ),
          ),
          const SizedBox(width: 16),

          Expanded(
            child: Column(
              crossAxisAlignment:
                  CrossAxisAlignment.start,
              children: [
                Row(
                  crossAxisAlignment:
                      CrossAxisAlignment.start,
                  children: [
                    Expanded(
                      child: Column(
                        crossAxisAlignment:
                            CrossAxisAlignment
                                .start,
                        children: [
                          Text(
                            product.name,
                            maxLines: 2,
                            overflow:
                                TextOverflow
                                    .ellipsis,
                            style:
                                const TextStyle(
                              color:
                                  FarmColors.ink,
                              fontSize: 15.5,
                              height: 1.08,
                              letterSpacing:
                                  -.22,
                              fontWeight:
                                  FontWeight.w900,
                            ),
                          ),
                          const SizedBox(
                            height: 5,
                          ),
                          Text(
                            farmName.isNotEmpty
                                ? farmName
                                : product.category,
                            maxLines: 1,
                            overflow:
                                TextOverflow
                                    .ellipsis,
                            style:
                                const TextStyle(
                              color: FarmColors
                                  .mutedText,
                              fontSize: 9.7,
                              fontWeight:
                                  FontWeight.w600,
                            ),
                          ),
                        ],
                      ),
                    ),
                    const SizedBox(width: 14),
                    Column(
                      crossAxisAlignment:
                          CrossAxisAlignment.end,
                      children: [
                        Text(
                          formatJmd(
                            lineTotal,
                          ),
                          style:
                              const TextStyle(
                            color: FarmColors
                                .deepGreen,
                            fontSize: 16.5,
                            height: 1,
                            fontWeight:
                                FontWeight.w900,
                          ),
                        ),
                        const SizedBox(
                          height: 4,
                        ),
                        Text(
                          unit.isEmpty
                              ? '${formatJmd(product.effectivePrice)} each'
                              : '${formatJmd(product.effectivePrice)} / $unit',
                          style:
                              const TextStyle(
                            color: FarmColors
                                .mutedText,
                            fontSize: 8.8,
                            fontWeight:
                                FontWeight.w600,
                          ),
                        ),
                      ],
                    ),
                  ],
                ),

                const SizedBox(height: 15),

                Row(
                  children: [
                    if (!product.canAddToCart)
                      Container(
                        padding:
                            const EdgeInsets
                                .symmetric(
                          horizontal: 9,
                          vertical: 6,
                        ),
                        decoration:
                            BoxDecoration(
                          color: FarmColors
                              .dangerSoft,
                          borderRadius:
                              BorderRadius
                                  .circular(
                            999,
                          ),
                        ),
                        child:
                            const Text(
                          'Unavailable',
                          style: TextStyle(
                            color: FarmColors
                                .danger,
                            fontSize: 8.5,
                            fontWeight:
                                FontWeight
                                    .w900,
                          ),
                        ),
                      )
                    else if (lineSavings >
                        0)
                      Container(
                        padding:
                            const EdgeInsets
                                .symmetric(
                          horizontal: 9,
                          vertical: 6,
                        ),
                        decoration:
                            BoxDecoration(
                          color:
                              const Color(
                            0xFFFFF2D3,
                          ),
                          borderRadius:
                              BorderRadius
                                  .circular(
                            999,
                          ),
                        ),
                        child: Text(
                          'Save ${formatJmd(lineSavings)}',
                          style:
                              const TextStyle(
                            color:
                                Color(0xFF8B6500),
                            fontSize: 8.5,
                            fontWeight:
                                FontWeight
                                    .w900,
                          ),
                        ),
                      )
                    else
                      Text(
                        product.canAddToCart
                            ? 'Available'
                            : 'Unavailable',
                        style:
                            const TextStyle(
                          color: FarmColors
                              .mutedText,
                          fontSize: 8.8,
                          fontWeight:
                              FontWeight.w700,
                        ),
                      ),

                    const Spacer(),

                    Container(
                      padding:
                          const EdgeInsets
                              .symmetric(
                        horizontal: 6,
                        vertical: 5,
                      ),
                      decoration:
                          BoxDecoration(
                        color:
                            const Color(
                          0xFFF7F9F6,
                        ),
                        borderRadius:
                            BorderRadius
                                .circular(10),
                        border: Border.all(
                          color:
                              const Color(
                            0xFFDDE5DD,
                          ),
                        ),
                      ),
                      child: Row(
                        mainAxisSize:
                            MainAxisSize.min,
                        children: [
                          IconButton(
                            tooltip:
                                line.quantity >
                                        1
                                    ? 'Decrease'
                                    : 'Remove',
                            visualDensity:
                                VisualDensity
                                    .compact,
                            padding:
                                EdgeInsets.zero,
                            constraints:
                                const BoxConstraints(
                              minWidth: 30,
                              minHeight: 30,
                            ),
                            onPressed: () =>
                                onRemoveFromCart(
                              product,
                            ),
                            icon: Icon(
                              line.quantity >
                                      1
                                  ? Icons
                                      .remove_rounded
                                  : Icons
                                      .delete_outline_rounded,
                              size: 17,
                              color:
                                  FarmColors
                                      .deepGreen,
                            ),
                          ),
                          SizedBox(
                            width: 36,
                            child: Text(
                              '${line.quantity}',
                              textAlign:
                                  TextAlign
                                      .center,
                              style:
                                  const TextStyle(
                                color:
                                    FarmColors
                                        .ink,
                                fontSize: 12,
                                fontWeight:
                                    FontWeight
                                        .w900,
                              ),
                            ),
                          ),
                          IconButton(
                            tooltip:
                                'Increase',
                            visualDensity:
                                VisualDensity
                                    .compact,
                            padding:
                                EdgeInsets.zero,
                            constraints:
                                const BoxConstraints(
                              minWidth: 30,
                              minHeight: 30,
                            ),
                            onPressed:
                                product.canAddToCart
                                    ? () =>
                                        onAddToCart(
                                          product,
                                        )
                                    : null,
                            icon: const Icon(
                              Icons.add_rounded,
                              size: 17,
                              color:
                                  FarmColors
                                      .deepGreen,
                            ),
                          ),
                        ],
                      ),
                    ),
                  ],
                ),

                if (!product
                    .canAddToCart) ...[
                  const SizedBox(height: 10),
                  const Text(
                    'Remove this item before checkout.',
                    style: TextStyle(
                      color: FarmColors.danger,
                      fontSize: 8.8,
                      fontWeight:
                          FontWeight.w800,
                    ),
                  ),
                ],
              ],
            ),
          ),
        ],
      ),
    );
  }

  Widget _desktopOrderSummary(
    BuildContext context,
    List<CartLine> lines,
  ) {
    final hasUnavailable =
        unavailableItems > 0;

    return Container(
      padding: const EdgeInsets.all(18),
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius:
            BorderRadius.circular(18),
        border: Border.all(
          color: const Color(0xFFDDE5DD),
        ),
        boxShadow: [
          BoxShadow(
            color: const Color(0xFF0B432F)
                .withOpacity(.055),
            blurRadius: 24,
            offset: const Offset(0, 9),
          ),
        ],
      ),
      child: Column(
        crossAxisAlignment:
            CrossAxisAlignment.start,
        children: [
          const Text(
            'ORDER SUMMARY',
            style: TextStyle(
              color: Color(0xFF8A6A08),
              fontSize: 7.8,
              letterSpacing: 1.2,
              fontWeight: FontWeight.w900,
            ),
          ),
          const SizedBox(height: 6),
          const Text(
            'My Box',
            style: TextStyle(
              color: FarmColors.ink,
              fontSize: 20,
              height: 1,
              fontWeight: FontWeight.w900,
              letterSpacing: -.35,
            ),
          ),
          const SizedBox(height: 18),

          _summaryRow(
            'Products',
            '$distinctItems',
          ),
          _summaryRow(
            'Items',
            '$totalItems',
          ),
          if (totalSavings > 0)
            _summaryRow(
              'Savings',
              '-${formatJmd(totalSavings)}',
            ),

          const Padding(
            padding:
                EdgeInsets.symmetric(
              vertical: 9,
            ),
            child: Divider(
              height: 1,
              color: Color(0xFFE2E8E1),
            ),
          ),

          _summaryRow(
            'Subtotal',
            formatJmd(subtotal),
            bold: true,
          ),

          const SizedBox(height: 14),

          if (hasUnavailable) ...[
            Container(
              width: double.infinity,
              padding:
                  const EdgeInsets.all(10),
              decoration: BoxDecoration(
                color: FarmColors.dangerSoft,
                borderRadius:
                    BorderRadius.circular(12),
              ),
              child: const Row(
                children: [
                  Icon(
                    Icons
                        .error_outline_rounded,
                    color: FarmColors.danger,
                    size: 16,
                  ),
                  SizedBox(width: 7),
                  Expanded(
                    child: Text(
                      'Remove unavailable items before checkout.',
                      style: TextStyle(
                        color:
                            FarmColors.danger,
                        fontSize: 9,
                        height: 1.25,
                        fontWeight:
                            FontWeight.w800,
                      ),
                    ),
                  ),
                ],
              ),
            ),
            const SizedBox(height: 11),
          ],

          SizedBox(
            width: double.infinity,
            height: 48,
            child: FilledButton.icon(
              onPressed:
                  lines.isEmpty ||
                          hasUnavailable
                      ? null
                      : () async {
                          final allowed =
                              await requireLoginForCheckout(
                            context,
                          );

                          if (!context.mounted ||
                              !allowed) {
                            return;
                          }

                          Navigator.push(
                            context,
                            MaterialPageRoute(
                              builder:
                                  (_) =>
                                      CheckoutScreen(
                                cartLines:
                                    lines,
                                subtotal:
                                    subtotal,
                                onOrderPlaced:
                                    onOrderPlaced,
                                onInventoryChanged:
                                    onInventoryChanged,
                              ),
                            ),
                          );
                        },
