                  child: ListView(
                    physics:
                        const AlwaysScrollableScrollPhysics(),
                    padding: EdgeInsets.zero,
                    children: [
                      _desktopMyBoxHeader(
                        lines,
                      ),
                      if (!isLoggedIn) ...[
                        const _PremiumWebGuestPurchaseNotice(
                          compact: true,
                        ),
                        const SizedBox(
                          height: 14,
                        ),
                      ],
                      _emptyBoxInviteCard(
                        context,
                      ),
                    ],
                  ),
                ),
        ),
      );
    }

    return FarmPage(
      child: Stack(
        children: [
          RefreshIndicator(
            onRefresh: () => _loadSavedCartIfNeeded(force: true),
            child: ListView(
              physics: const AlwaysScrollableScrollPhysics(),
              padding: EdgeInsets.fromLTRB(
                14,
                12,
                14,
                hasItems
                    ? (hpjUseMobileAppPresentation(context) ? 178 : 238)
                    : 120,
              ),
              children: [
                _boxHeroCard(lines),
                const SizedBox(height: 14),
                if (lines.isEmpty)
                  _emptyBoxInviteCard(context)
                else ...[
                  _selectedItemsHeader(lines),
                  const SizedBox(height: 13),
                  ...lines.map(_cartLineCard),
                  const SizedBox(height: 4),
                  _mobileAddMoreProduceCard(context, lines),
                  const SizedBox(height: 14),
                ],
              ],
            ),
          ),
          if (hasItems)
            Positioned(
              left: 16,
              right: 16,
              bottom: 0,
              child: _checkoutBar(context, lines),
            ),
        ],
      ),
    );
  }
}

