  String _orderPlacedDateLabel(DateTime? value) {
    if (value == null) return 'Placed date unavailable';

    final date = value.toLocal();
    const months = <String>[
      'Jan',
      'Feb',
      'Mar',
      'Apr',
      'May',
      'Jun',
      'Jul',
      'Aug',
      'Sep',
      'Oct',
      'Nov',
      'Dec',
    ];

    return 'Placed ${months[date.month - 1]} ${date.day}, ${date.year}';
  }

  Color _orderStatusColor(String rawStatus) {
    switch (rawStatus.trim().toLowerCase()) {
      case 'delivered':
      case 'completed':
        return FarmColors.green;
      case 'ready':
      case 'ready_for_pickup':
        return const Color(0xFF2F6E4B);
      case 'out_for_delivery':
        return const Color(0xFF1F6C84);
      case 'preparing':
      case 'confirmed':
        return const Color(0xFFC38322);
      case 'cancelled':
      case 'canceled':
      case 'rejected':
        return FarmColors.danger;
      default:
        return const Color(0xFF66736C);
    }
  }

  IconData _orderStatusIcon(String rawStatus) {
    switch (rawStatus.trim().toLowerCase()) {
      case 'delivered':
      case 'completed':
        return Icons.check_circle_outline_rounded;
      case 'ready':
      case 'ready_for_pickup':
        return Icons.inventory_2_outlined;
      case 'out_for_delivery':
        return Icons.local_shipping_outlined;
      case 'preparing':
        return Icons.inventory_outlined;
      case 'confirmed':
        return Icons.verified_outlined;
      case 'cancelled':
      case 'canceled':
      case 'rejected':
        return Icons.cancel_outlined;
      default:
        return Icons.schedule_rounded;
    }
  }

  @override
  void initState() {
    super.initState();
    _ordersFuture = fetchOrders(forceRefresh: true);
    _authSubscription = supabase.auth.onAuthStateChange.listen((_) {
      if (mounted) {
        _refreshOrders();
      }
    });
  }

  Future<void> _refreshOrders() async {
    FarmDataCache.clearOrders();
    final future = fetchOrders(forceRefresh: true);
    if (mounted) {
      setState(() {
        _ordersFuture = future;
      });
    }
    await future;
  }

  @override
  void dispose() {
    _authSubscription?.cancel();
    super.dispose();
  }

