  Future<String?> _fetchCustomerBoxPhotoUrl() async {
    final response = await supabase
        .from('orders')
        .select('box_photo_url')
        .eq('id', widget.orderId)
        .maybeSingle();

    final url = response?['box_photo_url']?.toString().trim();

    if (url == null || url.isEmpty) return null;

    return url;
  }

  Future<void> _openReorderPreview(
    OrderDetails order,
  ) async {
    if (_loadingReorder) return;

    final addToCart = widget.onAddToCart;

    if (addToCart == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text(
            'Reorder is not available from this screen right now.',
          ),
        ),
      );
      return;
    }

    setState(() => _loadingReorder = true);

    try {
      final productIds = order.items
          .map((item) => item.productId.trim())
          .where((id) => id.isNotEmpty)
          .toSet()
          .toList();

      if (productIds.isEmpty) {
        throw Exception(
          'The products from this order could not be identified.',
        );
      }

      final response =
          await supabase.from('products').select().inFilter('id', productIds);

      final currentProducts = (response as List)
          .map(
            (row) => Product.fromSupabase(
              Map<String, dynamic>.from(row as Map),
            ),
          )
          .toList();

      final productsById = <String, Product>{
        for (final product in currentProducts) product.id.trim(): product,
      };

      final previewLines = order.items.map((previousItem) {
        final productId = previousItem.productId.trim();
        final product = productsById[productId];

        String unavailableReason = '';

        if (product == null) {
          unavailableReason = 'No longer listed';
        } else if (product.isOutOfStock) {
          unavailableReason = 'Out of stock';
        } else if (!product.canAddToCart) {
          unavailableReason = 'Currently unavailable';
        }

        return _ReorderPreviewLine(
          previousItem: previousItem,
          product: product,
          unavailableReason: unavailableReason,
          selected: product != null && product.canAddToCart,
        );
      }).toList();

      if (!mounted) return;

      final availableLines =
          previewLines.where((line) => line.isAvailable).toList();

      if (availableLines.isEmpty) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text(
              'None of the products from this order are available right now.',
            ),
          ),
        );
        return;
      }

      final confirmedLines =
          await showModalBottomSheet<List<_ReorderPreviewLine>>(
        context: context,
        isScrollControlled: true,
        useSafeArea: true,
        backgroundColor: FarmColors.background,
        builder: (sheetContext) {
          return StatefulBuilder(
            builder: (sheetContext, setSheetState) {
              final available =
                  previewLines.where((line) => line.isAvailable).toList();

              final unavailable =
                  previewLines.where((line) => !line.isAvailable).toList();

              final selected =
                  available.where((line) => line.selected).toList();

              final estimatedTotal = selected.fold<double>(
                0,
                (total, line) => total + line.currentLineTotal,
              );

              return FractionallySizedBox(
                heightFactor: 0.88,
                child: Padding(
                  padding: const EdgeInsets.fromLTRB(
                    18,
                    14,
                    18,
                    18,
                  ),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Center(
                        child: Container(
                          width: 46,
                          height: 5,
                          decoration: BoxDecoration(
                            color: FarmColors.line,
                            borderRadius: BorderRadius.circular(999),
                          ),
                        ),
                      ),
                      const SizedBox(height: 18),
                      const Text(
                        'Reorder Review',
                        style: TextStyle(
                          color: FarmColors.ink,
                          fontSize: 22,
                          fontWeight: FontWeight.w900,
                        ),
                      ),
                      const SizedBox(height: 6),
                      const Text(
                        'Prices and availability have been refreshed. '
                        'Review the products before adding them to My Box.',
                        style: TextStyle(
                          color: FarmColors.mutedText,
                          fontWeight: FontWeight.w700,
                          height: 1.3,
                        ),
                      ),
                      const SizedBox(height: 18),
                      Expanded(
                        child: ListView(
                          children: [
                            const Text(
                              'Available today',
                              style: TextStyle(
                                color: FarmColors.green,
                                fontSize: 16,
                                fontWeight: FontWeight.w900,
                              ),
                            ),
                            const SizedBox(height: 10),
                            ...available.map((line) {
                              final product = line.product!;
                              final quantity = line.previousItem.quantity < 1
                                  ? 1
                                  : line.previousItem.quantity;

                              return Container(
                                margin: const EdgeInsets.only(bottom: 10),
                                padding: const EdgeInsets.all(12),
                                decoration: BoxDecoration(
                                  color: FarmColors.card,
                                  borderRadius: BorderRadius.circular(18),
                                  border: Border.all(
                                    color: FarmColors.line,
                                  ),
                                ),
                                child: Row(
                                  children: [
                                    Checkbox(
                                      value: line.selected,
                                      onChanged: (value) {
                                        setSheetState(() {
                                          line.selected = value ?? false;
                                        });
                                      },
                                    ),
                                    ProductVisual(
                                      product: product,
                                      size: 48,
                                      showOrganicBadge: false,
                                    ),
                                    const SizedBox(width: 11),
                                    Expanded(
                                      child: Column(
                                        crossAxisAlignment:
                                            CrossAxisAlignment.start,
                                        children: [
                                          Text(
                                            product.name,
                                            style: const TextStyle(
                                              color: FarmColors.ink,
                                              fontWeight: FontWeight.w900,
                                            ),
                                          ),
                                          const SizedBox(height: 3),
                                          Text(
                                            'Qty: $quantity • '
                                            '${formatJmd(product.effectivePrice)} each',
                                            style: const TextStyle(
                                              color: FarmColors.mutedText,
                                              fontWeight: FontWeight.w700,
                                              fontSize: 12,
                                            ),
                                          ),
                                        ],
                                      ),
                                    ),
                                    Text(
                                      formatJmd(
                                        line.currentLineTotal,
                                      ),
                                      style: const TextStyle(
                                        color: FarmColors.green,
                                        fontWeight: FontWeight.w900,
                                      ),
                                    ),
                                  ],
                                ),
                              );
                            }),
                            if (unavailable.isNotEmpty) ...[
                              const SizedBox(height: 12),
                              const Text(
                                'Unavailable today',
                                style: TextStyle(
                                  color: FarmColors.danger,
                                  fontSize: 16,
                                  fontWeight: FontWeight.w900,
                                ),
                              ),
                              const SizedBox(height: 10),
                              ...unavailable.map(
                                (line) => Container(
                                  width: double.infinity,
                                  margin: const EdgeInsets.only(
                                    bottom: 9,
                                  ),
                                  padding: const EdgeInsets.all(12),
                                  decoration: BoxDecoration(
                                    color: FarmColors.cardSoft,
                                    borderRadius: BorderRadius.circular(18),
                                    border: Border.all(
                                      color: FarmColors.line,
                                    ),
                                  ),
                                  child: Row(
                                    children: [
                                      const Icon(
                                        Icons.block_outlined,
                                        color: FarmColors.danger,
                                        size: 20,
                                      ),
                                      const SizedBox(width: 10),
                                      Expanded(
                                        child: Text(
                                          line.previousItem.productName,
                                          style: const TextStyle(
                                            color: FarmColors.ink,
                                            fontWeight: FontWeight.w800,
                                          ),
                                        ),
                                      ),
                                      Text(
                                        line.unavailableReason,
                                        style: const TextStyle(
                                          color: FarmColors.danger,
                                          fontWeight: FontWeight.w800,
                                          fontSize: 12,
                                        ),
                                      ),
                                    ],
                                  ),
                                ),
                              ),
                            ],
                          ],
                        ),
                      ),
                      const SizedBox(height: 12),
                      Container(
                        width: double.infinity,
                        padding: const EdgeInsets.all(14),
                        decoration: BoxDecoration(
                          color: FarmColors.primarySoft,
                          borderRadius: BorderRadius.circular(18),
                          border: Border.all(
                            color: FarmColors.line,
                          ),
                        ),
                        child: Row(
                          children: [
                            const Expanded(
                              child: Text(
                                'Estimated total',
                                style: TextStyle(
                                  color: FarmColors.ink,
                                  fontWeight: FontWeight.w900,
                                ),
                              ),
                            ),
                            Text(
                              formatJmd(estimatedTotal),
                              style: const TextStyle(
                                color: FarmColors.green,
                                fontSize: 18,
                                fontWeight: FontWeight.w900,
                              ),
                            ),
                          ],
                        ),
                      ),
                      const SizedBox(height: 12),
                      SizedBox(
                        width: double.infinity,
                        child: ElevatedButton.icon(
                          icon: const Icon(
                            Icons.shopping_basket_outlined,
                          ),
                          label: const Text(
                            'Add Selected to My Box',
                          ),
                          onPressed: selected.isEmpty
                              ? null
                              : () {
                                  Navigator.of(sheetContext).pop(
                                    List<_ReorderPreviewLine>.from(
                                      selected,
                                    ),
                                  );
                                },
                        ),
                      ),
                    ],
                  ),
                ),
              );
            },
          );
        },
      );

      if (confirmedLines == null || confirmedLines.isEmpty) {
        return;
      }

      for (final line in confirmedLines) {
        final product = line.product;

        if (product == null || !product.canAddToCart) {
          continue;
        }

        final quantity =
            line.previousItem.quantity < 1 ? 1 : line.previousItem.quantity;

        for (var count = 0; count < quantity; count++) {
          addToCart(product);
          await saveCartItemForCurrentUser(product);
        }
      }

      if (!mounted) return;

      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text(
            'Selected products were added to My Box.',
          ),
        ),
      );

      if (widget.onOpenMyBox != null) {
        widget.onOpenMyBox!.call();

        Navigator.of(context).popUntil(
          (route) => route.isFirst,
        );
      }
    } catch (error) {
      if (!mounted) return;

      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            'Could not prepare this reorder: $error',
          ),
        ),
      );
    } finally {
      if (mounted) {
        setState(() => _loadingReorder = false);
      }
    }
  }

  Widget _customerBoxPhotoCard() {
    return FutureBuilder<String?>(
      future: _fetchCustomerBoxPhotoUrl(),
      builder: (context, snapshot) {
        final photoUrl = snapshot.data;

        if (snapshot.connectionState == ConnectionState.waiting) {
          return const SizedBox.shrink();
        }

        if (photoUrl == null || photoUrl.isEmpty) {
          return const SizedBox.shrink();
        }

        return FarmCard(
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              const Row(
                children: [
                  Icon(Icons.photo_camera_outlined, color: FarmColors.green),
                  SizedBox(width: 8),
                  Text(
                    'Your Box Photo',
                    style: TextStyle(
                      color: FarmColors.ink,
                      fontSize: 16,
                      fontWeight: FontWeight.w900,
                    ),
                  ),
                ],
              ),
              const SizedBox(height: 10),
              ClipRRect(
                borderRadius: BorderRadius.all(Radius.circular(18)),
                child: Image.network(
                  photoUrl,
                  width: double.infinity,
                  height: 220,
                  fit: BoxFit.cover,
                  errorBuilder: (context, error, stackTrace) {
                    return Container(
                      width: double.infinity,
                      padding: const EdgeInsets.all(16),
                      decoration: BoxDecoration(
                        color: FarmColors.cardSoft,
                        borderRadius: BorderRadius.circular(18),
                      ),
                      child: const Text(
                        'Box photo could not be loaded.',
                        style: TextStyle(color: FarmColors.muted),
                      ),
                    );
                  },
                ),
              ),
              const SizedBox(height: 8),
              const Text(
                'Photo proof of your packed fresh box.',
                style: TextStyle(
                  color: FarmColors.muted,
                  fontSize: 12,
                  fontWeight: FontWeight.w600,
                ),
              ),
            ],
          ),
        );
      },
    );
  }

  Widget _trackingRow({
    required String label,
    required bool active,
    required bool complete,
  }) {
    final icon = complete ? Icons.check_circle : Icons.radio_button_unchecked;
    final color = complete || active ? FarmColors.green : FarmColors.mutedText;
    return Padding(
      padding: const EdgeInsets.only(bottom: 10),
      child: Row(
        children: [
          Icon(icon, color: color),
          const SizedBox(width: 10),
          Expanded(
            child: Text(
              label,
              style: TextStyle(
                fontWeight: active ? FontWeight.bold : FontWeight.normal,
                color: color,
              ),
            ),
          ),
        ],
      ),
    );
  }

  Future<void> _downloadCustomerReceiptPdf(dynamic order) async {
    String safeText(
      Object? Function() read, {
      String fallback = 'Not available',
    }) {
      try {
        final value = read();
        if (value == null) return fallback;

        final text = value.toString().trim();
        if (text.isEmpty || text == 'null') return fallback;

        return text;
      } catch (_) {
        return fallback;
      }
    }

    String titleCase(String value) {
      final clean = value.replaceAll('_', ' ').trim();
      if (clean.isEmpty) return value;

      return clean
          .split(' ')
          .where((part) => part.trim().isNotEmpty)
          .map((part) {
        final lower = part.toLowerCase();
        return '${lower[0].toUpperCase()}${lower.substring(1)}';
      }).join(' ');
    }

    List<dynamic> safeList(Object? Function() read) {
      try {
        final value = read();
        if (value is List) return value;
        return [];
      } catch (_) {
        return [];
      }
    }

    Object? readItemValue(dynamic item, String key) {
      try {
        if (item is Map) {
          return item[key];
        }

        switch (key) {
          case 'productName':
          case 'product_name':
            return item.productName;
          case 'name':
            return item.name;
          case 'quantity':
          case 'qty':
            return item.quantity;
          case 'formattedUnitPrice':
          case 'formatted_unit_price':
            return item.formattedUnitPrice;
          case 'unitPrice':
          case 'unit_price':
            return item.unitPrice;
          case 'price':
            return item.price;
          case 'formattedSubtotal':
          case 'formatted_subtotal':
            return item.formattedSubtotal;
          case 'subtotal':
          case 'line_total':
            return item.subtotal;
          case 'total':
            return item.total;
          default:
            return null;
        }
      } catch (_) {
        return null;
      }
    }

    String itemText(
      dynamic item,
      List<String> keys, {
      String fallback = '',
    }) {
      for (final key in keys) {
        final value = readItemValue(item, key);
        if (value != null && value.toString().trim().isNotEmpty) {
          return value.toString().trim();
        }
      }

      return fallback;
    }

    pw.Widget infoBox({
      required String title,
      required List<String> lines,
    }) {
      return pw.Container(
        padding: const pw.EdgeInsets.all(12),
        decoration: pw.BoxDecoration(
          border: pw.Border.all(color: PdfColor.fromInt(0xFFD8E8D8)),
          borderRadius: pw.BorderRadius.circular(10),
        ),
        child: pw.Column(
          crossAxisAlignment: pw.CrossAxisAlignment.start,
          children: [
            pw.Text(
              title,
              style: pw.TextStyle(
                fontSize: 12,
                fontWeight: pw.FontWeight.bold,
                color: PdfColor.fromInt(0xFF1F6B3A),
              ),
            ),
            pw.SizedBox(height: 8),
            ...lines.map(
              (line) => pw.Padding(
                padding: const pw.EdgeInsets.only(bottom: 4),
                child: pw.Text(
                  line,
                  style: const pw.TextStyle(fontSize: 10),
                ),
              ),
            ),
          ],
        ),
      );
    }

    pw.Widget amountRow(
      String label,
      String value, {
      bool bold = false,
      bool green = false,
    }) {
      return pw.Padding(
        padding: const pw.EdgeInsets.only(bottom: 6),
        child: pw.Row(
          mainAxisAlignment: pw.MainAxisAlignment.spaceBetween,
          children: [
            pw.Text(
              label,
              style: pw.TextStyle(
                fontSize: 10,
                fontWeight: bold ? pw.FontWeight.bold : pw.FontWeight.normal,
              ),
            ),
            pw.Text(
              value,
              style: pw.TextStyle(
                fontSize: bold ? 13 : 10,
                fontWeight: bold ? pw.FontWeight.bold : pw.FontWeight.normal,
                color: green ? PdfColor.fromInt(0xFF1F6B3A) : PdfColors.black,
              ),
            ),
          ],
        ),
      );
    }

    try {
      final companySettings = await fetchHpjCompanySettings();
      final receiptCompanyLine = <String>[
        companySettings.address.trim(),
        if (companySettings.supportPhone.trim().isNotEmpty)
          'Tel: ${companySettings.supportPhone.trim()}',
      ].where((value) => value.isNotEmpty).join(' | ');

      final pdf = pw.Document();
      String formatReceiptDate(String rawValue) {
        final cleanValue = rawValue.trim();

        if (cleanValue.isEmpty || cleanValue.toLowerCase() == 'not available') {
          return 'Not available';
        }

        final parsedDate = DateTime.tryParse(cleanValue);

        if (parsedDate == null) {
          return cleanValue;
        }

        const months = [
          'Jan',
          'Feb',
          'Mar',
          'Apr',
          'May',
          'Jun',
          'Jul',
          'Aug',
          'Sep',
          'Oct',
          'Nov',
          'Dec',
        ];

        final hour12 = parsedDate.hour % 12 == 0 ? 12 : parsedDate.hour % 12;

        final minute = parsedDate.minute.toString().padLeft(2, '0');

        final period = parsedDate.hour >= 12 ? 'PM' : 'AM';

        return '${months[parsedDate.month - 1]} '
            '${parsedDate.day}, '
            '${parsedDate.year} - '
            '$hour12:$minute $period';
      }

      pw.MemoryImage? receiptLogo;

      try {
        final logoData = await rootBundle.load('lib/assets/images/logo.png');

        receiptLogo = pw.MemoryImage(
          logoData.buffer.asUint8List(
            logoData.offsetInBytes,
            logoData.lengthInBytes,
          ),
        );
      } catch (_) {
        receiptLogo = null;
      }
      final receiptOrder = await supabase
          .from('orders')
          .select('*, customers(*)')
          .eq('id', widget.orderId)
          .maybeSingle();

      final receiptItems = await supabase
          .from('order_items')
          .select('*, products(*)')
          .eq('order_id', widget.orderId);

      final shortId = safeText(() => order.shortId, fallback: widget.orderId);
      final status = safeText(() => order.status, fallback: 'Pending');
      final paymentStatus =
          safeText(() => order.paymentStatus, fallback: 'Unpaid');
      final fulfillment = safeText(
        () => formatFulfillmentType(order.fulfillmentType),
        fallback: 'Farm Pickup',
      );
      final paymentMethod = safeText(
        () => order.formattedPaymentMethod,
        fallback: 'Payment on collection',
      );
      final total = safeText(() => order.formattedTotal, fallback: 'J\$0.00');
      final subtotal = safeText(() => order.formattedSubtotal, fallback: '');
      final deliveryFee =
          safeText(() => order.formattedDeliveryFee, fallback: '');
      final customer = receiptOrder?['customers'];

      String customerValue(List<String> keys,
          {String fallback = 'Not available'}) {
        try {
          for (final key in keys) {
            final orderValue = receiptOrder?[key];
            if (orderValue != null && orderValue.toString().trim().isNotEmpty) {
              return orderValue.toString().trim();
            }

            if (customer is Map) {
              final customerValue = customer[key];
              if (customerValue != null &&
                  customerValue.toString().trim().isNotEmpty) {
                return customerValue.toString().trim();
              }
            }
          }

          return fallback;
        } catch (_) {
          return fallback;
        }
      }

      final customerName = customerValue(
        [
          'customer_name',
          'full_name',
          'name',
          'display_name',
        ],
        fallback: 'Customer',
      );

      final customerPhone = customerValue(
        [
          'customer_phone',
          'phone',
          'phone_number',
        ],
        fallback: 'Not provided',
      );
      final createdAtRaw =
          safeText(() => order.createdAt, fallback: 'Not available');

      final createdAt = formatReceiptDate(createdAtRaw);
      final scheduledFor =
          safeText(() => order.scheduledFor, fallback: 'Not available');

      final items = receiptItems;

      pdf.addPage(
        pw.MultiPage(
          pageFormat: PdfPageFormat.a4,
          margin: const pw.EdgeInsets.all(34),
          build: (context) {
            return [
              pw.Column(
                crossAxisAlignment: pw.CrossAxisAlignment.start,
                children: [
                  // Company header
                  pw.Row(
                    crossAxisAlignment: pw.CrossAxisAlignment.center,
                    children: [
                      pw.SizedBox(
                        width: 72,
                        height: 72,
                        child: receiptLogo != null
                            ? pw.Image(
                                receiptLogo!,
                                fit: pw.BoxFit.contain,
                              )
                            : pw.Container(
                                alignment: pw.Alignment.center,
                                child: pw.Text(
                                  'HPJ',
                                  style: pw.TextStyle(
                                    fontSize: 20,
                                    fontWeight: pw.FontWeight.bold,
                                    color: PdfColor.fromInt(0xFF1F6B3A),
                                  ),
                                ),
                              ),
                      ),

                      pw.SizedBox(width: 12),

                      // Vertical divider
                      pw.Container(
                        width: 2,
                        height: 68,
                        color: PdfColor.fromInt(0xFF1F6B3A),
                      ),

                      pw.SizedBox(width: 14),

                      pw.Expanded(
                        child: pw.Column(
                          crossAxisAlignment: pw.CrossAxisAlignment.start,
                          mainAxisAlignment: pw.MainAxisAlignment.center,
                          children: [
                            pw.Text(
                              'THE HARVEST PLACE JA',
                              style: pw.TextStyle(
                                fontSize: 22,
                                fontWeight: pw.FontWeight.bold,
                                color: PdfColor.fromInt(0xFF124D32),
                              ),
                            ),
                            pw.SizedBox(height: 5),
                            pw.Text(
                              receiptCompanyLine,
                              style: pw.TextStyle(
                                fontSize: 10.5,
                                color: PdfColor.fromInt(0xFF4B5450),
                              ),
                            ),
                            pw.SizedBox(height: 4),
                            pw.Text(
                              'Fresh - Local - Jamaican',
                              style: pw.TextStyle(
                                fontSize: 9,
                                fontWeight: pw.FontWeight.bold,
                                color: PdfColor.fromInt(0xFF1F6B3A),
                              ),
                            ),
                          ],
                        ),
                      ),
                    ],
                  ),

                  pw.SizedBox(height: 10),

                  pw.Container(
                    width: double.infinity,
                    height: 2,
                    color: PdfColor.fromInt(0xFF1F6B3A),
                  ),

                  pw.SizedBox(height: 8),

                  pw.Row(
                    crossAxisAlignment: pw.CrossAxisAlignment.center,
                    children: [
                      pw.Expanded(
                        child: pw.Text(
                          'OFFICIAL CUSTOMER RECEIPT',
                          style: pw.TextStyle(
                            fontSize: 11,
                            fontWeight: pw.FontWeight.bold,
                            color: PdfColor.fromInt(0xFF1F6B3A),
                            letterSpacing: 0.3,
                          ),
                        ),
                      ),
                      pw.Text(
                        'Receipt #$shortId',
                        style: pw.TextStyle(
                          fontSize: 9.5,
                          fontWeight: pw.FontWeight.bold,
                          color: PdfColor.fromInt(0xFF33443A),
                        ),
                      ),
                    ],
                  ),

                  pw.SizedBox(height: 18),

                  // Receipt information
                  // Clean green divider
                ],
              ),
              pw.SizedBox(height: 20),
              pw.Row(
                crossAxisAlignment: pw.CrossAxisAlignment.start,
                children: [
                  pw.Expanded(
                    child: infoBox(
                      title: 'Customer Details',
                      lines: [
                        'Name: $customerName',
                        'Phone: $customerPhone',
                      ],
                    ),
                  ),
                  pw.SizedBox(width: 12),
                  pw.Expanded(
                    child: infoBox(
                      title: 'Order Details',
                      lines: [
                        'Order ID: $shortId',
                        'Order date: $createdAt',
                        'Scheduled: $scheduledFor',
                        'Fulfillment: $fulfillment',
                        'Payment method: $paymentMethod',
                      ],
                    ),
                  ),
                ],
              ),
              pw.SizedBox(height: 22),
              pw.Text(
                'Items Purchased',
                style: pw.TextStyle(
                  fontSize: 15,
                  fontWeight: pw.FontWeight.bold,
                  color: PdfColor.fromInt(0xFF1F6B3A),
                ),
              ),
              pw.SizedBox(height: 8),
              if (items.isEmpty)
                pw.Container(
                  width: double.infinity,
                  padding: const pw.EdgeInsets.all(12),
                  decoration: pw.BoxDecoration(
                    border: pw.Border.all(color: PdfColor.fromInt(0xFFD8E8D8)),
                    borderRadius: pw.BorderRadius.circular(8),
                  ),
                  child: pw.Text(
                    'Item details were not available for this receipt.',
                    style: const pw.TextStyle(fontSize: 10),
                  ),
                )
              else
                pw.TableHelper.fromTextArray(
                  headers: ['Item', 'Qty', 'Unit Price', 'Subtotal'],
                  data: items.map((item) {
                    final name = itemText(
                      item,
                      ['productName', 'product_name', 'name'],
                      fallback: 'Item',
                    );

                    final qty = itemText(
                      item,
                      ['quantity', 'qty'],
                      fallback: '1',
                    );

                    final unitPrice = itemText(
                      item,
                      [
                        'formattedUnitPrice',
                        'formatted_unit_price',
                        'unitPrice',
                        'unit_price',
                        'price',
                      ],
                      fallback: '',
                    );

                    final itemSubtotal = itemText(
                      item,
                      [
                        'formattedSubtotal',
                        'formatted_subtotal',
                        'subtotal',
                        'line_total',
                        'total',
                      ],
                      fallback: '',
                    );

                    return [name, qty, unitPrice, itemSubtotal];
                  }).toList(),
                  headerDecoration: pw.BoxDecoration(
                    color: PdfColor.fromInt(0xFF1F6B3A),
                  ),
                  headerStyle: pw.TextStyle(
                    color: PdfColors.white,
                    fontWeight: pw.FontWeight.bold,
                    fontSize: 10,
                  ),
                  cellStyle: const pw.TextStyle(fontSize: 10),
                  cellAlignment: pw.Alignment.centerLeft,
                  headerAlignment: pw.Alignment.centerLeft,
                  border: pw.TableBorder.all(
                    color: PdfColor.fromInt(0xFFD8E8D8),
                    width: 0.6,
                  ),
                  cellPadding: const pw.EdgeInsets.all(7),
                ),
              pw.SizedBox(height: 22),
              pw.Align(
                alignment: pw.Alignment.centerRight,
                child: pw.Container(
                  width: 245,
                  padding: const pw.EdgeInsets.all(14),
                  decoration: pw.BoxDecoration(
                    color: PdfColor.fromInt(0xFFF8FAF7),
                    borderRadius: pw.BorderRadius.circular(10),
                    border: pw.Border.all(
                      color: PdfColor.fromInt(0xFFD8E8D8),
                    ),
                  ),
                  child: pw.Column(
                    children: [
                      if (subtotal.isNotEmpty && subtotal != 'Not available')
                        amountRow('Subtotal', subtotal),
                      if (deliveryFee.isNotEmpty &&
                          deliveryFee != 'Not available')
                        amountRow('Delivery fee', deliveryFee),
                      pw.Divider(color: PdfColor.fromInt(0xFFD8E8D8)),
                      amountRow(
                        'Total',
                        total,
                        bold: true,
                        green: true,
                      ),
                    ],
                  ),
                ),
              ),
              pw.SizedBox(height: 28),
              pw.Container(
                width: double.infinity,
                padding: const pw.EdgeInsets.all(14),
                decoration: pw.BoxDecoration(
                  color: PdfColor.fromInt(0xFFFFFBF0),
                  borderRadius: pw.BorderRadius.circular(10),
                  border: pw.Border.all(
                    color: PdfColor.fromInt(0xFFE8D6A8),
                  ),
                ),
                child: pw.Column(
                  crossAxisAlignment: pw.CrossAxisAlignment.start,
                  children: [
                    pw.Text(
                      'Receipt Notes',
                      style: pw.TextStyle(
                        fontSize: 12,
                        fontWeight: pw.FontWeight.bold,
                        color: PdfColor.fromInt(0xFF1F6B3A),
                      ),
                    ),
                    pw.SizedBox(height: 6),
                    pw.Text(
                      'Please keep this receipt for your records. You can view your order status, staff messages, and box photo proof inside the app under My Orders.',
                      style: const pw.TextStyle(fontSize: 9),
                    ),
                  ],
                ),
              ),
              pw.SizedBox(height: 20),
              pw.Divider(color: PdfColor.fromInt(0xFFD8E8D8)),
              pw.Text(
                'Thank you for supporting local farmers through The Harvest Place Ja.',
                style: pw.TextStyle(
                  fontSize: 11,
                  fontWeight: pw.FontWeight.bold,
                  color: PdfColor.fromInt(0xFF1F6B3A),
                ),
              ),
              pw.SizedBox(height: 4),
              pw.Text(
                'Fresh produce. Local support. Better food for Jamaican families.',
                style: const pw.TextStyle(fontSize: 9),
              ),
            ];
          },
        ),
      );

      final cleanShortId = shortId.replaceAll(RegExp(r'[^A-Za-z0-9_-]'), '');

      await Printing.sharePdf(
        bytes: await pdf.save(),
        filename: 'HPJ-Receipt-$cleanShortId.pdf',
      );
    } catch (error) {
      if (!mounted) return;

      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text('Could not create receipt: $error'),
        ),
      );
    }
  }

  void _openMyOrdersRoot() {
    if (!mounted) return;

    Navigator.of(context).pushAndRemoveUntil<void>(
      MaterialPageRoute<void>(
        builder: (_) => const MainNavigation(
          initialIndex: 3,
        ),
      ),
      (route) => false,
    );
  }

  @override
  Widget build(BuildContext context) {
    final desktopWeb = HpjWebUi.isDesktop(context);

    if (!isLoggedIn) {
      return const GuestProtectedScreen(
        title: 'Order Details',
        subtitle: 'Private order information',
        message: 'Sign in to view private order details and tracking updates.',
      );
    }

    final scaffold = Scaffold(
      backgroundColor: FarmColors.background,
      appBar: AppBar(
        leading: widget.backToOrders
            ? IconButton(
                tooltip: 'Back to My Orders',
                onPressed: _openMyOrdersRoot,
                icon: const Icon(Icons.arrow_back_rounded),
              )
            : const BackButton(),
        title: Text(
          desktopWeb ? 'Order Tracking' : 'Order Details',
        ),
        backgroundColor: FarmColors.background,
        actions: [
          IconButton(
            tooltip: 'Refresh order',
            onPressed: () => unawaited(_refreshOrderDetails()),
            icon: const Icon(Icons.refresh_rounded),
          ),
          const SizedBox(width: 4),
        ],
      ),
      body: RefreshIndicator(
        onRefresh: _refreshOrderDetails,
        child: FutureBuilder<OrderDetails?>(
          future: _orderFuture,
          builder: (context, snapshot) {
            if (snapshot.connectionState == ConnectionState.waiting &&
                !snapshot.hasData) {
              return const SkeletonList();
            }

            final order = snapshot.data;
            if (order == null) {
              return ListView(
                physics: const AlwaysScrollableScrollPhysics(),
                padding: const EdgeInsets.fromLTRB(18, 18, 18, 120),
                children: [
                  Container(
                    width: double.infinity,
                    padding: const EdgeInsets.fromLTRB(20, 26, 20, 24),
                    decoration: BoxDecoration(
                      color: FarmColors.card,
                      borderRadius: BorderRadius.circular(26),
                      border: Border.all(color: FarmColors.line),
                    ),
                    child: Column(
                      children: [
                        Container(
                          width: 62,
                          height: 62,
                          decoration: const BoxDecoration(
                            color: FarmColors.primarySoft,
                            shape: BoxShape.circle,
                          ),
                          child: const Icon(
                            Icons.search_off_rounded,
                            color: FarmColors.green,
                            size: 29,
                          ),
                        ),
                        const SizedBox(height: 14),
                        const Text(
                          'Order unavailable',
                          style: TextStyle(
                            color: FarmColors.ink,
                            fontSize: 18,
                            fontWeight: FontWeight.w900,
                          ),
                        ),
                        const SizedBox(height: 6),
                        const Text(
                          'HPJ could not open this order right now. Retry the lookup or return to My Orders.',
                          textAlign: TextAlign.center,
                          style: TextStyle(
                            color: FarmColors.mutedText,
                            height: 1.4,
                            fontWeight: FontWeight.w600,
                          ),
                        ),
                      ],
                    ),
                  ),
                  const SizedBox(height: 14),
                  SizedBox(
                    width: double.infinity,
                    child: ElevatedButton.icon(
                      onPressed: () => unawaited(_refreshOrderDetails()),
                      icon: const Icon(Icons.refresh_rounded),
                      label: const Text('Try Again'),
                    ),
                  ),
                  const SizedBox(height: 8),
                  SizedBox(
                    width: double.infinity,
                    child: OutlinedButton.icon(
                      onPressed: _openMyOrdersRoot,
                      icon: const Icon(Icons.receipt_long_outlined),
                      label: const Text('Back to My Orders'),
                    ),
                  ),
                ],
              );
            }

            final isDelivery = order.fulfillmentType == 'delivery';
            final status = order.status.trim().toLowerCase();
            final canReorder = (status == 'completed' || status == 'delivered') &&
                widget.onAddToCart != null;
            final bottomSafePadding = MediaQuery.of(context).viewPadding.bottom;

            return ListView(
              physics: const AlwaysScrollableScrollPhysics(),
              padding: EdgeInsets.fromLTRB(
                desktopWeb ? 22 : 18,
                desktopWeb ? 18 : 12,
                desktopWeb ? 22 : 18,
                62 + bottomSafePadding,
              ),
              children: [
                if (desktopWeb)
                  _PremiumWebOrderTrackingHero(
                    shortId: order.shortId,
                    statusLabel:
                        _prettyOrderValue(order.status),
                    total: order.formattedTotal,
                    fulfillmentLabel:
                        formatFulfillmentType(
                      order.fulfillmentType,
                    ),
                    paymentMethod:
                        order.formattedPaymentMethod,
                    paymentStatus:
                        _prettyOrderValue(
                      order.paymentStatus,
                    ),
                    itemCount: order.items.length,
                    isDelivery: isDelivery,
                  )
                else
                  _premiumOrderDetailHero(order),
                const SizedBox(height: 16),
                EliteOrderStatusCard(order: order),
                const SizedBox(height: 14),
                PremiumOrderTracker(
                  status: order.status,
                  isDelivery: isDelivery,
                  paymentStatus: order.paymentStatus,
                ),
                const SizedBox(height: 14),
                EliteOrderQuickActions(
                  order: order,
                  onRefresh: _refreshOrderDetails,
                ),
                const SizedBox(height: 12),
                if (canReorder) ...[
                  SizedBox(
                    width: double.infinity,
                    child: ElevatedButton.icon(
                      icon: _loadingReorder
                          ? const SizedBox(
                              width: 18,
                              height: 18,
                              child: CircularProgressIndicator(strokeWidth: 2),
                            )
                          : const Icon(Icons.replay_rounded),
                      label: Text(
                        _loadingReorder
                            ? 'Checking Products...'
                            : 'Reorder This Order',
                      ),
                      onPressed: _loadingReorder
                          ? null
                          : () => _openReorderPreview(order),
                    ),
                  ),
                  const SizedBox(height: 10),
                ],
                Row(
                  children: [
                    Expanded(
                      child: OutlinedButton.icon(
                        icon: const Icon(Icons.picture_as_pdf_outlined),
                        label: const Text('Receipt'),
                        onPressed: () => _downloadCustomerReceiptPdf(order),
                      ),
                    ),
                    const SizedBox(width: 10),
                    Expanded(
                      child: FilledButton.tonalIcon(
                        onPressed: () {
                          Navigator.of(context).push(
                            MaterialPageRoute<void>(
                              builder: (_) => SupportScreen(
                                initialSubject: 'Order #${order.shortId}',
                              ),
                            ),
                          );
                        },
                        icon: const Icon(Icons.chat_bubble_outline_rounded),
                        label: const Text('Message HPJ'),
                      ),
                    ),
                  ],
                ),
                const SizedBox(height: 14),
                _premiumSupportCard(order),
                const SizedBox(height: 14),
                _customerBoxPhotoCard(),
                const SizedBox(height: 12),
                CustomerOrderUpdatesCard(orderId: widget.orderId),
                const SizedBox(height: 14),
                HpjOrderFarmPassportCard(orderId: widget.orderId),
                const SizedBox(height: 14),
                _premiumOrderItemsCard(
                  order,
                  isDelivery: isDelivery,
                ),
                if ((order.notes ?? '').isNotEmpty) ...[
                  const SizedBox(height: 14),
                  Container(
                    width: double.infinity,
                    padding: const EdgeInsets.all(16),
                    decoration: BoxDecoration(
                      color: const Color(0xFFFFFBF1),
                      borderRadius: BorderRadius.circular(22),
                      border: Border.all(color: const Color(0xFFE8D9B5)),
                    ),
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        const Row(
                          children: [
                            Icon(
                              Icons.sticky_note_2_outlined,
                              color: Color(0xFF805512),
                              size: 20,
                            ),
                            SizedBox(width: 8),
                            Text(
                              'Order notes',
                              style: TextStyle(
                                color: FarmColors.ink,
                                fontSize: 16,
                                fontWeight: FontWeight.w900,
                              ),
                            ),
                          ],
                        ),
                        const SizedBox(height: 9),
                        Text(
                          order.notes!,
                          style: const TextStyle(
                            color: FarmColors.ink,
                            height: 1.4,
                            fontWeight: FontWeight.w600,
                          ),
                        ),
                      ],
                    ),
                  ),
                ],
              ],
            );
          },
        ),
      ),
    );

    if (!widget.backToOrders) {
      return scaffold;
    }

    return PopScope(
      canPop: false,
      onPopInvokedWithResult: (didPop, result) {
        if (didPop) return;
        _openMyOrdersRoot();
      },
      child: scaffold,
    );
  }

}

