class ProductCollectionScreen extends StatelessWidget {
  final String title;
  final String subtitle;
  final List<Product> products;
  final String emptyText;
  final VoidCallback onShopTap;

  const ProductCollectionScreen({
    super.key,
    required this.title,
    required this.subtitle,
    required this.products,
    required this.emptyText,
    required this.onShopTap,
  });

  @override
  Widget build(BuildContext context) {
    final isFavorites = title.toLowerCase().contains('favorite');
    final desktopWeb = HpjWebUi.isDesktop(context);

    return Scaffold(
      backgroundColor: FarmColors.background,
      appBar: AppBar(
        leading: const BackButton(),
        title: Text(title),
        backgroundColor: FarmColors.background,
      ),
      body: FarmPage(
        child: ListView(
          physics: const AlwaysScrollableScrollPhysics(),
          padding: EdgeInsets.fromLTRB(
            desktopWeb ? 22 : 18,
            18,
            desktopWeb ? 22 : 18,
            120,
          ),
          children: [
            if (desktopWeb)
              _PremiumWebSavedCollectionHero(
                title: title,
                subtitle: subtitle,
                count: products.length,
                isFavorites: isFavorites,
              )
            else
              _PremiumSavedCollectionHero(
                title: title,
                subtitle: subtitle,
                count: products.length,
                isFavorites: isFavorites,
              ),
            const SizedBox(height: 18),
            if (products.isEmpty)
              FarmEmptyState(
                icon: isFavorites
                    ? Icons.favorite_border_rounded
                    : Icons.history_rounded,
                title: isFavorites ? 'No favorites yet' : 'Nothing viewed yet',
                message: emptyText,
                actionLabel: 'Explore the Shop',
                actionIcon: Icons.storefront_outlined,
                onAction: () {
                  Navigator.pop(context);
                  onShopTap();
                },
              )
            else ...[
              Row(
                children: [
                  Expanded(
                    child: Text(
                      isFavorites ? 'Saved for later' : 'Your recent discoveries',
                      style: const TextStyle(
                        color: FarmColors.deepGreen,
                        fontSize: 20,
                        fontWeight: FontWeight.w900,
                        letterSpacing: -0.3,
                      ),
                    ),
                  ),
                  TextButton.icon(
                    onPressed: () {
                      Navigator.pop(context);
                      onShopTap();
                    },
                    icon: const Icon(Icons.storefront_outlined, size: 18),
                    label: const Text('Shop'),
                  ),
                ],
              ),
              const SizedBox(height: 10),
              LayoutBuilder(
                builder: (context, constraints) {
                  final columns = desktopWeb &&
                          constraints.maxWidth >= 1050
                      ? 3
                      : constraints.maxWidth >= 720
                          ? 2
                          : 1;
                  const gap = 12.0;
                  final cardWidth =
                      (constraints.maxWidth -
                              gap * (columns - 1)) /
                          columns;
                  return Wrap(
                    spacing: 12,
                    runSpacing: 12,
                    children: products
                        .map(
                          (product) => SizedBox(
                            width: cardWidth,
                            child: _PremiumSavedProductCard(product: product),
                          ),
                        )
                        .toList(),
                  );
                },
              ),
            ],
          ],
        ),
      ),
    );
  }
}

