class FarmNotificationButton extends StatelessWidget {
  final double size;
  final bool showBadge;
  final Color badgeColor;

  const FarmNotificationButton({
    super.key,
    this.size = 38,
    this.showBadge = true,
    this.badgeColor = FarmColors.danger,
  });

  @override
  Widget build(BuildContext context) {
    return FutureBuilder<int>(
      future: showBadge ? fetchUnreadNotificationCount() : null,
      builder: (context, snapshot) {
        final count = snapshot.data ?? 0;
        return Container(
          height: size,
          width: size,
          decoration: BoxDecoration(
            color: Colors.white,
            shape: BoxShape.circle,
            border: Border.all(color: FarmColors.line),
            boxShadow: [
              BoxShadow(
                color: FarmColors.shadow.withOpacity(0.07),
                blurRadius: 14,
                offset: const Offset(0, 6),
              ),
            ],
          ),
          child: Stack(
            clipBehavior: Clip.none,
            children: [
              Positioned.fill(
                child: IconButton(
                  padding: EdgeInsets.zero,
                  tooltip: 'Notifications',
                  onPressed: () {
                    Navigator.of(context).push(
                      MaterialPageRoute(
                        builder: (_) => const NotificationsScreen(),
                      ),
                    );
                  },
                  icon: const Icon(
                    Icons.notifications_none_rounded,
                    color: FarmColors.deepGreen,
                    size: 20,
                  ),
                ),
              ),
              if (showBadge && count > 0)
                Positioned(
                  right: -1,
                  top: -2,
                  child: Container(
                    padding: const EdgeInsets.symmetric(
                      horizontal: 5,
                      vertical: 2,
                    ),
                    decoration: BoxDecoration(
                      color: badgeColor,
                      borderRadius: BorderRadius.circular(999),
                      border: Border.all(color: Colors.white, width: 1.5),
                    ),
                    constraints: const BoxConstraints(minWidth: 18),
                    child: Text(
                      count > 99 ? '99+' : '$count',
                      textAlign: TextAlign.center,
                      style: const TextStyle(
                        color: Colors.white,
                        fontSize: 9,
                        height: 1,
                        fontWeight: FontWeight.w900,
                      ),
                    ),
                  ),
                ),
            ],
          ),
        );
      },
    );
  }
}

