class ReviewScreen extends StatefulWidget {
  const ReviewScreen({super.key});

  @override
  State<ReviewScreen> createState() => _ReviewScreenState();
}

class _ReviewScreenState extends State<ReviewScreen> {
  Product? selectedProduct;
  int rating = 5;
  final commentController = TextEditingController();
  bool sending = false;
  int refreshKey = 0;

  @override
  void dispose() {
    commentController.dispose();
    super.dispose();
  }

  void usePrompt(String text) {
    final clean = text.trim();
    if (clean.isEmpty) return;
    final current = commentController.text.trim();
    commentController.text = current.isEmpty ? clean : '$current $clean';
    commentController.selection = TextSelection.fromPosition(
      TextPosition(offset: commentController.text.length),
    );
  }

  Future<void> submitReview() async {
    final product = selectedProduct;
    final comment = commentController.text.trim();

    if (product == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Choose the product you want to review.')),
      );
      return;
    }

    if (comment.length < 8) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Add a little more detail so your review is useful.'),
        ),
      );
      return;
    }

    setState(() => sending = true);
    try {
      await createProductReview(
        productId: product.id,
        productName: product.name,
        rating: rating,
        comment: comment,
      );
      commentController.clear();
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('Thanks — your review was shared.')),
        );
        setState(() {
          selectedProduct = null;
          rating = 5;
          refreshKey++;
        });
      }
    } catch (error) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
              content:
                  Text('Could not save review: ${friendlyAppError(error)}')),
        );
      }
    } finally {
      if (mounted) setState(() => sending = false);
    }
  }

  Product? selectedProductFrom(List<Product> products) {
    final id = selectedProduct?.id.trim() ?? '';
    if (id.isEmpty) return null;
    for (final product in products) {
      if (product.id == id) return product;
    }
    return null;
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: FarmColors.background,
      appBar: AppBar(
        leading: const BackButton(),
        title: const Text('Reviews'),
        backgroundColor: FarmColors.background,
      ),
      body: FarmPage(
        child: RefreshIndicator(
          onRefresh: () async {
            setState(() => refreshKey++);
            await fetchProductReviews();
          },
          child: ListView(
            physics: const AlwaysScrollableScrollPhysics(),
            padding: const EdgeInsets.fromLTRB(18, 18, 18, 120),
            children: [
              const ReviewHeroCard(),
              const SizedBox(height: 16),
              FarmCard(
                padding: const EdgeInsets.all(18),
                child: FutureBuilder<List<Product>>(
                  future: fetchReviewEligibleProducts(),
                  builder: (context, snapshot) {
                    final products = (snapshot.data ?? const <Product>[])
                        .where((product) => product.isCustomerVisible)
                        .toList()
                      ..sort((a, b) => a.name.compareTo(b.name));
                    final selected = selectedProductFrom(products);

                    return Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        const Text(
                          'Share your experience',
                          style: TextStyle(
                            fontSize: 20,
                            fontWeight: FontWeight.w900,
                            letterSpacing: -0.3,
                          ),
                        ),
                        const SizedBox(height: 5),
                        Text(
                          products.isEmpty
                              ? 'Complete an HPJ order before sharing a product review.'
                              : 'Only products from your paid, completed HPJ orders appear here.',
                          style: TextStyle(
                            color: FarmColors.mutedText,
                            height: 1.35,
                            fontWeight: FontWeight.w600,
                          ),
                        ),
                        const SizedBox(height: 16),
                        DropdownButtonFormField<Product>(
                          value: selected,
                          isExpanded: true,
                          decoration: InputDecoration(
                            labelText: 'Product you tried',
                            hintText: products.isEmpty
                                ? 'No completed-order products yet'
                                : 'Choose a purchased product',
                            prefixIcon:
                                const Icon(Icons.shopping_basket_outlined),
                          ),
                          items: products.map((product) {
                            return DropdownMenuItem<Product>(
                              value: product,
                              child: Text(
                                product.name,
                                maxLines: 1,
                                overflow: TextOverflow.ellipsis,
                              ),
                            );
                          }).toList(),
                          onChanged: products.isEmpty
                              ? null
                              : (Product? product) {
                                  if (product == null) return;
                                  setState(
                                    () => selectedProduct = product,
                                  );
                                },
                        ),
                        const SizedBox(height: 16),
                        ReviewRatingSelector(
                          value: rating,
                          onChanged: (value) => setState(() => rating = value),
                        ),
                        const SizedBox(height: 14),
                        Wrap(
                          spacing: 8,
                          runSpacing: 8,
                          children: [
                            ReviewPromptChip(
                              label: 'Fresh quality',
                              onTap: () =>
                                  usePrompt('The freshness was great.'),
                            ),
                            ReviewPromptChip(
                              label: 'Easy pickup',
                              onTap: () =>
                                  usePrompt('Pickup was easy and smooth.'),
                            ),
                            ReviewPromptChip(
                              label: 'Good value',
                              onTap: () =>
                                  usePrompt('Good value for the quality.'),
                            ),
                          ],
                        ),
                        const SizedBox(height: 14),
                        TextField(
                          controller: commentController,
                          maxLines: 4,
                          textInputAction: TextInputAction.newline,
                          decoration: const InputDecoration(
                            labelText: 'What should other customers know?',
                            hintText:
                                'Example: Fresh, well packed, and perfect for dinner.',
                            prefixIcon: Icon(Icons.rate_review_outlined),
                          ),
                        ),
                        const SizedBox(height: 16),
                        PrimaryFarmButton(
                          label: sending ? 'Sharing review...' : 'Share Review',
                          icon: Icons.send_rounded,
                          onPressed: sending ? null : submitReview,
                        ),
                      ],
                    );
                  },
                ),
              ),
              const SizedBox(height: 20),
              Row(
                children: [
                  const Expanded(
                    child: SectionTitle('Customer Reviews'),
                  ),
                  TextButton.icon(
                    onPressed: () async {
                      final reviews = await fetchProductReviews();
                      final summary = reviews.isEmpty
                          ? 'No customer reviews yet.'
                          : '${reviews.length} reviews • ${(reviews.fold<double>(0, (sum, review) => sum + review.rating) / reviews.length).toStringAsFixed(1)} average rating';
                      await Clipboard.setData(ClipboardData(text: summary));
                      if (context.mounted) {
                        ScaffoldMessenger.of(context).showSnackBar(
                          const SnackBar(
                              content: Text('Review summary copied.')),
                        );
                      }
                    },
                    icon: const Icon(Icons.copy_rounded, size: 17),
                    label: const Text('Copy'),
                  ),
                ],
              ),
              const SizedBox(height: 12),
              ReviewsList(refreshKey: refreshKey),
            ],
          ),
        ),
      ),
    );
  }
}

