class WeeklyBoxBuilderScreen extends StatefulWidget {
  const WeeklyBoxBuilderScreen({super.key});

  @override
  State<WeeklyBoxBuilderScreen> createState() => _WeeklyBoxBuilderScreenState();
}

class _WeeklyBoxBuilderScreenState extends State<WeeklyBoxBuilderScreen> {
  late Future<List<Product>> productsFuture;
  final Set<String> selectedIds = <String>{};
  int intervalDays = 7;
  bool saving = false;

  @override
  void initState() {
    super.initState();
    productsFuture = fetchProducts(forceRefresh: true);
  }

  void toggleProduct(Product product) {
    if (!canAddToWeeklyBox(product)) return;
    final id = product.id.trim();
    if (id.isEmpty) return;

    setState(() {
      if (!selectedIds.add(id)) {
        selectedIds.remove(id);
      }
    });
  }

  Future<void> saveBox(List<Product> products) async {
    if (saving) return;

    final selectedProducts = products
        .where((product) => selectedIds.contains(product.id))
        .where(canAddToWeeklyBox)
        .toList();

    if (selectedProducts.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Choose at least one available item.')),
      );
      return;
    }

    setState(() => saving = true);
    try {
      final count = await saveWeeklyBoxPlanProducts(
        products: selectedProducts,
        intervalDays: intervalDays,
      );
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
            content: Text(
                'Weekly Box saved with $count item${count == 1 ? '' : 's'}.')),
      );
      Navigator.pop(context, true);
    } catch (error) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(friendlyAppError(error))),
      );
    } finally {
      if (mounted) setState(() => saving = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: FarmColors.background,
      appBar: AppBar(
        leading: const BackButton(),
        title: const Text('Build Weekly Box'),
        backgroundColor: FarmColors.background,
      ),
      body: SafeArea(
        top: false,
        child: FutureBuilder<List<Product>>(
          future: productsFuture,
          builder: (context, snapshot) {
            final products = (snapshot.data ?? const <Product>[])
                .where(canAddToWeeklyBox)
                .toList();

            if (snapshot.connectionState == ConnectionState.waiting) {
              return SkeletonList(count: 4, height: 132);
            }

            if (products.isEmpty) {
              return ListView(
                physics: const AlwaysScrollableScrollPhysics(),
                padding: const EdgeInsets.fromLTRB(18, 18, 18, 140),
                children: const [
                  FarmCard(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Icon(Icons.inventory_2_outlined,
                            size: 42, color: FarmColors.green),
                        SizedBox(height: 12),
                        Text(
                          'No items ready for a Weekly Box',
                          style: TextStyle(
                            fontSize: 22,
                            fontWeight: FontWeight.w900,
                          ),
                        ),
                        SizedBox(height: 6),
                        Text(
                          'Add available products in Admin first, then customers can build their weekly repeat box here.',
                          style: TextStyle(
                            color: FarmColors.mutedText,
                            height: 1.35,
                            fontWeight: FontWeight.w700,
                          ),
                        ),
                      ],
                    ),
                  ),
                ],
              );
            }

            return Column(
              children: [
                Expanded(
                  child: ListView(
                    physics: const AlwaysScrollableScrollPhysics(),
                    padding: const EdgeInsets.fromLTRB(18, 18, 18, 18),
                    children: [
                      FarmCard(
                        color: FarmColors.successSoft,
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Row(
                              children: [
                                Container(
                                  height: 44,
                                  width: 44,
                                  decoration: BoxDecoration(
                                    color: Colors.white,
                                    borderRadius: BorderRadius.circular(16),
                                  ),
                                  child: const Icon(
                                    Icons.inventory_2_outlined,
                                    color: FarmColors.green,
                                  ),
                                ),
                                const SizedBox(width: 12),
                                const Expanded(
                                  child: Column(
                                    crossAxisAlignment:
                                        CrossAxisAlignment.start,
                                    children: [
                                      Text(
                                        'Make your weekly box',
                                        style: TextStyle(
                                          color: FarmColors.ink,
                                          fontSize: 20,
                                          fontWeight: FontWeight.w900,
                                        ),
                                      ),
                                      SizedBox(height: 4),
                                      Text(
                                        'Pick the items you want repeated. You still confirm before each order.',
                                        style: TextStyle(
                                          color: FarmColors.mutedText,
                                          fontWeight: FontWeight.w700,
                                          height: 1.25,
                                        ),
                                      ),
                                    ],
                                  ),
                                ),
                              ],
                            ),
                            const SizedBox(height: 14),
                            DropdownButtonFormField<int>(
                              value: intervalDays,
                              decoration: const InputDecoration(
                                labelText: 'Repeat reminder',
                              ),
                              items: const [
                                DropdownMenuItem(
                                    value: 7, child: Text('Every week')),
                                DropdownMenuItem(
                                    value: 14, child: Text('Every 2 weeks')),
                                DropdownMenuItem(
                                    value: 30, child: Text('Every month')),
                              ],
                              onChanged: saving
                                  ? null
                                  : (value) =>
                                      setState(() => intervalDays = value ?? 7),
                            ),
                          ],
                        ),
                      ),
                      const SizedBox(height: 16),
                      const Text(
                        'Today’s Fresh Harvest',
                        style: TextStyle(
                          fontSize: 20,
                          fontWeight: FontWeight.w900,
                          letterSpacing: -0.4,
                          color: FarmColors.primaryDark,
                        ),
                      ),
                      const SizedBox(height: 5),
                      const Text(
                        'Choose your favourites and build your box.',
                        style: TextStyle(
                          color: FarmColors.mutedText,
                          fontSize: 12.5,
                          height: 1.25,
                          fontWeight: FontWeight.w700,
                        ),
                      ),
                      const SizedBox(height: 12),
                      GridView.builder(
                        shrinkWrap: true,
                        physics: const NeverScrollableScrollPhysics(),
                        itemCount: products.length,
                        gridDelegate:
                            const SliverGridDelegateWithFixedCrossAxisCount(
                          crossAxisCount: 2,
                          mainAxisSpacing: 12,
                          crossAxisSpacing: 12,
                          childAspectRatio: 0.74,
                        ),
                        itemBuilder: (context, index) {
                          final product = products[index];
                          final selected = selectedIds.contains(product.id);
                          return _WeeklyBoxProductTile(
                            product: product,
                            selected: selected,
                            onTap: () => toggleProduct(product),
                          );
                        },
                      ),
                      const SizedBox(height: 110),
                    ],
                  ),
                ),
              ],
            );
          },
        ),
      ),
      bottomNavigationBar: SafeArea(
        top: false,
        child: FutureBuilder<List<Product>>(
          future: productsFuture,
          builder: (context, snapshot) {
            final products = snapshot.data ?? const <Product>[];
            final selectedProducts = products
                .where((product) => selectedIds.contains(product.id))
                .where(canAddToWeeklyBox)
                .toList();
            final selectedTotal = selectedProducts.fold<double>(
              0,
              (sum, product) => sum + product.effectivePrice,
            );

            return Container(
              padding: const EdgeInsets.fromLTRB(18, 12, 18, 14),
              decoration: const BoxDecoration(
                color: FarmColors.card,
                border: Border(top: BorderSide(color: FarmColors.line)),
              ),
              child: Row(
                children: [
                  Expanded(
                    child: Column(
                      mainAxisSize: MainAxisSize.min,
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(
                          '${selectedProducts.length} selected',
                          style: const TextStyle(
                            color: FarmColors.mutedText,
                            fontWeight: FontWeight.w800,
                          ),
                        ),
                        Text(
                          formatJmd(selectedTotal),
                          style: const TextStyle(
                            color: FarmColors.green,
                            fontSize: 20,
                            fontWeight: FontWeight.w900,
                          ),
                        ),
                      ],
                    ),
                  ),
                  ElevatedButton.icon(
                    onPressed: saving || selectedProducts.isEmpty
                        ? null
                        : () => saveBox(products),
                    icon: saving
                        ? const SizedBox(
                            height: 16,
                            width: 16,
                            child: CircularProgressIndicator(strokeWidth: 2),
                          )
                        : const Icon(Icons.check_circle_outline),
                    label: Text(saving ? 'Saving' : 'Save Box'),
                  ),
                ],
              ),
            );
          },
        ),
      ),
    );
  }
}

class _WeeklyBoxProductTile extends StatelessWidget {
  final Product product;
  final bool selected;
  final VoidCallback onTap;

  const _WeeklyBoxProductTile({
    required this.product,
    required this.selected,
    required this.onTap,
  });

  @override
  Widget build(BuildContext context) {
    final discount = weeklyBoxDiscountForProduct(product);

    return Material(
      color: Colors.transparent,
      child: InkWell(
        borderRadius: BorderRadius.circular(24),
        onTap: onTap,
        child: AnimatedContainer(
          duration: const Duration(milliseconds: 180),
          padding: const EdgeInsets.all(12),
          decoration: BoxDecoration(
            color: selected ? FarmColors.successSoft : FarmColors.card,
            borderRadius: BorderRadius.circular(24),
            border: Border.all(
              color: selected
                  ? FarmColors.green.withOpacity(0.55)
                  : FarmColors.line,
              width: selected ? 1.6 : 1,
            ),
            boxShadow: [
              BoxShadow(
                color: FarmColors.shadow.withOpacity(selected ? 0.10 : 0.045),
                blurRadius: selected ? 18 : 12,
                offset: const Offset(0, 8),
              ),
            ],
          ),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Row(
                children: [
                  Container(
                    height: 28,
                    width: 28,
                    decoration: BoxDecoration(
                      color:
                          selected ? FarmColors.green : FarmColors.lightGreen,
                      shape: BoxShape.circle,
                    ),
                    child: Icon(
                      selected ? Icons.check_rounded : Icons.add_rounded,
                      size: 18,
                      color: selected ? Colors.white : FarmColors.green,
                    ),
                  ),
                  const Spacer(),
                  if (discount > 0)
                    Container(
                      padding: const EdgeInsets.symmetric(
                        horizontal: 8,
                        vertical: 4,
                      ),
                      decoration: BoxDecoration(
                        color: FarmColors.accentSoft,
                        borderRadius: BorderRadius.circular(999),
                      ),
                      child: Text(
                        '${discount.toStringAsFixed(0)}% save',
                        style: const TextStyle(
                          color: FarmColors.warning,
                          fontSize: 10,
                          fontWeight: FontWeight.w900,
                        ),
                      ),
                    ),
                ],
              ),
              const SizedBox(height: 8),
              Center(child: ProductVisual(product: product, size: 76)),
              const SizedBox(height: 8),
              Text(
                product.name,
                maxLines: 2,
                overflow: TextOverflow.ellipsis,
                style: const TextStyle(
                  fontSize: 14,
                  fontWeight: FontWeight.w900,
                ),
              ),
              const SizedBox(height: 4),
              Text(
                product.formattedEffectivePrice,
                style: const TextStyle(
                  color: FarmColors.green,
                  fontSize: 15,
                  fontWeight: FontWeight.w900,
                ),
              ),
              const SizedBox(height: 4),
              Text(
                product.unit?.trim().isNotEmpty == true
                    ? product.unit!.trim()
                    : product.category,
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
                style: const TextStyle(
                  color: FarmColors.mutedText,
                  fontSize: 11,
                  fontWeight: FontWeight.w800,
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

class CustomerSubscriptionsScreen extends StatefulWidget {
  const CustomerSubscriptionsScreen({super.key});

  @override
  State<CustomerSubscriptionsScreen> createState() =>
      _CustomerSubscriptionsScreenState();
}

class _CustomerSubscriptionsScreenState
    extends State<CustomerSubscriptionsScreen> {
  late Future<List<CustomerProductSubscription>> plansFuture;

  @override
  void initState() {
    super.initState();
    plansFuture = fetchCustomerProductSubscriptions();
  }

  Future<void> refreshPlans() async {
    final future = fetchCustomerProductSubscriptions();
    if (mounted) {
      setState(() {
        plansFuture = future;
      });
    }
    await future;
  }

  Future<void> openWeeklyBoxBuilder() async {
    final changed = await Navigator.push<bool>(
      context,
      MaterialPageRoute(builder: (_) => const WeeklyBoxBuilderScreen()),
    );

    if (changed == true) {
      await refreshPlans();
    }
  }

  Widget buildWeeklyBoxBuilderCard({required bool hasPlans}) {
    return Container(
      padding: const EdgeInsets.all(20),
      decoration: BoxDecoration(
        borderRadius: BorderRadius.circular(30),
        gradient: const LinearGradient(
          begin: Alignment.topLeft,
          end: Alignment.bottomRight,
          colors: [Color(0xFF153F2D), Color(0xFF397A4E)],
        ),
        boxShadow: [
          BoxShadow(
            color: FarmColors.shadow.withOpacity(0.18),
            blurRadius: 26,
            offset: const Offset(0, 12),
          ),
        ],
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Container(
                height: 54,
                width: 54,
                decoration: BoxDecoration(
                  color: Colors.white.withOpacity(0.13),
                  borderRadius: BorderRadius.circular(19),
                  border: Border.all(color: Colors.white.withOpacity(0.18)),
                ),
                child: const Icon(
                  Icons.inventory_2_outlined,
                  color: Color(0xFFFFD98A),
                  size: 27,
                ),
              ),
              const SizedBox(width: 13),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      hasPlans ? 'Your Weekly Box' : 'Build your Weekly Box',
                      style: const TextStyle(
                        color: Colors.white,
                        fontSize: 22,
                        fontWeight: FontWeight.w900,
                        letterSpacing: -0.4,
                      ),
                    ),
                    const SizedBox(height: 4),
                    Text(
                      'Fresh favourites on your schedule, with a reminder before every repeat order.',
                      style: TextStyle(
                        color: Colors.white.withOpacity(0.80),
                        height: 1.32,
                        fontWeight: FontWeight.w600,
                      ),
                    ),
                  ],
                ),
              ),
            ],
          ),
          const SizedBox(height: 16),
          Wrap(
            spacing: 8,
            runSpacing: 8,
            children: const [
              _PremiumWeeklyBoxBadge(icon: Icons.event_repeat_outlined, label: 'Flexible'),
              _PremiumWeeklyBoxBadge(icon: Icons.notifications_none_rounded, label: 'Reminder first'),
              _PremiumWeeklyBoxBadge(icon: Icons.savings_outlined, label: 'Save on repeats'),
            ],
          ),
          const SizedBox(height: 17),
          SizedBox(
            width: double.infinity,
            child: ElevatedButton.icon(
              onPressed: openWeeklyBoxBuilder,
              style: ElevatedButton.styleFrom(
                backgroundColor: const Color(0xFFFFF4D8),
                foregroundColor: FarmColors.deepGreen,
                elevation: 0,
                padding: const EdgeInsets.symmetric(vertical: 14),
                shape: RoundedRectangleBorder(
                  borderRadius: BorderRadius.circular(18),
                ),
              ),
              icon: Icon(hasPlans ? Icons.edit_outlined : Icons.add_shopping_cart_outlined),
              label: Text(hasPlans ? 'Edit Weekly Box' : 'Start Weekly Box'),
            ),
          ),
        ],
      ),
    );
  }

  Future<void> updateStatus(
    CustomerProductSubscription plan,
    String status,
  ) async {
    try {
      await updateCustomerSubscriptionStatus(
          subscription: plan, status: status);
      await refreshPlans();
      if (!mounted) return;
      final label = status == 'cancelled'
          ? 'cancelled'
          : status == 'paused'
              ? 'paused'
              : 'resumed';
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('Weekly Box item $label.')),
      );
    } catch (error) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(friendlyAppError(error))),
      );
    }
  }

  Future<void> changeSchedule(CustomerProductSubscription plan) async {
    final selected = await showModalBottomSheet<int>(
      context: context,
      backgroundColor: FarmColors.card,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(30)),
      ),
      builder: (context) {
        return SafeArea(
          child: Padding(
            padding: const EdgeInsets.fromLTRB(18, 14, 18, 24),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Center(
                  child: Container(
                    width: 42,
                    height: 4,
                    decoration: BoxDecoration(
                      color: FarmColors.line,
                      borderRadius: BorderRadius.circular(99),
                    ),
                  ),
                ),
                const SizedBox(height: 18),
                const Text(
                  'Change repeat schedule',
                  style: TextStyle(
                    color: FarmColors.deepGreen,
                    fontSize: 21,
                    fontWeight: FontWeight.w900,
                  ),
                ),
                const SizedBox(height: 5),
                const Text(
                  'Choose how often HPJ should prepare a reminder for this item.',
                  style: TextStyle(
                    color: FarmColors.mutedText,
                    height: 1.3,
                    fontWeight: FontWeight.w600,
                  ),
                ),
                const SizedBox(height: 12),
                _PremiumScheduleChoice(
                  icon: Icons.calendar_view_week_outlined,
                  title: 'Every week',
                  subtitle: 'Best for everyday staples',
                  onTap: () => Navigator.pop(context, 7),
                ),
                _PremiumScheduleChoice(
                  icon: Icons.calendar_view_month_outlined,
                  title: 'Every 2 weeks',
                  subtitle: 'A flexible fortnightly rhythm',
                  onTap: () => Navigator.pop(context, 14),
                ),
                _PremiumScheduleChoice(
                  icon: Icons.event_repeat_outlined,
                  title: 'Every month',
                  subtitle: 'For occasional repeat items',
                  onTap: () => Navigator.pop(context, 30),
                ),
              ],
            ),
          ),
        );
      },
    );

    if (selected == null) return;

    try {
      await updateCustomerSubscriptionSchedule(
        subscription: plan,
        intervalDays: selected,
      );
      await refreshPlans();
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            'Schedule changed to ${repeatIntervalLabel(selected).toLowerCase()}.',
          ),
        ),
      );
    } catch (error) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(friendlyAppError(error))),
      );
    }
  }

  @override
  Widget build(BuildContext context) {
    final desktopWeb = HpjWebUi.isDesktop(context);

    return Scaffold(
      backgroundColor: FarmColors.background,
      appBar: AppBar(
        leading: const BackButton(),
        title: Text(
          desktopWeb ? 'Weekly Box & Repeats' : 'Weekly Box',
        ),
        backgroundColor: FarmColors.background,
        actions: [
          IconButton(
            tooltip: 'Build Weekly Box',
            onPressed: openWeeklyBoxBuilder,
            icon: const Icon(Icons.add_box_outlined),
          ),
        ],
      ),
      body: SafeArea(
        top: false,
        child: RefreshIndicator(
          onRefresh: refreshPlans,
          child: FutureBuilder<List<CustomerProductSubscription>>(
            future: plansFuture,
            builder: (context, snapshot) {
              final plans = snapshot.data ?? [];

              if (snapshot.connectionState == ConnectionState.waiting) {
                return const SkeletonList(count: 3, height: 116);
              }

              final activeCount = plans.where((plan) => plan.isActive).length;

              return ListView(
                physics: const AlwaysScrollableScrollPhysics(),
                padding: EdgeInsets.fromLTRB(
                  desktopWeb ? 22 : 18,
                  18,
                  desktopWeb ? 22 : 18,
                  120,
                ),
                children: [
                  if (desktopWeb)
                    _PremiumWebWeeklyBoxHero(
                      planCount: plans.length,
                      activeCount: activeCount,
                      onBuild: openWeeklyBoxBuilder,
                    )
                  else
                    buildWeeklyBoxBuilderCard(
                      hasPlans: plans.isNotEmpty,
                    ),
                  const SizedBox(height: 16),
                  if (plans.isNotEmpty) ...[
                    Row(
                      children: [
                        Expanded(
                          child: _PremiumWeeklyBoxMetric(
                            label: 'Items',
                            value: '${plans.length}',
                            icon: Icons.inventory_2_outlined,
                          ),
                        ),
                        const SizedBox(width: 10),
                        Expanded(
                          child: _PremiumWeeklyBoxMetric(
                            label: 'Active',
                            value: '$activeCount',
                            icon: Icons.event_available_outlined,
                          ),
                        ),
                      ],
                    ),
                    const SizedBox(height: 18),
                    const SectionHeader(
                      title: 'Your repeat items',
                      subtitle: 'Pause, resume or change the schedule anytime.',
                    ),
                    const SizedBox(height: 10),
                    ...plans.map(
                      (plan) => Padding(
                        padding: const EdgeInsets.only(bottom: 12),
                        child: _PremiumSubscriptionCard(
                          plan: plan,
                          onChangeSchedule: () => changeSchedule(plan),
                          onToggle: () => updateStatus(
                            plan,
                            plan.isActive ? 'paused' : 'active',
                          ),
                          onCancel: () => updateStatus(plan, 'cancelled'),
                        ),
                      ),
                    ),
                  ] else ...[
                    const FarmCard(
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Icon(Icons.event_repeat_outlined,
                              size: 42, color: FarmColors.green),
                          SizedBox(height: 12),
                          Text(
                            'No weekly items yet',
                            style: TextStyle(
                              color: FarmColors.deepGreen,
                              fontSize: 22,
                              fontWeight: FontWeight.w900,
                            ),
                          ),
                          SizedBox(height: 6),
                          Text(
                            'Pick the fresh items you want in your Weekly Box. You stay in control and confirm before each repeat order.',
                            style: TextStyle(
                              color: FarmColors.mutedText,
                              height: 1.35,
                              fontWeight: FontWeight.w700,
                            ),
                          ),
                        ],
                      ),
                    ),
                  ],
                ],
              );
            },
          ),
        ),
      ),
    );
  }
}

