// HPJ CHECKOUT SUCCESS NAVIGATION FIX — exact order + shop routing — 2026-09-13
class OrderSuccessScreen extends StatelessWidget {
  final String orderId;
  final double total;

  const OrderSuccessScreen({
    super.key,
    required this.orderId,
    required this.total,
  });

  String get shortOrderId {
    if (orderId.length <= 6) return orderId.toUpperCase();
    return orderId.substring(0, 6).toUpperCase();
  }

  Widget _receiptRow(String label, String value, {bool strong = false}) {
    return Padding(
      padding: const EdgeInsets.only(bottom: 10),
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Expanded(
            child: Text(
              label,
              style: TextStyle(
                color: strong ? FarmColors.ink : FarmColors.mutedText,
                fontWeight: strong ? FontWeight.w900 : FontWeight.w800,
              ),
            ),
          ),
          const SizedBox(width: 12),
          Flexible(
            child: Text(
              value,
              textAlign: TextAlign.right,
              style: TextStyle(
                color: strong ? FarmColors.green : FarmColors.ink,
                fontSize: strong ? 18 : 14,
                fontWeight: strong ? FontWeight.w900 : FontWeight.w800,
              ),
            ),
          ),
        ],
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: FarmColors.background,
      body: SafeArea(
        child: ListView(
          padding: const EdgeInsets.fromLTRB(22, 24, 22, 34),
          children: [
            const SizedBox(height: 18),
            Center(
              child: Container(
                height: 118,
                width: 118,
                decoration: BoxDecoration(
                  gradient: const LinearGradient(
                    begin: Alignment.topLeft,
                    end: Alignment.bottomRight,
                    colors: [FarmColors.green, FarmColors.primaryDark],
                  ),
                  shape: BoxShape.circle,
                  boxShadow: [
                    BoxShadow(
                      color: FarmColors.green.withOpacity(0.22),
                      blurRadius: 28,
                      offset: const Offset(0, 14),
                    ),
                  ],
                ),
                child: const Icon(
                  Icons.check_rounded,
                  color: Colors.white,
                  size: 68,
                ),
              ),
            ),
            const SizedBox(height: 28),
            const Text(
              'Order sent to the farm',
              textAlign: TextAlign.center,
              style: TextStyle(
                fontSize: 30,
                height: 1.02,
                fontWeight: FontWeight.w900,
                letterSpacing: -0.6,
              ),
            ),
            const SizedBox(height: 10),
            Text(
              'We received your order and will keep you updated as it moves through the harvest workflow.',
              textAlign: TextAlign.center,
              style: TextStyle(
                color: FarmColors.mutedText,
                fontSize: 15,
                height: 1.35,
                fontWeight: FontWeight.w700,
              ),
            ),
            const SizedBox(height: 24),
            FarmCard(
              padding: const EdgeInsets.all(18),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Row(
                    children: [
                      Container(
                        height: 42,
                        width: 42,
                        decoration: BoxDecoration(
                          color: FarmColors.lightGreen,
                          borderRadius: BorderRadius.circular(16),
                        ),
                        child: const Icon(
                          Icons.receipt_long_outlined,
                          color: FarmColors.green,
                        ),
                      ),
                      const SizedBox(width: 12),
                      Expanded(
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Text(
                              'Order #$shortOrderId',
                              style: const TextStyle(
                                fontSize: 18,
                                fontWeight: FontWeight.w900,
                              ),
                            ),
                            const SizedBox(height: 2),
                            const Text(
                              'Receipt and tracking are available in Orders.',
                              style: TextStyle(
                                color: FarmColors.mutedText,
                                fontWeight: FontWeight.w700,
                              ),
                            ),
                          ],
                        ),
                      ),
                    ],
                  ),
                  const SizedBox(height: 18),
                  _receiptRow('Status', 'Received'),
                  _receiptRow('Review', 'Farm review'),
                  const Divider(height: 22),
                  _receiptRow('Total', formatJmd(total), strong: true),
                ],
              ),
            ),
            const SizedBox(height: 16),
            Container(
              padding: const EdgeInsets.all(16),
              decoration: BoxDecoration(
                color: FarmColors.accentSoft.withOpacity(0.78),
                borderRadius: BorderRadius.circular(22),
                border: Border.all(color: FarmColors.accent.withOpacity(0.18)),
              ),
              child: const Row(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Icon(Icons.notifications_active_outlined,
                      color: FarmColors.warning),
                  SizedBox(width: 10),
                  Expanded(
                    child: Text(
                      'Tip: keep notifications on so you know when your order is ready for pickup or delivery.',
                      style: TextStyle(
                        fontWeight: FontWeight.w800,
                        height: 1.32,
                      ),
                    ),
                  ),
                ],
              ),
            ),
            const SizedBox(height: 28),
            PrimaryFarmButton(
              label: 'View Order',
              onPressed: () {
                // Checkout currently replaces CheckoutScreen with this success
                // screen. Popping to the first route loses the new order context
                // and can land on Customer Home (or another root page).
                //
                // Replace the success screen with the exact order that was just
                // created so the customer sees receipt, tracking, updates,
                // messages and Farm-to-Box data for the correct order.
                Navigator.of(context).pushReplacement<void, void>(
                  MaterialPageRoute<void>(
                    builder: (_) => OrderDetailsScreen(
                      orderId: orderId,
                      backToOrders: true,
                    ),
                  ),
                );
              },
            ),
            const SizedBox(height: 12),
            OutlinedButton.icon(
              onPressed: () {
                // Continue shopping must explicitly return to Customer Shop
                // instead of merely popping to whichever route happens to be
                // first in the stack.
                Navigator.of(context).pushAndRemoveUntil<void>(
                  MaterialPageRoute<void>(
                    builder: (_) => const MainNavigation(
                      initialIndex: 1,
                    ),
                  ),
                  (route) => false,
                );
              },
              icon: const Icon(Icons.storefront_outlined),
              label: const Text('Continue shopping'),
            ),
          ],
        ),
      ),
    );
  }
}

class _PremiumWebCheckoutMvpHero extends StatelessWidget {
