List<Widget> _buildHpjTermsPolicySections(String content) {
  final clean = content.trim();
  if (clean.isEmpty) {
    return const <Widget>[
      PolicySection(
        title: 'Terms & Conditions',
        body: _hpjDefaultTermsContent,
      ),
    ];
  }

  final blocks = clean
      .split(RegExp(r'\n\s*\n'))
      .map((block) => block.trim())
      .where((block) => block.isNotEmpty)
      .toList();

  if (blocks.isEmpty) {
    return <Widget>[
      PolicySection(title: 'Terms & Conditions', body: clean),
    ];
  }

  final output = <Widget>[];
  for (final block in blocks) {
    final lines = block
        .split('\n')
        .map((line) => line.trim())
        .where((line) => line.isNotEmpty)
        .toList();
    if (lines.isEmpty) continue;

    if (lines.length == 1) {
      output.add(
        PolicySection(
          title: output.isEmpty ? 'Terms & Conditions' : 'Additional terms',
          body: lines.first,
        ),
      );
      continue;
    }

    output.add(
      PolicySection(
        title: lines.first,
        body: lines.skip(1).join('\n'),
      ),
    );
  }

  return output;
}

