// ============================================================================
// HPJ PHASE 95 — PUBLIC QR FARM-TO-BOX TRACE PASSPORT
// ============================================================================
// A QR/token opens a privacy-safe public provenance story. It deliberately
// excludes customer identity, address, payment and private order information.
// ============================================================================

class HpjPublicTracePassportItem {
  final String productId;
  final String farmerProfileId;
  final String productName;
  final String imageUrl;
  final String unit;
  final double orderedQuantity;
  final String farmName;
  final String farmerName;
  final String parish;
  final DateTime? harvestStart;
  final DateTime? harvestEnd;
  final DateTime? expectedHarvestDate;
  final String latestStage;
  final String latestMessage;
  final String latestImageUrl;
  final DateTime? latestUpdateAt;
  final String lotCode;
  final String qualityGrade;
  final double packedQuantity;
  final DateTime? packedAt;
  final DateTime? receivedAt;
  final DateTime? completedAt;
  final String traceLevel;
  final String traceMessage;

  const HpjPublicTracePassportItem({
    required this.productId,
    required this.farmerProfileId,
    required this.productName,
    required this.imageUrl,
    required this.unit,
    required this.orderedQuantity,
    required this.farmName,
    required this.farmerName,
    required this.parish,
    required this.harvestStart,
    required this.harvestEnd,
    required this.expectedHarvestDate,
    required this.latestStage,
    required this.latestMessage,
    required this.latestImageUrl,
    required this.latestUpdateAt,
    required this.lotCode,
    required this.qualityGrade,
    required this.packedQuantity,
    required this.packedAt,
    required this.receivedAt,
    required this.completedAt,
    required this.traceLevel,
    required this.traceMessage,
  });

  factory HpjPublicTracePassportItem.fromSupabase(
    Map<String, dynamic> data,
  ) {
    double number(dynamic value) {
      if (value is num) return value.toDouble();
      return double.tryParse(value?.toString() ?? '') ?? 0;
    }

    return HpjPublicTracePassportItem(
      productId: (data['product_id'] ?? '').toString().trim(),
      farmerProfileId:
          (data['farmer_profile_id'] ?? '').toString().trim(),
      productName: (data['product_name'] ?? 'Fresh produce').toString().trim(),
      imageUrl: (data['image_url'] ?? '').toString().trim(),
      unit: (data['unit'] ?? 'unit').toString().trim(),
      orderedQuantity: number(data['ordered_quantity']),
      farmName: (data['farm_name'] ?? 'Jamaican farm').toString().trim(),
      farmerName: (data['farmer_name'] ?? '').toString().trim(),
      parish: (data['parish'] ?? '').toString().trim(),
      harvestStart: parseProductDate(data['harvest_start']),
      harvestEnd: parseProductDate(data['harvest_end']),
      expectedHarvestDate: parseProductDate(data['expected_harvest_date']),
      latestStage: (data['latest_stage'] ?? '').toString().trim().toLowerCase(),
      latestMessage: (data['latest_message'] ?? '').toString().trim(),
      latestImageUrl: (data['latest_image_url'] ?? '').toString().trim(),
      latestUpdateAt: parseProductDate(data['latest_update_at']),
      lotCode: (data['lot_code'] ?? '').toString().trim(),
      qualityGrade: (data['quality_grade'] ?? '').toString().trim(),
      packedQuantity: number(data['packed_quantity']),
      packedAt: parseProductDate(data['packed_at']),
      receivedAt: parseProductDate(data['received_at']),
      completedAt: parseProductDate(data['completed_at']),
      traceLevel: (data['trace_level'] ?? 'harvest_linked')
          .toString()
          .trim()
          .toLowerCase(),
      traceMessage: (data['trace_message'] ?? '').toString().trim(),
    );
  }

  bool get exactPackedLot => traceLevel == 'packed_lot_verified';

  String get farmDisplayName {
    final farm = farmName.trim();
    if (farm.isNotEmpty) return farm;
    final farmer = farmerName.trim();
    return farmer.isEmpty ? 'Jamaican farm' : farmer;
  }

  String get traceLabel {
    switch (traceLevel) {
      case 'packed_lot_verified':
        return 'Exact packing lot verified';
      case 'supply_verified':
        return 'HPJ supply verified';
      case 'field_verified':
        return 'Farm update verified';
      default:
        return 'GrowTogether harvest linked';
    }
  }
}

Future<List<HpjPublicTracePassportItem>> fetchHpjPublicTracePassport(
  String traceToken,
) async {
  final clean = traceToken.trim();
  if (clean.isEmpty) return const <HpjPublicTracePassportItem>[];

  try {
    final response = await supabase.rpc(
      'hpj_get_public_trace_passport_v2',
      params: {'p_trace_token': clean},
    );

    return (response as List)
        .map(
          (row) => HpjPublicTracePassportItem.fromSupabase(
            Map<String, dynamic>.from(row as Map),
          ),
        )
        .where((item) => item.productName.isNotEmpty)
        .toList(growable: false);
  } catch (error) {
    farmDebugLog('Public Farm-to-Box trace unavailable: $error');
    return const <HpjPublicTracePassportItem>[];
  }
}

Future<String?> fetchHpjMyOrderTraceToken(String orderId) async {
  final clean = orderId.trim();
  if (clean.isEmpty || supabase.auth.currentUser == null) return null;

  try {
    final response = await supabase.rpc(
      'hpj_get_my_order_trace_token',
      params: {'p_order_id': clean},
    );
    final token = response?.toString().trim() ?? '';
    return token.isEmpty || token == 'null' ? null : token;
  } catch (error) {
    farmDebugLog('Customer trace token unavailable: $error');
    return null;
  }
}

String? hpjPublicTraceUrlForCurrentHost(String traceToken) {
  final clean = traceToken.trim();
  if (!kIsWeb || clean.isEmpty) return null;

  final current = Uri.base;
  final scheme = current.scheme.toLowerCase();
  if ((scheme != 'http' && scheme != 'https') || current.host.isEmpty) {
    return null;
  }

  final uri = Uri(
    scheme: current.scheme,
    host: current.host,
    port: current.hasPort ? current.port : null,
    path: current.path.isEmpty ? '/' : current.path,
    queryParameters: <String, String>{'hpj_trace': clean},
  );

  return uri.toString();
}

String _hpjTraceStageLabel(String value) {
  final clean = value.trim().toLowerCase();
  switch (clean) {
    case 'planted':
      return 'Planted';
    case 'established':
      return 'Established';
    case 'growing':
      return 'Growing';
    case 'flowering':
      return 'Flowering';
    case 'fruiting':
      return 'Producing';
    case 'harvest_ready':
      return 'Harvest Ready';
    case 'harvesting':
      return 'Harvesting';
    case 'collected':
      return 'Collected';
    default:
      return 'Harvest Journey';
  }
}

String _hpjTraceQuantity(double value, String unit) {
  final amount = value == value.roundToDouble()
      ? value.toInt().toString()
      : value.toStringAsFixed(1);
  final cleanUnit = unit.trim().isEmpty ? 'unit' : unit.trim();
  return '$amount $cleanUnit';
}


// ============================================================================
// HPJ PHASE 96 — VERIFIED STORY + REORDER LOOP
// ============================================================================
// Converts the public trace passport into a retention loop without weakening
// Phase 95 privacy. Analytics record only trace/action/session relationships;
// HPJ does not collect an IP address, customer address or payment data here.
// ============================================================================

final String _hpjTraceSessionKey =
    '${DateTime.now().microsecondsSinceEpoch}-${Object().hashCode}';

Future<void> recordHpjTraceEngagement({
  required String traceToken,
  required String actionType,
  String productId = '',
  String farmerProfileId = '',
}) async {
  final token = traceToken.trim();
  final action = actionType.trim().toLowerCase();
  if (token.isEmpty || action.isEmpty) return;

  try {
    await supabase.rpc(
      'hpj_record_trace_engagement',
      params: <String, dynamic>{
        'p_trace_token': token,
        'p_action_type': action,
        'p_session_key': _hpjTraceSessionKey,
        'p_product_id': productId.trim().isEmpty ? null : productId.trim(),
        'p_farmer_profile_id': farmerProfileId.trim().isEmpty
            ? null
            : farmerProfileId.trim(),
      },
    );
  } catch (error) {
    // Engagement measurement must never block the public provenance story.
    farmDebugLog('Trace engagement skipped safely: $error');
  }
}

class HpjTraceFeedback {
  final int freshnessRating;
  final int packagingRating;
  final int overallRating;
  final String comment;
  final DateTime? updatedAt;

  const HpjTraceFeedback({
    required this.freshnessRating,
    required this.packagingRating,
    required this.overallRating,
    required this.comment,
    this.updatedAt,
  });

  factory HpjTraceFeedback.fromSupabase(Map<String, dynamic> data) {
    int rating(dynamic value) {
      final parsed = value is num
          ? value.toInt()
          : int.tryParse(value?.toString() ?? '') ?? 0;
      return parsed.clamp(0, 5).toInt();
    }

    return HpjTraceFeedback(
      freshnessRating: rating(data['freshness_rating']),
      packagingRating: rating(data['packaging_rating']),
      overallRating: rating(data['overall_rating']),
      comment: (data['comment'] ?? '').toString().trim(),
      updatedAt: parseProductDate(data['updated_at']),
    );
  }
}

Future<HpjTraceFeedback?> fetchMyHpjTraceFeedback(String traceToken) async {
  final token = traceToken.trim();
  if (token.isEmpty || supabase.auth.currentUser == null) return null;

  final response = await supabase.rpc(
    'hpj_get_my_trace_feedback',
    params: <String, dynamic>{'p_trace_token': token},
  );

  if (response is List && response.isNotEmpty) {
    return HpjTraceFeedback.fromSupabase(
      Map<String, dynamic>.from(response.first as Map),
    );
  }
  if (response is Map) {
    return HpjTraceFeedback.fromSupabase(
      Map<String, dynamic>.from(response),
    );
  }
  return null;
}

Future<void> saveMyHpjTraceFeedback({
  required String traceToken,
  required int freshnessRating,
  required int packagingRating,
  required int overallRating,
  required String comment,
}) async {
  if (supabase.auth.currentUser == null) {
    throw Exception('Please sign in to rate your Farm-to-Box experience.');
  }

  await supabase.rpc(
    'hpj_submit_my_trace_feedback',
    params: <String, dynamic>{
      'p_trace_token': traceToken.trim(),
      'p_freshness_rating': freshnessRating,
      'p_packaging_rating': packagingRating,
      'p_overall_rating': overallRating,
      'p_comment': comment.trim(),
    },
  );
}

Future<bool> _hpjTraceAddProductToBox(
  BuildContext context,
  Product product, {
  bool openBox = false,
}) async {
  if (!product.canAddToCart || product.stockQuantity <= 0) {
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(
          '${product.name} is not available for My Box right now. Check the farm page for current produce.',
        ),
      ),
    );
    return false;
  }

  final cart = OfflineCartStore.restore();
  final alreadyInBox = cart.where((item) => item.id == product.id).length;
  if (product.stockQuantity > 0 && alreadyInBox >= product.stockQuantity) {
    ScaffoldMessenger.of(context).showSnackBar(
      const SnackBar(
        content: Text('You already have the available quantity in My Box.'),
      ),
    );
    if (openBox && context.mounted) {
      await Navigator.of(context).push<void>(
        MaterialPageRoute<void>(
          builder: (_) => const MainNavigation(initialIndex: 2),
        ),
      );
    }
    return false;
  }

  cart.add(product);
  OfflineCartStore.save(cart);

  if (isLoggedIn) {
    try {
      await saveCartItemForCurrentUser(product);
    } catch (error) {
      farmDebugLog('Trace reorder saved-cart sync skipped: $error');
    }
  }

  if (!context.mounted) return true;

  ScaffoldMessenger.of(context).showSnackBar(
    SnackBar(content: Text('${product.name} added to My Box.')),
  );

  if (openBox) {
    await Navigator.of(context).push<void>(
      MaterialPageRoute<void>(
        builder: (_) => const MainNavigation(initialIndex: 2),
      ),
    );
  }
  return true;
}

class HpjPublicTracePassportScreen extends StatefulWidget {
  final String traceToken;

  const HpjPublicTracePassportScreen({
    super.key,
    required this.traceToken,
  });

  @override
  State<HpjPublicTracePassportScreen> createState() =>
      _HpjPublicTracePassportScreenState();
}

class _HpjPublicTracePassportScreenState
    extends State<HpjPublicTracePassportScreen> {
  late Future<List<HpjPublicTracePassportItem>> _future;
  List<HpjPublicTracePassportItem> _itemsCache =
      const <HpjPublicTracePassportItem>[];
  bool _scanRecorded = false;

  @override
  void initState() {
    super.initState();
    _future = fetchHpjPublicTracePassport(widget.traceToken);
  }

  Future<void> _refresh() async {
    final next = fetchHpjPublicTracePassport(widget.traceToken);
    if (mounted) setState(() => _future = next);
    await next;
  }

  Future<void> _openHpjHome() async {
    if (!kIsWeb) return;
    final current = Uri.base;
    final clean = current.replace(
      queryParameters: const <String, String>{},
      fragment: '',
    );
    await openExternalShareUrl(clean.toString());
  }

  Future<bool> _ensureSignedIn() async {
    if (isLoggedIn && supabase.auth.currentUser != null) return true;

    final authenticated = await Navigator.of(context).push<bool>(
      MaterialPageRoute<bool>(
        builder: (_) => const LoginScreen(returnToPrevious: true),
      ),
    );

    return context.mounted &&
        (authenticated == true ||
            (isLoggedIn && supabase.auth.currentUser != null));
  }

  Future<void> _recordTraceLoaded(
    List<HpjPublicTracePassportItem> items,
  ) async {
    final seen = <String>{};
    for (final item in items) {
      final key = '${item.farmerProfileId}|${item.productId}';
      if (!seen.add(key)) continue;
      await recordHpjTraceEngagement(
        traceToken: widget.traceToken,
        actionType: 'scan',
        productId: item.productId,
        farmerProfileId: item.farmerProfileId,
      );
    }
  }

  Future<void> _recordAcrossItems(String actionType) async {
    final items = _itemsCache;
    if (items.isEmpty) {
      await recordHpjTraceEngagement(
        traceToken: widget.traceToken,
        actionType: actionType,
      );
      return;
    }

    final seenFarmers = <String>{};
    var recorded = false;
    for (final item in items) {
      final farmerId = item.farmerProfileId.trim();
      if (farmerId.isNotEmpty && !seenFarmers.add(farmerId)) continue;
      recorded = true;
      await recordHpjTraceEngagement(
        traceToken: widget.traceToken,
        actionType: actionType,
        farmerProfileId: farmerId,
      );
    }

    if (!recorded) {
      await recordHpjTraceEngagement(
        traceToken: widget.traceToken,
        actionType: actionType,
      );
    }
  }

  Future<void> _buyAgain(HpjPublicTracePassportItem item) async {
    final productId = item.productId.trim();
    if (productId.isEmpty) return;

    unawaited(
      recordHpjTraceEngagement(
        traceToken: widget.traceToken,
        actionType: 'buy_again',
        productId: productId,
        farmerProfileId: item.farmerProfileId,
      ),
    );

    try {
      final product = await fetchProductById(productId);
      if (!mounted) return;

      if (product == null) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text('This produce is not in the current HPJ shop.'),
          ),
        );
        return;
      }

      await _hpjTraceAddProductToBox(context, product, openBox: true);
    } catch (error) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(friendlyAppError(error))),
      );
    }
  }

  Future<void> _openFarm(HpjPublicTracePassportItem item) async {
    final farmerId = item.farmerProfileId.trim();
    if (farmerId.isEmpty) return;

    unawaited(
      recordHpjTraceEngagement(
        traceToken: widget.traceToken,
        actionType: 'view_farm',
        productId: item.productId,
        farmerProfileId: farmerId,
      ),
    );

    await Navigator.of(context).push<void>(
      MaterialPageRoute<void>(
        builder: (_) => PublicFarmProfileScreen(
          farmerId: farmerId,
          sourceWorkspace: 'customer',
          onAddProduct: (product) {
            unawaited(_hpjTraceAddProductToBox(context, product));
          },
        ),
      ),
    );
  }

  Future<void> _shareStory() async {
    final url = hpjPublicTraceUrlForCurrentHost(widget.traceToken);
    if (url == null || url.trim().isEmpty) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Sharing is available from the HPJ website trace page.'),
        ),
      );
      return;
    }

    unawaited(_recordAcrossItems('share_story'));

    final text =
        'See the verified Jamaican farm-to-box story behind this HPJ harvest: $url';
    final whatsapp = 'https://wa.me/?text=${Uri.encodeComponent(text)}';
    final opened = await openExternalShareUrl(whatsapp);

    if (!opened && mounted) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Could not open sharing right now.')),
      );
    }
  }

  Future<void> _openMealPulse() async {
    final signedIn = await _ensureSignedIn();
    if (!signedIn || !mounted) return;

    unawaited(_recordAcrossItems('meal_pulse'));

    await Navigator.of(context).push<void>(
      MaterialPageRoute<void>(
        builder: (_) => const HpjMealPulseScreen(openComposerOnStart: true),
      ),
    );
  }

  Future<void> _rateExperience() async {
    final signedIn = await _ensureSignedIn();
    if (!signedIn || !mounted) return;

    try {
      final existing = await fetchMyHpjTraceFeedback(widget.traceToken);
      if (!mounted) return;

      final feedback = await showModalBottomSheet<HpjTraceFeedback>(
        context: context,
        isScrollControlled: true,
        useSafeArea: true,
        backgroundColor: Colors.transparent,
        builder: (_) => _HpjTraceFeedbackSheet(initial: existing),
      );

      if (feedback == null || !mounted) return;

      await saveMyHpjTraceFeedback(
        traceToken: widget.traceToken,
        freshnessRating: feedback.freshnessRating,
        packagingRating: feedback.packagingRating,
        overallRating: feedback.overallRating,
        comment: feedback.comment,
      );

      unawaited(_recordAcrossItems('feedback'));

      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Thanks — your Farm-to-Box feedback was saved.'),
        ),
      );
    } catch (error) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(friendlyAppError(error))),
      );
    }
  }

  @override
  Widget build(BuildContext context) {
    final desktop = kIsWeb && MediaQuery.sizeOf(context).width >= 900;

    return Scaffold(
      backgroundColor: const Color(0xFFF5F7F1),
      appBar: AppBar(
        automaticallyImplyLeading: false,
        backgroundColor: Colors.white,
        surfaceTintColor: Colors.white,
        titleSpacing: desktop ? 30 : 16,
        title: const Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(
              'The Harvest Place Ja',
              style: TextStyle(
                color: FarmColors.deepGreen,
                fontWeight: FontWeight.w900,
                fontSize: 17,
              ),
            ),
            Text(
              'Farm-to-Box Trace Passport',
              style: TextStyle(
                color: FarmColors.mutedText,
                fontWeight: FontWeight.w700,
                fontSize: 9.5,
              ),
            ),
          ],
        ),
        actions: [
          if (kIsWeb)
            Padding(
              padding: const EdgeInsets.only(right: 12),
              child: TextButton.icon(
                onPressed: _openHpjHome,
                icon: const Icon(Icons.storefront_outlined, size: 17),
                label: const Text('Visit HPJ'),
              ),
            ),
        ],
      ),
      body: RefreshIndicator(
        onRefresh: _refresh,
        child: FutureBuilder<List<HpjPublicTracePassportItem>>(
          future: _future,
          builder: (context, snapshot) {
            if (snapshot.connectionState == ConnectionState.waiting &&
                !snapshot.hasData) {
              return ListView(
                physics: const AlwaysScrollableScrollPhysics(),
                children: const [
                  SizedBox(height: 240),
                  Center(child: CircularProgressIndicator()),
                ],
              );
            }

            final items = snapshot.data ?? const <HpjPublicTracePassportItem>[];

            if (items.isEmpty) {
              return ListView(
                physics: const AlwaysScrollableScrollPhysics(),
                padding: const EdgeInsets.all(20),
                children: [
                  const SizedBox(height: 70),
                  Center(
                    child: ConstrainedBox(
                      constraints: const BoxConstraints(maxWidth: 520),
                      child: Container(
                        padding: const EdgeInsets.all(25),
                        decoration: BoxDecoration(
                          color: Colors.white,
                          borderRadius: BorderRadius.circular(26),
                          border: Border.all(color: FarmColors.line),
                        ),
                        child: const Column(
                          children: [
                            Icon(
                              Icons.qr_code_2_rounded,
                              color: FarmColors.green,
                              size: 44,
                            ),
                            SizedBox(height: 13),
                            Text(
                              'Trace passport unavailable',
                              textAlign: TextAlign.center,
                              style: TextStyle(
                                color: FarmColors.deepGreen,
                                fontSize: 19,
                                fontWeight: FontWeight.w900,
                              ),
                            ),
                            SizedBox(height: 7),
                            Text(
                              'This QR may be inactive, or HPJ has not published a Farm-to-Box trace for it yet.',
                              textAlign: TextAlign.center,
                              style: TextStyle(
                                color: FarmColors.mutedText,
                                height: 1.4,
                                fontWeight: FontWeight.w600,
                              ),
                            ),
                          ],
                        ),
                      ),
                    ),
                  ),
                ],
              );
            }

            _itemsCache = items;
            if (!_scanRecorded) {
              _scanRecorded = true;
              unawaited(_recordTraceLoaded(items));
            }

            final exactLots = items.where((item) => item.exactPackedLot).length;
            final farms = items
                .map((item) => item.farmDisplayName)
                .where((name) => name.trim().isNotEmpty)
                .toSet();

            return ListView(
              physics: const AlwaysScrollableScrollPhysics(),
              padding: EdgeInsets.fromLTRB(
                desktop ? 34 : 15,
                desktop ? 28 : 16,
                desktop ? 34 : 15,
                100,
              ),
              children: [
                Center(
                  child: ConstrainedBox(
                    constraints: const BoxConstraints(maxWidth: 1060),
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.stretch,
                      children: [
                        _HpjPublicTraceHero(
                          sourceCount: items.length,
                          farmCount: farms.length,
                          exactLotCount: exactLots,
                        ),
                        const SizedBox(height: 16),
                        if (desktop)
                          Wrap(
                            spacing: 14,
                            runSpacing: 14,
                            children: items
                                .map(
                                  (item) => SizedBox(
                                    width: 510,
                                    child: _HpjPublicTraceSourceCard(
                                      item: item,
                                      onBuyAgain: item.productId.isEmpty
                                          ? null
                                          : () => _buyAgain(item),
                                      onViewFarm: item.farmerProfileId.isEmpty
                                          ? null
                                          : () => _openFarm(item),
                                    ),
                                  ),
                                )
                                .toList(growable: false),
                          )
                        else
                          ...items.map(
                            (item) => Padding(
                              padding: const EdgeInsets.only(bottom: 12),
                              child: _HpjPublicTraceSourceCard(
                                item: item,
                                onBuyAgain: item.productId.isEmpty
                                    ? null
                                    : () => _buyAgain(item),
                                onViewFarm: item.farmerProfileId.isEmpty
                                    ? null
                                    : () => _openFarm(item),
                              ),
                            ),
                          ),
                        const SizedBox(height: 5),
                        _HpjTraceKeepStoryGoingCard(
                          onShare: _shareStory,
                          onMealPulse: _openMealPulse,
                          onRate: _rateExperience,
                        ),
                        const SizedBox(height: 12),
                        Container(
                          padding: const EdgeInsets.all(16),
                          decoration: BoxDecoration(
                            color: Colors.white,
                            borderRadius: BorderRadius.circular(20),
                            border: Border.all(color: FarmColors.line),
                          ),
                          child: const Row(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              Icon(
                                Icons.shield_outlined,
                                color: FarmColors.green,
                                size: 21,
                              ),
                              SizedBox(width: 10),
                              Expanded(
                                child: Text(
                                  'Privacy protected: this public trace shows food provenance only. Customer name, phone, address, payment details and private order information are never included.',
                                  style: TextStyle(
                                    color: FarmColors.mutedText,
                                    height: 1.45,
                                    fontSize: 10.2,
                                    fontWeight: FontWeight.w700,
                                  ),
                                ),
                              ),
                            ],
                          ),
                        ),
                      ],
                    ),
                  ),
                ),
              ],
            );
          },
        ),
      ),
    );
  }
}

class _HpjPublicTraceHero extends StatelessWidget {
  final int sourceCount;
  final int farmCount;
  final int exactLotCount;

  const _HpjPublicTraceHero({
    required this.sourceCount,
    required this.farmCount,
