class _HpjPublicTraceSourceCard extends StatelessWidget {
  final HpjPublicTracePassportItem item;
  final Future<void> Function()? onBuyAgain;
  final Future<void> Function()? onViewFarm;

  const _HpjPublicTraceSourceCard({
    required this.item,
    this.onBuyAgain,
    this.onViewFarm,
  });

  Widget _detail(IconData icon, String label, String value) {
    if (value.trim().isEmpty) return const SizedBox.shrink();
    return Padding(
      padding: const EdgeInsets.only(bottom: 8),
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Icon(icon, color: FarmColors.green, size: 17),
          const SizedBox(width: 8),
          Expanded(
            child: RichText(
              text: TextSpan(
                style: const TextStyle(
                  color: FarmColors.mutedText,
                  fontSize: 10.2,
                  height: 1.35,
                  fontWeight: FontWeight.w600,
                ),
                children: [
                  TextSpan(
                    text: '$label  ',
                    style: const TextStyle(
                      color: FarmColors.ink,
                      fontWeight: FontWeight.w900,
                    ),
                  ),
                  TextSpan(text: value),
                ],
              ),
            ),
          ),
        ],
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final image = item.latestImageUrl.isNotEmpty
        ? item.latestImageUrl
        : item.imageUrl;
    final harvestWindow = <String>[
      if (_hpjPassportDate(item.harvestStart).isNotEmpty)
        _hpjPassportDate(item.harvestStart),
      if (_hpjPassportDate(item.harvestEnd).isNotEmpty)
        _hpjPassportDate(item.harvestEnd),
    ].toSet().join(' – ');

    return Container(
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(24),
        border: Border.all(
          color: item.exactPackedLot
              ? FarmColors.green.withOpacity(.24)
              : FarmColors.line,
        ),
      ),
      clipBehavior: Clip.antiAlias,
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          if (image.isNotEmpty)
            SizedBox(
              height: 168,
              width: double.infinity,
              child: Image.network(
                image,
                fit: BoxFit.cover,
                errorBuilder: (_, __, ___) => Container(
                  color: FarmColors.primarySoft,
                  alignment: Alignment.center,
                  child: const Icon(
                    Icons.eco_outlined,
                    color: FarmColors.green,
                    size: 38,
                  ),
                ),
              ),
            ),
          Padding(
            padding: const EdgeInsets.all(17),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Row(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Expanded(
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Text(
                            item.productName,
                            style: const TextStyle(
                              color: FarmColors.deepGreen,
                              fontSize: 18,
                              fontWeight: FontWeight.w900,
                            ),
                          ),
                          const SizedBox(height: 3),
                          Text(
                            item.farmDisplayName,
                            style: const TextStyle(
                              color: FarmColors.ink,
                              fontSize: 11,
                              fontWeight: FontWeight.w800,
                            ),
                          ),
                        ],
                      ),
                    ),
                    Container(
                      padding: const EdgeInsets.symmetric(
                        horizontal: 9,
                        vertical: 6,
                      ),
                      decoration: BoxDecoration(
                        color: item.exactPackedLot
                            ? const Color(0xFFE8F4E8)
                            : FarmColors.primarySoft,
                        borderRadius: BorderRadius.circular(999),
                      ),
                      child: Text(
                        item.traceLabel,
                        style: const TextStyle(
                          color: FarmColors.deepGreen,
                          fontSize: 7.8,
                          fontWeight: FontWeight.w900,
                        ),
                      ),
                    ),
                  ],
                ),
                const SizedBox(height: 13),
                if (item.parish.isNotEmpty)
                  _detail(Icons.place_outlined, 'Parish', item.parish),
                if (harvestWindow.isNotEmpty)
                  _detail(Icons.calendar_month_outlined, 'Harvest', harvestWindow),
                if (item.latestStage.isNotEmpty)
                  _detail(
                    Icons.spa_outlined,
                    'Field stage',
                    _hpjTraceStageLabel(item.latestStage),
                  ),
                if (item.latestMessage.isNotEmpty)
                  _detail(
                    Icons.chat_bubble_outline,
                    'Farm update',
                    item.latestMessage,
                  ),
                if (item.completedAt != null)
                  _detail(
                    Icons.inventory_2_outlined,
                    'HPJ receiving',
                    _hpjPassportDate(item.completedAt),
                  ),
                if (item.exactPackedLot) ...[
                  _detail(
                    Icons.qr_code_2_rounded,
                    'Lot',
                    item.lotCode,
                  ),
                  if (item.qualityGrade.isNotEmpty)
