                  ),
                ),
                if (onBuyAgain != null || onViewFarm != null) ...[
                  const SizedBox(height: 12),
                  Row(
                    children: [
                      if (onBuyAgain != null)
                        Expanded(
                          child: FilledButton.icon(
                            onPressed: () async => onBuyAgain!(),
                            icon: const Icon(Icons.replay_rounded, size: 17),
                            label: const Text('Buy Again'),
                            style: FilledButton.styleFrom(
                              backgroundColor: FarmColors.deepGreen,
                            ),
                          ),
                        ),
                      if (onBuyAgain != null && onViewFarm != null)
                        const SizedBox(width: 8),
                      if (onViewFarm != null)
                        Expanded(
                          child: OutlinedButton.icon(
                            onPressed: () async => onViewFarm!(),
                            icon: const Icon(Icons.storefront_outlined, size: 17),
                            label: const Text('View / Follow Farm'),
                          ),
                        ),
                    ],
                  ),
                ],
              ],
            ),
          ),
        ],
      ),
    );
  }
}

class _HpjTraceKeepStoryGoingCard extends StatelessWidget {
  final Future<void> Function() onShare;
  final Future<void> Function() onMealPulse;
  final Future<void> Function() onRate;

  const _HpjTraceKeepStoryGoingCard({
    required this.onShare,
    required this.onMealPulse,
    required this.onRate,
  });

  Widget _action({
    required IconData icon,
    required String label,
    required Future<void> Function() onPressed,
    bool primary = false,
  }) {
    final child = Row(
      mainAxisSize: MainAxisSize.min,
      mainAxisAlignment: MainAxisAlignment.center,
      children: [
        Icon(icon, size: 17),
        const SizedBox(width: 7),
        Flexible(
          child: Text(
            label,
            overflow: TextOverflow.ellipsis,
            style: const TextStyle(fontWeight: FontWeight.w900),
          ),
        ),
      ],
    );

    return SizedBox(
      height: 42,
      child: primary
          ? FilledButton(
              onPressed: () async => onPressed(),
              style: FilledButton.styleFrom(
                backgroundColor: FarmColors.deepGreen,
              ),
              child: child,
            )
          : OutlinedButton(
              onPressed: () async => onPressed(),
              child: child,
            ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Container(
      padding: const EdgeInsets.all(17),
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(22),
        border: Border.all(color: FarmColors.green.withOpacity(.16)),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          const Text(
            'Keep the story going',
            style: TextStyle(
              color: FarmColors.deepGreen,
              fontSize: 17,
              fontWeight: FontWeight.w900,
            ),
          ),
          const SizedBox(height: 4),
          const Text(
            'Share the verified journey, show Jamaica what you cooked in Meal Pulse, or rate your Farm-to-Box experience.',
            style: TextStyle(
              color: FarmColors.mutedText,
              fontSize: 10.2,
              height: 1.4,
              fontWeight: FontWeight.w700,
            ),
          ),
          const SizedBox(height: 12),
          LayoutBuilder(
            builder: (context, constraints) {
              final wide = constraints.maxWidth >= 680;
              final buttons = <Widget>[
                _action(
                  icon: Icons.share_outlined,
                  label: 'Share Story',
                  onPressed: onShare,
                  primary: true,
                ),
                _action(
                  icon: Icons.restaurant_outlined,
                  label: 'Post to Meal Pulse',
                  onPressed: onMealPulse,
                ),
                _action(
                  icon: Icons.star_outline_rounded,
                  label: 'Rate Experience',
                  onPressed: onRate,
                ),
              ];

              if (wide) {
                return Row(
                  children: [
                    for (var i = 0; i < buttons.length; i++) ...[
                      Expanded(child: buttons[i]),
                      if (i != buttons.length - 1) const SizedBox(width: 8),
                    ],
                  ],
                );
              }

              return Column(
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  for (var i = 0; i < buttons.length; i++) ...[
                    buttons[i],
                    if (i != buttons.length - 1) const SizedBox(height: 8),
                  ],
                ],
              );
            },
          ),
          const SizedBox(height: 9),
          const Text(
            '“Buy Again” records a trace-page action, not a completed sale. Checkout remains the final source of truth for purchases.',
            style: TextStyle(
              color: FarmColors.mutedText,
              fontSize: 8.8,
              height: 1.35,
              fontWeight: FontWeight.w600,
            ),
          ),
        ],
      ),
    );
  }
}

class _HpjTraceFeedbackSheet extends StatefulWidget {
  final HpjTraceFeedback? initial;

  const _HpjTraceFeedbackSheet({this.initial});

  @override
  State<_HpjTraceFeedbackSheet> createState() => _HpjTraceFeedbackSheetState();
}

class _HpjTraceFeedbackSheetState extends State<_HpjTraceFeedbackSheet> {
  late int freshness;
  late int packaging;
  late int overall;
  late final TextEditingController commentController;

  @override
  void initState() {
    super.initState();
    freshness = widget.initial?.freshnessRating ?? 5;
    packaging = widget.initial?.packagingRating ?? 5;
    overall = widget.initial?.overallRating ?? 5;
    commentController = TextEditingController(text: widget.initial?.comment ?? '');
  }

  @override
  void dispose() {
    commentController.dispose();
    super.dispose();
  }

  Widget _ratingRow(
    String label,
    int value,
    ValueChanged<int> onChanged,
  ) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Text(
          label,
          style: const TextStyle(
            color: FarmColors.ink,
            fontSize: 12,
            fontWeight: FontWeight.w900,
          ),
        ),
        const SizedBox(height: 4),
        Wrap(
          spacing: 2,
          children: List<Widget>.generate(
            5,
            (index) {
              final rating = index + 1;
              return IconButton(
                tooltip: '$rating star${rating == 1 ? '' : 's'}',
                visualDensity: VisualDensity.compact,
                padding: EdgeInsets.zero,
                constraints: const BoxConstraints(minWidth: 36, minHeight: 36),
                onPressed: () => onChanged(rating),
                icon: Icon(
                  rating <= value
                      ? Icons.star_rounded
                      : Icons.star_border_rounded,
                  color: const Color(0xFFE4A915),
                  size: 28,
                ),
              );
            },
          ),
        ),
      ],
    );
  }

  @override
  Widget build(BuildContext context) {
    return Padding(
      padding: EdgeInsets.only(
        left: 14,
        right: 14,
        bottom: MediaQuery.viewInsetsOf(context).bottom + 14,
      ),
      child: Container(
        padding: const EdgeInsets.fromLTRB(18, 12, 18, 18),
        decoration: const BoxDecoration(
          color: Colors.white,
          borderRadius: BorderRadius.vertical(top: Radius.circular(28)),
        ),
        child: SingleChildScrollView(
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Center(
                child: Container(
                  width: 42,
                  height: 4,
                  decoration: BoxDecoration(
                    color: FarmColors.line,
                    borderRadius: BorderRadius.circular(999),
                  ),
                ),
              ),
              const SizedBox(height: 16),
              const Text(
                'Rate your Farm-to-Box experience',
                style: TextStyle(
                  color: FarmColors.deepGreen,
                  fontSize: 20,
                  fontWeight: FontWeight.w900,
                ),
              ),
              const SizedBox(height: 5),
              const Text(
                'Only the HPJ account that placed this order can save feedback. Ratings are used as aggregate experience signals.',
                style: TextStyle(
                  color: FarmColors.mutedText,
                  fontSize: 10.2,
                  height: 1.4,
                  fontWeight: FontWeight.w700,
                ),
              ),
              const SizedBox(height: 16),
              _ratingRow(
                'Freshness',
                freshness,
                (value) => setState(() => freshness = value),
              ),
              const SizedBox(height: 10),
              _ratingRow(
                'Packaging',
                packaging,
                (value) => setState(() => packaging = value),
              ),
              const SizedBox(height: 10),
              _ratingRow(
                'Overall experience',
                overall,
                (value) => setState(() => overall = value),
              ),
              const SizedBox(height: 12),
              TextField(
                controller: commentController,
                minLines: 3,
                maxLines: 5,
                maxLength: 600,
                textCapitalization: TextCapitalization.sentences,
                decoration: const InputDecoration(
                  labelText: 'Optional comment',
                  hintText: 'Tell HPJ what worked well or what could improve.',
                ),
              ),
              const SizedBox(height: 8),
              SizedBox(
                width: double.infinity,
                child: FilledButton.icon(
                  onPressed: () {
                    Navigator.of(context).pop(
                      HpjTraceFeedback(
                        freshnessRating: freshness,
                        packagingRating: packaging,
                        overallRating: overall,
                        comment: commentController.text.trim(),
                      ),
                    );
                  },
                  icon: const Icon(Icons.check_rounded),
                  label: const Text('Save Feedback'),
                  style: FilledButton.styleFrom(
                    backgroundColor: FarmColors.deepGreen,
                  ),
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}
// ============================================================================
// HPJ PHASE 97 COMPILE FIX — SHARED GROW INTELLIGENCE MODELS
//
// Admin + Farmer Phase 97 screens live in separate `part` files but share the
// same `harvest_place_app` library. These public model/service definitions are
// intentionally kept in a shared customer part so both screens can resolve the
// exact types at compile time.
//
// Social activity remains a soft signal. `hasVerifiedGap` only becomes true
// when server-returned verified demand exceeds HPJ-confirmed supply.
// ============================================================================

class HpjGrowIntelligenceSignal {
  final String cropName;
  final String category;
  final String parish;
  final String unit;
  final String? harvestCircleId;

  final int socialMentions;
  final int customerInterestCount;
  final int harvestCircleHouseholds;
  final int recentOrderCount;
  final int businessNeedCount;

  final double socialInterestScore;
  final double reservedDemand;
  final double retailOrderDemand;
  final double businessDemand;
  final double verifiedDemand;
  final double futureDemandQuantity;
  final double confirmedSupply;
  final double supplyGap;
  final double opportunityScore;

  final String confidence;
  final String signalStatus;
  final bool overplantGuard;
  final String recommendedAction;

  final DateTime? needWindowStart;
  final DateTime? needWindowEnd;

  const HpjGrowIntelligenceSignal({
    required this.cropName,
    required this.category,
    required this.parish,
    required this.unit,
    this.harvestCircleId,
    required this.socialMentions,
    required this.customerInterestCount,
    required this.harvestCircleHouseholds,
    required this.recentOrderCount,
    required this.businessNeedCount,
    required this.socialInterestScore,
    required this.reservedDemand,
    required this.retailOrderDemand,
    required this.businessDemand,
    required this.verifiedDemand,
    required this.futureDemandQuantity,
    required this.confirmedSupply,
    required this.supplyGap,
    required this.opportunityScore,
    required this.confidence,
    required this.signalStatus,
    required this.overplantGuard,
    required this.recommendedAction,
    required this.needWindowStart,
    required this.needWindowEnd,
  });

  factory HpjGrowIntelligenceSignal.fromSupabase(
    Map<String, dynamic> data,
  ) {
    double number(dynamic value) {
      if (value is num) return value.toDouble();
      return double.tryParse(value?.toString() ?? '') ?? 0;
    }

    int integer(dynamic value) {
      if (value is num) return value.toInt();
      return int.tryParse(value?.toString() ?? '') ?? 0;
    }

    bool boolean(dynamic value) {
      if (value is bool) return value;
      final clean = value?.toString().trim().toLowerCase() ?? '';
      return clean == 'true' || clean == 't' || clean == '1' || clean == 'yes';
    }

    String stringFrom(List<String> keys, {String fallback = ''}) {
      for (final key in keys) {
        final value = data[key];
        if (value == null) continue;
        final clean = value.toString().trim();
        if (clean.isNotEmpty) return clean;
      }
      return fallback;
    }

    dynamic valueFrom(List<String> keys) {
      for (final key in keys) {
        if (data.containsKey(key) && data[key] != null) return data[key];
      }
      return null;
    }

    DateTime? dateFrom(List<String> keys) {
      final value = valueFrom(keys);
      if (value == null) return null;
      if (value is DateTime) return value;
      return DateTime.tryParse(value.toString());
    }

    final verified = number(
      valueFrom(<String>[
        'future_demand_quantity',
        'verified_demand',
        'committed_demand',
        'confirmed_demand',
      ]),
    );

    final confirmed = number(
      valueFrom(<String>[
        'confirmed_supply_quantity',
        'confirmed_supply',
        'hpj_confirmed_supply',
        'verified_supply',
      ]),
    );

    final rawGap = valueFrom(<String>[
      'supply_gap',
      'verified_gap',
      'opportunity_gap',
    ]);

    final double gap = rawGap == null
        ? (verified - confirmed > 0 ? verified - confirmed : 0.0)
        : number(rawGap);

    final futureDemand = number(
      valueFrom(<String>[
        'future_demand_quantity',
        'verified_demand',
        'committed_demand',
        'confirmed_demand',
      ]),
    );

    final circleValue = stringFrom(<String>['harvest_circle_id']);
    final overplant = boolean(
      valueFrom(<String>[
        'overplant_guard',
        'overplant_warning',
        'social_only',
      ]),
    );
    final serverRecommendation = stringFrom(
      <String>['recommended_action', 'recommendation', 'action_text'],
    );
    final recommendation = serverRecommendation.isNotEmpty
        ? serverRecommendation
        : overplant
            ? 'Treat this as an interest signal only. Wait for stronger reserved or verified demand before expanding planting.'
            : gap > 0
                ? 'Review the verified demand gap and commit only the quantity your farm can confidently supply.'
                : 'Keep your expected harvest and available supply current so HPJ can match future demand accurately.';

    return HpjGrowIntelligenceSignal(
      cropName: stringFrom(
        <String>['crop_name', 'product_name', 'ingredient_name'],
        fallback: 'Produce',
      ),
      category: stringFrom(<String>['category']),
      parish: stringFrom(
        <String>['parish', 'demand_parish', 'region'],
        fallback: 'Jamaica',
      ),
      unit: stringFrom(<String>['unit'], fallback: 'lb'),
      harvestCircleId: circleValue.isEmpty ? null : circleValue,
      socialMentions: integer(
        valueFrom(<String>[
          'social_mentions',
          'meal_mentions',
          'meal_pulse_mentions',
        ]),
      ),
      customerInterestCount: integer(
        valueFrom(<String>[
          'customer_interest_count',
          'follow_count',
          'follower_count',
        ]),
      ),
      harvestCircleHouseholds: integer(
        valueFrom(<String>[
          'reserved_households',
          'harvest_circle_households',
          'household_count',
          'reservation_households',
        ]),
      ),
      recentOrderCount: integer(
        valueFrom(<String>[
          'recent_order_count',
          'retail_order_count',
          'customer_order_count',
        ]),
      ),
      businessNeedCount: integer(
        valueFrom(<String>[
          'business_need_count',
          'business_demand_count',
          'wholesale_need_count',
        ]),
      ),
      socialInterestScore: number(
        valueFrom(<String>[
          'social_interest_score',
          'social_score',
        ]),
      ),
      reservedDemand: number(
        valueFrom(<String>[
          'reserved_demand',
          'reserved_quantity',
          'harvest_circle_reserved',
        ]),
      ),
      retailOrderDemand: number(
        valueFrom(<String>[
          'recent_order_quantity',
          'retail_order_demand',
          'customer_order_demand',
          'retail_demand',
        ]),
      ),
      businessDemand: number(
        valueFrom(<String>[
          'business_demand',
          'wholesale_demand',
          'business_demand_quantity',
        ]),
      ),
      verifiedDemand: verified,
      futureDemandQuantity: futureDemand,
      confirmedSupply: confirmed,
      supplyGap: gap < 0 ? 0.0 : gap,
      opportunityScore: number(
        valueFrom(<String>[
          'opportunity_score',
          'demand_score',
          'score',
        ]),
      ),
      confidence: stringFrom(
        <String>['confidence', 'confidence_level', 'demand_confidence'],
        fallback: verified > 0 ? 'medium' : 'social',
      ).toLowerCase(),
      signalStatus: stringFrom(
        <String>['signal_status', 'status', 'opportunity_status'],
        fallback: gap > 0 ? 'gap' : 'watch',
      ).toLowerCase(),
      overplantGuard: overplant,
      recommendedAction: recommendation,
      needWindowStart: dateFrom(
        <String>['need_window_start', 'window_start', 'need_from'],
      ),
      needWindowEnd: dateFrom(
        <String>['need_window_end', 'window_end', 'need_by'],
      ),
    );
  }

  bool get hasVerifiedGap => verifiedDemand > 0 && supplyGap > 0.0001;

  bool get isCovered =>
      verifiedDemand > 0 && confirmedSupply + 0.0001 >= verifiedDemand;

  // Phase 97 compatibility aliases used by Farmer + Admin intelligence views.
  int get reservedHouseholds => harvestCircleHouseholds;
  double get reservedQuantity => reservedDemand;
  double get recentOrderQuantity => retailOrderDemand;
  double get businessDemandQuantity => businessDemand;
  double get confirmedSupplyQuantity => confirmedSupply;

  bool get isHighConfidence {
    final clean = confidence.trim().toLowerCase();
    return clean == 'high' ||
        clean == 'verified' ||
        clean == 'committed' ||
        clean == 'confirmed';
  }

  bool get isSocialOnly =>
      verifiedDemand <= 0.0001 &&
      (socialMentions > 0 || socialInterestScore > 0);

  String get confidenceLabel {
    switch (confidence.trim().toLowerCase()) {
      case 'high':
      case 'verified':
      case 'confirmed':
      case 'committed':
        return 'High';
      case 'medium':
      case 'moderate':
        return 'Medium';
      case 'low':
        return 'Low';
      case 'social':
      case 'social_only':
        return 'Social';
      default:
        return confidence.trim().isEmpty ? 'Watch' : confidence.trim();
    }
  }

  String get statusLabel {
    switch (signalStatus.trim().toLowerCase()) {
      case 'gap':
      case 'verified_gap':
      case 'opportunity':
        return 'Supply Opportunity';
      case 'covered':
        return 'Covered';
      case 'surplus':
        return 'Supply Ahead';
      case 'social':
      case 'social_only':
        return 'Social Interest';
      default:
        return 'Watch';
    }
  }
}

