Future<List<HpjGrowIntelligenceSignal>> fetchHpjGrowIntelligence({
  int historyDays = 30,
  int futureDays = 60,
  int limit = 40,
}) async {
  const rpcCandidates = <String>[
    'hpj_get_grow_intelligence',
    'hpj_grow_intelligence',
  ];

  Object? lastError;
  final safeHistoryDays = historyDays < 1 ? 1 : historyDays;
  final safeFutureDays = futureDays < 1 ? 1 : futureDays;
  final safeLimit = limit < 1 ? 1 : (limit > 500 ? 500 : limit);

  for (final rpcName in rpcCandidates) {
    try {
      dynamic response;
      try {
        response = await supabase.rpc(
          rpcName,
          params: <String, dynamic>{
            'p_days': safeHistoryDays,
            'p_future_days': safeFutureDays,
            'p_limit': safeLimit,
          },
        );
      } catch (parameterizedError) {
        // Compatibility with an older/no-argument RPC alias.
        response = await supabase.rpc(rpcName);
      }
      final rows = response is List ? response : const <dynamic>[];

      return rows
          .whereType<Map>()
          .map(
            (item) => HpjGrowIntelligenceSignal.fromSupabase(
              Map<String, dynamic>.from(item),
            ),
          )
          .toList(growable: false);
    } catch (error) {
      lastError = error;
    }
  }

  // Compatibility fallback if the Phase 97 migration exposed a view instead
  // of one of the RPC aliases above.
  const viewCandidates = <String>[
    'hpj_grow_intelligence',
    'hpj_grow_intelligence_view',
  ];

  for (final viewName in viewCandidates) {
    try {
      final response = await supabase.from(viewName).select().limit(safeLimit);
      return (response as List)
          .whereType<Map>()
          .map(
            (item) => HpjGrowIntelligenceSignal.fromSupabase(
              Map<String, dynamic>.from(item),
            ),
          )
          .toList(growable: false);
    } catch (error) {
      lastError = error;
    }
  }

  farmDebugLog(
    'Phase 97 grow intelligence unavailable safely: $lastError',
  );
  return const <HpjGrowIntelligenceSignal>[];
}

