class HpjMealCreatorProfile {
  final String userId;
  final String username;
  final String displayName;
  final String bio;
  final String avatarUrl;
  final int followerCount;
  final int followingCount;
  final int mealCount;
  final bool isFollowing;
  final bool isMe;

  const HpjMealCreatorProfile({
    required this.userId,
    required this.username,
    required this.displayName,
    required this.bio,
    required this.avatarUrl,
    required this.followerCount,
    required this.followingCount,
    required this.mealCount,
    required this.isFollowing,
    required this.isMe,
  });

  factory HpjMealCreatorProfile.fromSupabase(Map<String, dynamic> row) {
    int integer(dynamic value) {
      if (value is num) return value.toInt();
      return int.tryParse(value?.toString() ?? '') ?? 0;
    }

    bool truthy(dynamic value) {
      if (value is bool) return value;
      final clean = value?.toString().trim().toLowerCase() ?? '';
      return clean == 'true' || clean == '1' || clean == 't';
    }

    return HpjMealCreatorProfile(
      userId: (row['user_id'] ?? '').toString().trim(),
      username: (row['username'] ?? '').toString().trim(),
      displayName: (row['display_name'] ?? 'HPJ Member').toString().trim(),
      bio: (row['bio'] ?? '').toString().trim(),
      avatarUrl: (row['avatar_url'] ?? '').toString().trim(),
      followerCount: integer(row['follower_count']),
      followingCount: integer(row['following_count']),
      mealCount: integer(row['meal_count']),
      isFollowing: truthy(row['is_following']),
      isMe: truthy(row['is_me']),
    );
  }
}

