                        final columns = constraints.maxWidth >= 900 ? 3 : 2;
                        const gap = 10.0;
                        final width =
                            (constraints.maxWidth - gap * (columns - 1)) /
                                columns;

                        return Wrap(
                          spacing: gap,
                          runSpacing: gap,
                          children: meals.map((meal) {
                            return SizedBox(
                              width: width,
                              child: Container(
                                decoration: BoxDecoration(
                                  color: Colors.white,
                                  borderRadius: BorderRadius.circular(15),
                                  border: Border.all(color: FarmColors.line),
                                ),
                                clipBehavior: Clip.antiAlias,
                                child: Column(
                                  crossAxisAlignment: CrossAxisAlignment.start,
                                  children: [
                                    AspectRatio(
                                      aspectRatio: 4 / 3,
                                      child: meal.imageUrl.isNotEmpty
                                          ? Image.network(
                                              meal.imageUrl,
                                              fit: BoxFit.cover,
                                              errorBuilder: (_, __, ___) =>
                                                  Container(
                                                color: FarmColors.primarySoft,
                                                child: const Icon(
                                                  Icons.restaurant_rounded,
                                                ),
                                              ),
                                            )
                                          : Container(
                                              color: FarmColors.primarySoft,
                                              child: Icon(
                                                meal.videoUrl.isNotEmpty
                                                    ? Icons
                                                        .play_circle_outline_rounded
                                                    : Icons
                                                        .restaurant_rounded,
                                                color: FarmColors.primary,
                                              ),
                                            ),
                                    ),
                                    Padding(
                                      padding: const EdgeInsets.all(9),
                                      child: Text(
                                        meal.mealName,
                                        maxLines: 1,
                                        overflow: TextOverflow.ellipsis,
                                        style: const TextStyle(
                                          color: FarmColors.deepGreen,
                                          fontSize: 9.5,
                                          fontWeight: FontWeight.w900,
                                        ),
                                      ),
                                    ),
                                  ],
                                ),
                              ),
                            );
                          }).toList(growable: false),
                        );
                      },
                    );
                  },
                ),
              ],
            );
          },
        ),
      ),
    );
  }
}


Future<List<HpjMealPost>> fetchHpjMealCollectionPosts(
  String collectionId,
) async {
  try {
    final response = await supabase
        .from('hpj_meal_collection_items')
        .select(
          'created_at, '
          'hpj_meal_posts('
          'id,user_id,display_name,meal_name,caption,meal_type,parish,'
          'ingredients,image_url,video_url,allow_shop,created_at'
          ')',
        )
        .eq('collection_id', collectionId.trim())
        .order('created_at', ascending: false);

    final meals = <HpjMealPost>[];
    for (final raw in response as List) {
      final row = Map<String, dynamic>.from(raw as Map);
      final nested = row['hpj_meal_posts'];
      if (nested is! Map) continue;
      meals.add(
        HpjMealPost.fromSupabase(
          Map<String, dynamic>.from(nested),
        ),
      );
    }
    return meals;
  } catch (error) {
    farmDebugLog('Collection meals unavailable: $error');
    return const <HpjMealPost>[];
  }
}

class HpjMealCollectionScreen extends StatelessWidget {
  final HpjMealCollectionSummary collection;

  const HpjMealCollectionScreen({
    super.key,
    required this.collection,
  });

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: const Color(0xFFF7F8F3),
      appBar: AppBar(title: Text(collection.name)),
      body: FutureBuilder<List<HpjMealPost>>(
        future: fetchHpjMealCollectionPosts(collection.id),
        builder: (context, snapshot) {
          final meals = snapshot.data ?? const <HpjMealPost>[];

          if (snapshot.connectionState == ConnectionState.waiting &&
              snapshot.data == null) {
            return const Center(child: CircularProgressIndicator());
          }

          if (meals.isEmpty) {
            return const Center(
              child: Padding(
                padding: EdgeInsets.all(24),
                child: FarmEmptyState(
                  icon: Icons.collections_bookmark_outlined,
                  title: 'Collection is empty',
                  message: 'Saved Meal Pulse posts will appear here.',
                ),
              ),
            );
          }

          return ListView.separated(
            padding: const EdgeInsets.fromLTRB(16, 16, 16, 100),
            itemCount: meals.length,
            separatorBuilder: (_, __) => const SizedBox(height: 10),
            itemBuilder: (context, index) {
              final meal = meals[index];

              return FarmCard(
                padding: EdgeInsets.zero,
                child: Row(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    SizedBox(
                      width: 120,
                      height: 100,
                      child: meal.imageUrl.isNotEmpty
                          ? Image.network(
                              meal.imageUrl,
                              fit: BoxFit.cover,
                              errorBuilder: (_, __, ___) => Container(
                                color: FarmColors.primarySoft,
                                child: const Icon(
                                  Icons.restaurant_rounded,
                                  color: FarmColors.primary,
                                ),
                              ),
                            )
                          : Container(
                              color: FarmColors.primarySoft,
                              child: Icon(
                                meal.videoUrl.isNotEmpty
                                    ? Icons.play_circle_outline_rounded
                                    : Icons.restaurant_rounded,
                                color: FarmColors.primary,
                              ),
                            ),
                    ),
                    Expanded(
                      child: Padding(
                        padding: const EdgeInsets.all(12),
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Text(
                              meal.mealName,
                              style: const TextStyle(
                                color: FarmColors.ink,
                                fontSize: 12,
                                fontWeight: FontWeight.w900,
                              ),
                            ),
                            const SizedBox(height: 3),
                            Text(
                              meal.displayName,
                              style: const TextStyle(
                                color: FarmColors.mutedText,
                                fontSize: 8.8,
                                fontWeight: FontWeight.w700,
                              ),
                            ),
                            if (meal.ingredients.isNotEmpty) ...[
                              const SizedBox(height: 7),
                              Text(
                                meal.ingredients.take(4).join(' • '),
                                maxLines: 2,
                                overflow: TextOverflow.ellipsis,
                                style: const TextStyle(
                                  color: FarmColors.deepGreen,
                                  fontSize: 8.5,
                                  height: 1.3,
                                  fontWeight: FontWeight.w700,
                                ),
                              ),
                            ],
                          ],
                        ),
                      ),
                    ),
                  ],
                ),
              );
            },
          );
        },
      ),
    );
  }
}
